insert into public.destinations (id, name, description, cover_photo, sort_order, published) values ('hurghada', '{"en":"Hurghada","ar":"الغردقة","fr":"Hurghada","de":"Hurghada"}'::jsonb, '{"en":"Egypt''s premier Red Sea resort destination — a city that lives on sun, sea, and some of the world''s finest coral reefs. From the azure waters of Orange Bay to the star-filled Eastern Desert, Hurghada offers an extraordinary range of experiences year-round.","ar":"أشهر منتجعات البحر الأحمر في مصر، مدينة تعيش على الشمس والبحر وأجمل الشعاب المرجانية في العالم. من مياه أورانج باي الفيروزية إلى سماء الصحراء الشرقية المرصّعة بالنجوم، تقدّم الغردقة تجارب مميزة طوال العام.","fr":"La grande station balnéaire égyptienne de la mer Rouge : soleil, mer et certains des plus beaux récifs coralliens du monde. Des eaux turquoise d''Orange Bay au ciel étoilé du désert oriental, Hurghada offre des expériences extraordinaires toute l''année.","de":"Ägyptens führender Badeort am Roten Meer – Sonne, Meer und einige der schönsten Korallenriffe der Welt. Vom türkisblauen Wasser der Orange Bay bis zum Sternenhimmel der Östlichen Wüste bietet Hurghada das ganze Jahr über außergewöhnliche Erlebnisse."}'::jsonb, 'https://images.unsplash.com/photo-1583157048761-ac1dba033233?w=1600&h=900&fit=crop&auto=format&q=80', 0, true)
insert into public.destinations (id, name, description, cover_photo, sort_order, published) values ('sharm', '{"en":"Sharm El Sheikh","ar":"شرم الشيخ","fr":"Charm el-Cheikh","de":"Scharm El-Scheich"}'::jsonb, '{"en":"Perched at the southern tip of the Sinai Peninsula where two gulfs meet, Sharm el-Sheikh is home to the legendary reefs of Ras Mohammed National Park and a striking desert landscape that frames the Red Sea in every direction.","ar":"في الطرف الجنوبي لشبه جزيرة سيناء حيث يلتقي الخليجان، تضم شرم الشيخ الشعاب الأسطورية لمحمية رأس محمد ومناظر صحراوية خلابة تحيط بالبحر الأحمر من كل اتجاه.","fr":"À la pointe sud de la péninsule du Sinaï, là où se rejoignent deux golfes, Charm el-Cheikh abrite les récifs légendaires du parc national de Ras Mohammed et un paysage désertique saisissant qui encadre la mer Rouge.","de":"An der Südspitze der Sinai-Halbinsel, wo zwei Golfe aufeinandertreffen, liegen die legendären Riffe des Ras-Mohammed-Nationalparks und eine beeindruckende Wüstenlandschaft rund um das Rote Meer."}'::jsonb, 'https://images.unsplash.com/photo-1700482323555-182b61c90794?w=1600&h=900&fit=crop&auto=format&q=80', 1, true)
insert into public.destinations (id, name, description, cover_photo, sort_order, published) values ('cairo', '{"en":"Cairo","ar":"القاهرة","fr":"Le Caire","de":"Kairo"}'::jsonb, '{"en":"The city of a thousand minarets — ancient and electric, chaotic and magnificent. Cairo is home to the last surviving wonder of the ancient world, a new museum of global importance, and one of the most layered and fascinating urban experiences on earth.","ar":"مدينة الألف مئذنة، عريقة ونابضة بالحياة. تضم القاهرة آخر عجائب الدنيا السبع الباقية، ومتحفًا جديدًا ذا أهمية عالمية، وواحدة من أغنى التجارب الحضرية على وجه الأرض.","fr":"La ville aux mille minarets, antique et électrique. Le Caire abrite la dernière merveille du monde antique encore debout, un nouveau musée d''importance mondiale et l''une des expériences urbaines les plus fascinantes de la planète.","de":"Die Stadt der tausend Minarette – uralt und voller Energie. Kairo beherbergt das letzte erhaltene Weltwunder der Antike, ein neues Museum von Weltrang und eines der faszinierendsten Stadterlebnisse der Welt."}'::jsonb, 'https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=1600&h=900&fit=crop&auto=format&q=80', 2, true)
insert into public.destinations (id, name, description, cover_photo, sort_order, published) values ('luxor', '{"en":"Luxor","ar":"الأقصر","fr":"Louxor","de":"Luxor"}'::jsonb, '{"en":"Ancient Thebes — once the world''s greatest city, now the open-air museum of a civilization. Both banks of the Nile here are saturated with temples, tombs, and monuments spanning 1,500 years of pharaonic rule. Nowhere on earth concentrates this much antiquity.","ar":"طيبة القديمة، أعظم مدن العالم يومًا، وهي اليوم متحف مفتوح لحضارة كاملة. ضفتا النيل هنا مليئتان بالمعابد والمقابر والآثار الممتدة عبر 1500 عام من حكم الفراعنة.","fr":"L''antique Thèbes, jadis la plus grande ville du monde, aujourd''hui un musée à ciel ouvert. Les deux rives du Nil regorgent de temples, de tombeaux et de monuments couvrant 1 500 ans de règne pharaonique.","de":"Das antike Theben – einst die größte Stadt der Welt, heute ein Freilichtmuseum einer ganzen Zivilisation. Beide Nilufer sind voller Tempel, Gräber und Monumente aus 1.500 Jahren Pharaonenherrschaft."}'::jsonb, 'https://images.unsplash.com/photo-1777672351192-a7220589c25e?w=1600&h=900&fit=crop&auto=format&q=80', 3, true)
insert into public.destinations (id, name, description, cover_photo, sort_order, published) values ('aswan', '{"en":"Aswan","ar":"أسوان","fr":"Assouan","de":"Assuan"}'::jsonb, '{"en":"Where Egypt slows to the rhythm of the Nile. Aswan is Egypt''s most beautiful city — granite islands, sailing feluccas, Nubian villages painted in vivid colours, and some of ancient Egypt''s most extraordinary monuments within easy reach.","ar":"حيث تهدأ مصر على إيقاع النيل. أسوان أجمل مدن مصر: جزر من الجرانيت، وفلوكات شراعية، وقرى نوبية بألوان زاهية، وبعض أروع آثار مصر القديمة على مقربة منك.","fr":"Là où l''Égypte ralentit au rythme du Nil. Assouan est la plus belle ville d''Égypte : îles de granit, felouques, villages nubiens aux couleurs vives et monuments extraordinaires à portée de main.","de":"Hier passt sich Ägypten dem Rhythmus des Nils an. Assuan ist Ägyptens schönste Stadt – Granitinseln, Feluken, farbenfrohe nubische Dörfer und außergewöhnliche Monumente in greifbarer Nähe."}'::jsonb, 'https://images.unsplash.com/photo-1684100096410-fd39cdff91a3?w=1600&h=900&fit=crop&auto=format&q=80', 4, true)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('hurg-1', 'hurghada', 'Desert & Adventure', 890, 445, 5, array['English', 'Arabic', 'German']::text[], true, true, 'Desert Wings Egypt', array['https://images.unsplash.com/photo-1577085375786-edb0f45560aa?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1713021714419-ca3a7bc12f00?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.9, 312, '[]'::jsonb, '{"en":{"title":"Stargazing Desert Safari","duration":"5 hours","description":"Escape the city lights for an unforgettable night under the Sahara sky. This intimate stargazing experience takes you deep into the Eastern Desert where expert astronomers guide you through constellations, planets, and galaxies visible only in Egypt''s exceptional dark skies. Around a campfire with traditional Bedouin tea, you''ll witness a sky unlike anything you''ve seen before.","highlights":["Ride in a 4x4 jeep deep into the Eastern Desert, far from light pollution","Professional astronomer leads a live tour of the night sky","Powerful telescope viewing of planets, nebulae, and star clusters","Traditional Bedouin campfire with tea, coffee, and light snacks","Maximum group size of 8 for an intimate, personal experience","Photography tips for capturing the Milky Way"],"itinerary":[{"time":"19:00","activity":"Hotel pickup from Hurghada and Sahl Hasheesh"},{"time":"20:00","activity":"Arrive at base camp — welcome drinks and orientation"},{"time":"20:30","activity":"Guided star tour begins — naked-eye constellations and storytelling"},{"time":"21:30","activity":"Telescope session with deep-sky objects and planets"},{"time":"22:30","activity":"Campfire with Bedouin snacks and hot drinks"},{"time":"23:30","activity":"Return transfer to hotel"}],"included":["Hotel pickup and drop-off","Private 4x4 desert transport","Professional English-speaking astronomer","High-powered telescope","Bedouin tea, coffee, and light snacks","Warm blankets for the desert chill"],"excluded":["Gratuities (recommended)","Alcoholic beverages","Personal travel insurance"],"meetingPoint":"Your hotel lobby in Hurghada, Sahl Hasheesh, or El Gouna. Exact pickup time confirmed 24 hours before.","whatToBring":["Warm layer or light jacket (desert nights are cool)","Comfortable closed-toe shoes","Camera or smartphone for astrophotography","Personal water bottle"],"cancellationPolicy":"Free cancellation up to 24 hours before the experience starts. No refund for cancellations within 24 hours or no-shows.","faq":[{"question":"Is this experience suitable for children?","answer":"Yes, this experience is family-friendly and suitable for children aged 6 and above. Young stargazers often find it magical."},{"question":"What happens if the weather is bad?","answer":"In the unlikely event of clouds, we will reschedule at no charge or offer a full refund. Hurghada has over 330 clear nights per year."},{"question":"How far is the drive into the desert?","answer":"Approximately 45 minutes from Hurghada center. The road is smooth and the 4x4 handles all terrain comfortably."}]},"ar":{"title":"سفاري الصحراء لمشاهدة النجوم","duration":"5 ساعات","description":"ابتعد عن أضواء المدينة واستمتع بليلة لا تُنسى تحت سماء الصحراء. تأخذك هذه التجربة الهادئة إلى عمق الصحراء الشرقية حيث يرشدك فلكيون متخصصون بين الأبراج والكواكب والمجرات التي لا تظهر بهذا الوضوح إلا في سماء مصر الصافية. وحول نار المخيم مع الشاي البدوي الأصيل، ستشاهد سماءً لم ترَ مثلها من قبل.","highlights":["رحلة بسيارة دفع رباعي إلى عمق الصحراء الشرقية بعيدًا عن التلوث الضوئي","فلكي محترف يقدم جولة حية في سماء الليل","رصد الكواكب والسدم والعناقيد النجمية بتلسكوب قوي","نار مخيم بدوية مع الشاي والقهوة ووجبات خفيفة","مجموعة لا تتجاوز 8 أشخاص لتجربة هادئة وشخصية","نصائح لتصوير مجرة درب التبانة"],"itinerary":[{"time":"19:00","activity":"الاستلام من الفندق في الغردقة وسهل حشيش"},{"time":"20:00","activity":"الوصول إلى المخيم — مشروبات ترحيبية وتعريف بالبرنامج"},{"time":"20:30","activity":"بداية جولة النجوم — الأبراج بالعين المجردة وحكاياتها"},{"time":"21:30","activity":"جلسة التلسكوب لرصد الكواكب والأجرام البعيدة"},{"time":"22:30","activity":"نار المخيم مع وجبات بدوية ومشروبات ساخنة"},{"time":"23:30","activity":"العودة إلى الفندق"}],"included":["الاستلام والتوصيل من وإلى الفندق","سيارة دفع رباعي خاصة في الصحراء","فلكي محترف يتحدث الإنجليزية","تلسكوب عالي الدقة","شاي وقهوة بدوية ووجبات خفيفة","بطاطين دافئة لبرودة الصحراء"],"excluded":["الإكراميات (يُنصح بها)","المشروبات الكحولية","التأمين الشخصي على السفر"],"meetingPoint":"بهو فندقك في الغردقة أو سهل حشيش أو الجونة. يتم تأكيد موعد الاستلام قبلها بـ 24 ساعة.","whatToBring":["ملابس دافئة أو جاكيت خفيف (ليالي الصحراء باردة)","حذاء مريح مغلق","كاميرا أو هاتف لتصوير السماء","زجاجة مياه شخصية"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل بداية التجربة. لا يُسترد المبلغ عند الإلغاء خلال 24 ساعة أو عدم الحضور.","faq":[{"question":"هل التجربة مناسبة للأطفال؟","answer":"نعم، التجربة مناسبة للعائلات وللأطفال من سن 6 سنوات فأكثر، وغالبًا ما يجدها الصغار ساحرة."},{"question":"ماذا يحدث إذا كان الطقس سيئًا؟","answer":"في حالة وجود سحب، نعيد جدولة الرحلة مجانًا أو نرد المبلغ كاملًا. تتمتع الغردقة بأكثر من 330 ليلة صافية في السنة."},{"question":"كم تبعد المسافة داخل الصحراء؟","answer":"حوالي 45 دقيقة من وسط الغردقة. الطريق ممهد وسيارة الدفع الرباعي تسير بسهولة على كل التضاريس."}]},"fr":{"title":"Safari dans le désert sous les étoiles","duration":"5 heures","description":"Échappez aux lumières de la ville pour une nuit inoubliable sous le ciel du désert. Cette expérience intimiste vous emmène au cœur du désert oriental, où des astronomes passionnés vous guident parmi les constellations, les planètes et les galaxies que seul le ciel exceptionnellement pur de l''Égypte permet d''admirer. Autour d''un feu de camp avec un thé bédouin traditionnel, vous découvrirez un ciel comme vous n''en avez jamais vu.","highlights":["Trajet en 4x4 au cœur du désert oriental, loin de toute pollution lumineuse","Un astronome professionnel commente le ciel nocturne en direct","Observation de planètes, nébuleuses et amas d''étoiles au télescope","Feu de camp bédouin avec thé, café et collations","Groupe de 8 personnes maximum pour une expérience intime","Conseils pour photographier la Voie lactée"],"itinerary":[{"time":"19:00","activity":"Prise en charge à l''hôtel à Hurghada et Sahl Hasheesh"},{"time":"20:00","activity":"Arrivée au camp — boissons de bienvenue et présentation"},{"time":"20:30","activity":"Début de la visite des étoiles — constellations à l''œil nu et récits"},{"time":"21:30","activity":"Séance au télescope : objets du ciel profond et planètes"},{"time":"22:30","activity":"Feu de camp avec collations bédouines et boissons chaudes"},{"time":"23:30","activity":"Retour à l''hôtel"}],"included":["Prise en charge et retour à l''hôtel","Transport privé en 4x4 dans le désert","Astronome professionnel anglophone","Télescope haute puissance","Thé, café bédouin et collations","Couvertures chaudes pour la fraîcheur du désert"],"excluded":["Pourboires (recommandés)","Boissons alcoolisées","Assurance voyage personnelle"],"meetingPoint":"Hall de votre hôtel à Hurghada, Sahl Hasheesh ou El Gouna. L''heure exacte est confirmée 24 heures avant.","whatToBring":["Une couche chaude ou une veste légère (les nuits sont fraîches)","Chaussures fermées confortables","Appareil photo ou smartphone pour l''astrophotographie","Gourde personnelle"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant le début. Aucun remboursement en cas d''annulation tardive ou d''absence.","faq":[{"question":"Cette expérience convient-elle aux enfants ?","answer":"Oui, elle convient aux familles et aux enfants à partir de 6 ans. Les jeunes astronomes la trouvent souvent magique."},{"question":"Que se passe-t-il en cas de mauvais temps ?","answer":"Dans le cas peu probable de nuages, nous reportons gratuitement ou remboursons intégralement. Hurghada compte plus de 330 nuits claires par an."},{"question":"Quelle est la durée du trajet dans le désert ?","answer":"Environ 45 minutes depuis le centre de Hurghada. La route est confortable et le 4x4 passe partout."}]},"de":{"title":"Sternbeobachtungs-Wüstensafari","duration":"5 Stunden","description":"Lassen Sie die Lichter der Stadt hinter sich und erleben Sie eine unvergessliche Nacht unter dem Wüstenhimmel. Dieses intime Erlebnis führt Sie tief in die Östliche Wüste, wo erfahrene Astronomen Sie durch Sternbilder, Planeten und Galaxien führen, die nur Ägyptens außergewöhnlich dunkler Himmel so klar zeigt. Am Lagerfeuer mit traditionellem Beduinentee sehen Sie einen Himmel, wie Sie ihn noch nie gesehen haben.","highlights":["Fahrt im 4x4-Jeep tief in die Östliche Wüste, fernab von Lichtverschmutzung","Ein professioneller Astronom führt live durch den Nachthimmel","Beobachtung von Planeten, Nebeln und Sternhaufen mit leistungsstarkem Teleskop","Beduinen-Lagerfeuer mit Tee, Kaffee und kleinen Snacks","Maximal 8 Teilnehmer für ein persönliches Erlebnis","Tipps zum Fotografieren der Milchstraße"],"itinerary":[{"time":"19:00","activity":"Abholung vom Hotel in Hurghada und Sahl Hasheesh"},{"time":"20:00","activity":"Ankunft im Camp — Begrüßungsgetränke und Einführung"},{"time":"20:30","activity":"Beginn der Sternentour — Sternbilder mit bloßem Auge und Geschichten"},{"time":"21:30","activity":"Teleskop-Session mit Deep-Sky-Objekten und Planeten"},{"time":"22:30","activity":"Lagerfeuer mit Beduinen-Snacks und heißen Getränken"},{"time":"23:30","activity":"Rücktransfer zum Hotel"}],"included":["Abholung und Rücktransfer vom Hotel","Privater 4x4-Transport in der Wüste","Professioneller, englischsprachiger Astronom","Leistungsstarkes Teleskop","Beduinentee, Kaffee und kleine Snacks","Warme Decken gegen die Wüstenkühle"],"excluded":["Trinkgelder (empfohlen)","Alkoholische Getränke","Persönliche Reiseversicherung"],"meetingPoint":"Lobby Ihres Hotels in Hurghada, Sahl Hasheesh oder El Gouna. Die genaue Abholzeit wird 24 Stunden vorher bestätigt.","whatToBring":["Warme Schicht oder leichte Jacke (Wüstennächte sind kühl)","Bequeme, geschlossene Schuhe","Kamera oder Smartphone für Astrofotografie","Eigene Trinkflasche"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor Beginn. Keine Erstattung bei späterer Stornierung oder Nichterscheinen.","faq":[{"question":"Ist das Erlebnis für Kinder geeignet?","answer":"Ja, es ist familienfreundlich und für Kinder ab 6 Jahren geeignet. Junge Sternengucker finden es oft magisch."},{"question":"Was passiert bei schlechtem Wetter?","answer":"Im unwahrscheinlichen Fall von Wolken verschieben wir kostenlos oder erstatten den vollen Betrag. Hurghada hat über 330 klare Nächte im Jahr."},{"question":"Wie weit ist die Fahrt in die Wüste?","answer":"Etwa 45 Minuten vom Zentrum Hurghadas. Die Strecke ist angenehm und der 4x4 meistert jedes Gelände."}]}}'::jsonb, null, true, 4, 11, true, true, false, 0)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('hurg-2', 'hurghada', 'Water Sports', 650, 325, 7, array['English', 'Arabic', 'Russian', 'Italian']::text[], true, true, 'Red Sea Adventures', array['https://images.unsplash.com/photo-1700482323555-182b61c90794?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1583157048761-ac1dba033233?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1638123657021-f9aca72f8caf?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1625754884730-ba1e2eaafe91?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.7, 891, '[]'::jsonb, '{"en":{"title":"Orange Bay Snorkeling Cruise","duration":"7 hours","description":"Cruise to the pristine shores of Orange Bay, one of the most stunning beaches in the Red Sea. Snorkel vibrant coral gardens teeming with tropical fish, relax on a white-sand beach that sees fewer crowds than the main tourist areas, and enjoy a freshly prepared lunch on board. This full-day boat trip is the definitive Red Sea experience.","highlights":["Visit Orange Bay, Giftun Island — some of Egypt''s most pristine beaches","Two snorkeling stops over thriving coral reef ecosystems","Freshly prepared Egyptian buffet lunch on board","Glass-bottom boat viewing for non-swimmers","Free time to swim, sunbathe, and explore","Professional snorkeling equipment included"],"itinerary":[{"time":"08:00","activity":"Hotel pickup and transfer to Hurghada Marina"},{"time":"09:00","activity":"Depart marina — welcome drinks and orientation"},{"time":"10:00","activity":"First snorkeling stop at coral reef"},{"time":"11:30","activity":"Arrive at Orange Bay beach — free beach time"},{"time":"13:30","activity":"Buffet lunch served on board"},{"time":"14:30","activity":"Second snorkeling stop at Giftun Island"},{"time":"16:00","activity":"Return cruise to Hurghada Marina"},{"time":"17:00","activity":"Hotel drop-off"}],"included":["Hotel transfers","Full-day boat trip","Snorkeling equipment (mask, fins, vest)","Egyptian buffet lunch","Soft drinks and water","National park entry fees"],"excluded":["Alcoholic beverages (available for purchase)","Underwater camera rental","Gratuities"],"meetingPoint":"Hotel pickup throughout Hurghada, El Gouna, and Sahl Hasheesh.","whatToBring":["Swimwear and towel","Sunscreen (reef-safe preferred)","Sunglasses and hat","Change of clothes","Underwater camera (optional)"],"cancellationPolicy":"Free cancellation up to 24 hours before departure. In case of bad sea conditions, a full refund or reschedule is offered.","faq":[{"question":"Can non-swimmers participate?","answer":"Absolutely. Life vests are provided and the glass-bottom boat section is perfect for those who prefer not to snorkel."},{"question":"Is lunch suitable for vegetarians?","answer":"Yes, the buffet includes multiple vegetarian options. Please notify us of any dietary requirements when booking."}]},"ar":{"title":"رحلة سنوركلينج إلى أورانج باي","duration":"7 ساعات","description":"أبحر إلى شواطئ أورانج باي البكر، أحد أجمل شواطئ البحر الأحمر. مارس السنوركلينج بين حدائق المرجان الملونة المليئة بالأسماك الاستوائية، واسترخِ على شاطئ رملي أبيض أقل ازدحامًا من المناطق السياحية المعتادة، واستمتع بغداء طازج على متن المركب. رحلة اليوم الكامل هذه هي تجربة البحر الأحمر الأصيلة.","highlights":["زيارة أورانج باي بجزيرة الجفتون — من أجمل شواطئ مصر","محطتان للسنوركلينج فوق شعاب مرجانية نابضة بالحياة","غداء بوفيه مصري طازج على متن المركب","مركب بقاع زجاجي لغير السباحين","وقت حر للسباحة والاسترخاء والاستكشاف","معدات سنوركلينج احترافية مشمولة"],"itinerary":[{"time":"08:00","activity":"الاستلام من الفندق والتوجه إلى مرسى الغردقة"},{"time":"09:00","activity":"الإبحار — مشروبات ترحيبية وتعريف بالرحلة"},{"time":"10:00","activity":"أول محطة سنوركلينج عند الشعاب المرجانية"},{"time":"11:30","activity":"الوصول إلى شاطئ أورانج باي — وقت حر على الشاطئ"},{"time":"13:30","activity":"تقديم غداء البوفيه على المركب"},{"time":"14:30","activity":"المحطة الثانية للسنوركلينج عند جزيرة الجفتون"},{"time":"16:00","activity":"العودة إلى مرسى الغردقة"},{"time":"17:00","activity":"التوصيل إلى الفندق"}],"included":["التنقلات من وإلى الفندق","رحلة مركب يوم كامل","معدات السنوركلينج (قناع، زعانف، سترة)","غداء بوفيه مصري","مياه ومشروبات غازية","رسوم دخول المحمية الطبيعية"],"excluded":["المشروبات الكحولية (متاحة للشراء)","إيجار كاميرا تحت الماء","الإكراميات"],"meetingPoint":"الاستلام من الفنادق في الغردقة والجونة وسهل حشيش.","whatToBring":["ملابس سباحة ومنشفة","واقي شمس (ويفضّل الآمن على الشعاب)","نظارة شمس وقبعة","ملابس للتغيير","كاميرا تحت الماء (اختياري)"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الإبحار. في حالة سوء الأحوال البحرية يُرد المبلغ كاملًا أو تُعاد جدولة الرحلة.","faq":[{"question":"هل يمكن لغير السباحين المشاركة؟","answer":"بالتأكيد. نوفر سترات نجاة، والمركب ذو القاع الزجاجي مثالي لمن لا يرغب في السنوركلينج."},{"question":"هل الغداء مناسب للنباتيين؟","answer":"نعم، يحتوي البوفيه على عدة خيارات نباتية. من فضلك أخبرنا بأي احتياجات غذائية عند الحجز."}]},"fr":{"title":"Croisière snorkeling à Orange Bay","duration":"7 heures","description":"Naviguez jusqu''aux rivages préservés d''Orange Bay, l''une des plus belles plages de la mer Rouge. Explorez en snorkeling des jardins de corail colorés peuplés de poissons tropicaux, détendez-vous sur une plage de sable blanc moins fréquentée que les zones touristiques et savourez un déjeuner fraîchement préparé à bord. Cette sortie en mer d''une journée est l''expérience incontournable de la mer Rouge.","highlights":["Orange Bay, île de Giftun — parmi les plus belles plages d''Égypte","Deux arrêts snorkeling sur des récifs coralliens florissants","Buffet égyptien fraîchement préparé à bord","Vision sous-marine par bateau à fond de verre pour les non-nageurs","Temps libre pour nager, bronzer et explorer","Équipement de snorkeling professionnel inclus"],"itinerary":[{"time":"08:00","activity":"Prise en charge à l''hôtel et transfert à la marina de Hurghada"},{"time":"09:00","activity":"Départ de la marina — boissons de bienvenue et présentation"},{"time":"10:00","activity":"Premier arrêt snorkeling sur le récif"},{"time":"11:30","activity":"Arrivée à la plage d''Orange Bay — temps libre"},{"time":"13:30","activity":"Déjeuner buffet servi à bord"},{"time":"14:30","activity":"Deuxième arrêt snorkeling à l''île de Giftun"},{"time":"16:00","activity":"Retour vers la marina de Hurghada"},{"time":"17:00","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Excursion en bateau d''une journée","Équipement de snorkeling (masque, palmes, gilet)","Déjeuner buffet égyptien","Boissons non alcoolisées et eau","Droits d''entrée du parc national"],"excluded":["Boissons alcoolisées (en vente à bord)","Location d''appareil photo sous-marin","Pourboires"],"meetingPoint":"Prise en charge dans les hôtels de Hurghada, El Gouna et Sahl Hasheesh.","whatToBring":["Maillot de bain et serviette","Crème solaire (de préférence sans danger pour les récifs)","Lunettes de soleil et chapeau","Vêtements de rechange","Appareil photo sous-marin (facultatif)"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant le départ. En cas de mer agitée, remboursement intégral ou report proposé.","faq":[{"question":"Les non-nageurs peuvent-ils participer ?","answer":"Absolument. Des gilets de sauvetage sont fournis et le bateau à fond de verre est idéal pour ceux qui préfèrent ne pas faire de snorkeling."},{"question":"Le déjeuner convient-il aux végétariens ?","answer":"Oui, le buffet propose plusieurs options végétariennes. Merci de nous signaler vos besoins alimentaires lors de la réservation."}]},"de":{"title":"Schnorchel-Bootstour nach Orange Bay","duration":"7 Stunden","description":"Fahren Sie zu den unberührten Stränden der Orange Bay, einem der schönsten Strände am Roten Meer. Schnorcheln Sie in farbenfrohen Korallengärten voller tropischer Fische, entspannen Sie an einem weißen Sandstrand, der weniger überlaufen ist als die üblichen Touristengebiete, und genießen Sie ein frisch zubereitetes Mittagessen an Bord. Dieser Tagesausflug ist das ultimative Rotes-Meer-Erlebnis.","highlights":["Besuch der Orange Bay auf der Insel Giftun — einige der schönsten Strände Ägyptens","Zwei Schnorchelstopps an lebendigen Korallenriffen","Frisch zubereitetes ägyptisches Buffet an Bord","Glasbodenboot für Nichtschwimmer","Freie Zeit zum Schwimmen, Sonnen und Erkunden","Professionelle Schnorchelausrüstung inklusive"],"itinerary":[{"time":"08:00","activity":"Abholung vom Hotel und Transfer zur Marina Hurghada"},{"time":"09:00","activity":"Abfahrt — Begrüßungsgetränke und Einführung"},{"time":"10:00","activity":"Erster Schnorchelstopp am Korallenriff"},{"time":"11:30","activity":"Ankunft am Strand der Orange Bay — freie Strandzeit"},{"time":"13:30","activity":"Mittagsbuffet an Bord"},{"time":"14:30","activity":"Zweiter Schnorchelstopp an der Insel Giftun"},{"time":"16:00","activity":"Rückfahrt zur Marina Hurghada"},{"time":"17:00","activity":"Rücktransfer zum Hotel"}],"included":["Hoteltransfers","Ganztägiger Bootsausflug","Schnorchelausrüstung (Maske, Flossen, Weste)","Ägyptisches Mittagsbuffet","Softdrinks und Wasser","Eintritt in den Nationalpark"],"excluded":["Alkoholische Getränke (an Bord erhältlich)","Miete einer Unterwasserkamera","Trinkgelder"],"meetingPoint":"Abholung von Hotels in Hurghada, El Gouna und Sahl Hasheesh.","whatToBring":["Badekleidung und Handtuch","Sonnencreme (am besten riffschonend)","Sonnenbrille und Hut","Wechselkleidung","Unterwasserkamera (optional)"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor Abfahrt. Bei schlechtem Seegang volle Erstattung oder Umbuchung.","faq":[{"question":"Können Nichtschwimmer teilnehmen?","answer":"Auf jeden Fall. Schwimmwesten werden gestellt und das Glasbodenboot ist ideal für alle, die nicht schnorcheln möchten."},{"question":"Ist das Mittagessen für Vegetarier geeignet?","answer":"Ja, das Buffet bietet mehrere vegetarische Optionen. Bitte teilen Sie uns Ernährungswünsche bei der Buchung mit."}]}}'::jsonb, null, true, 4, 11, true, true, false, 1)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('hurg-3', 'hurghada', 'Cruises & Sailing', 1200, 600, 8, array['English', 'Arabic', 'German', 'Russian']::text[], true, true, 'Blue Horizon Yachts', array['https://images.unsplash.com/photo-1583157048761-ac1dba033233?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1625754884730-ba1e2eaafe91?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1700482323555-182b61c90794?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1638123657021-f9aca72f8caf?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.8, 543, '[]'::jsonb, '{"en":{"title":"3 Islands Dolphin Yacht Trip","duration":"8 hours","description":"Sail to three of the Red Sea''s most beautiful islands on a private or semi-private yacht and encounter wild spinner dolphins in their natural habitat. This premium trip includes the best snorkeling spots, a freshly prepared seafood lunch, and the chance to witness dolphin pods swimming alongside the boat — one of the most memorable experiences in Egypt.","highlights":["Visit three uninhabited islands including the famous Dolphin House reef","High chance of encountering wild spinner dolphins","Premium yacht with shaded deck and sun loungers","Two world-class snorkeling stops","Fresh seafood and Egyptian lunch on board","Small group — maximum 12 guests"],"itinerary":[{"time":"07:30","activity":"Hotel pickup and transfer to private marina"},{"time":"08:30","activity":"Welcome aboard — safety briefing and refreshments"},{"time":"09:30","activity":"Dolphin House reef — dolphin spotting and snorkeling"},{"time":"11:30","activity":"First island stop — swimming and relaxation"},{"time":"13:00","activity":"Seafood lunch served on board"},{"time":"14:00","activity":"Second snorkeling stop at Giftun South"},{"time":"15:30","activity":"Final island visit — beach time"},{"time":"16:30","activity":"Sail back to marina"},{"time":"17:30","activity":"Hotel drop-off"}],"included":["Hotel transfers","Full-day private yacht","Professional snorkeling equipment","Fresh seafood and Egyptian buffet lunch","Soft drinks, water, and fresh juice","Marine biologist guide"],"excluded":["Alcoholic beverages","Gratuities","Travel insurance"],"meetingPoint":"Hotel lobby. Pickup available from all Hurghada hotels.","whatToBring":["Swimwear","Sunscreen","Camera with underwater housing","Light jacket"],"cancellationPolicy":"Free cancellation up to 48 hours before departure. No refund for cancellations within 48 hours.","faq":[{"question":"Are dolphin sightings guaranteed?","answer":"Dolphin sightings occur on approximately 95% of trips. We go to Dolphin House reef where resident spinner dolphin pods are consistently present."}]},"ar":{"title":"رحلة يخت الدلافين و3 جزر","duration":"8 ساعات","description":"أبحر إلى ثلاث من أجمل جزر البحر الأحمر على يخت خاص أو شبه خاص، وشاهد الدلافين الدوّارة في بيئتها الطبيعية. تشمل هذه الرحلة المميزة أفضل أماكن السنوركلينج وغداءً طازجًا من المأكولات البحرية، وفرصة لرؤية أسراب الدلافين تسبح بجانب المركب — واحدة من أجمل التجارب في مصر.","highlights":["زيارة ثلاث جزر غير مأهولة منها شعاب بيت الدلافين الشهيرة","فرصة كبيرة لمشاهدة الدلافين الدوّارة البرية","يخت فاخر بسطح مظلل وكراسي استلقاء","محطتان للسنوركلينج بمستوى عالمي","غداء مأكولات بحرية ومصرية طازجة على متن اليخت","مجموعة صغيرة — 12 ضيفًا كحد أقصى"],"itinerary":[{"time":"07:30","activity":"الاستلام من الفندق والتوجه إلى المرسى الخاص"},{"time":"08:30","activity":"الترحيب على متن اليخت — شرح السلامة ومشروبات"},{"time":"09:30","activity":"شعاب بيت الدلافين — مشاهدة الدلافين والسنوركلينج"},{"time":"11:30","activity":"محطة الجزيرة الأولى — سباحة واسترخاء"},{"time":"13:00","activity":"تقديم غداء المأكولات البحرية على اليخت"},{"time":"14:00","activity":"المحطة الثانية للسنوركلينج عند جفتون الجنوبية"},{"time":"15:30","activity":"زيارة الجزيرة الأخيرة — وقت على الشاطئ"},{"time":"16:30","activity":"العودة إلى المرسى"},{"time":"17:30","activity":"التوصيل إلى الفندق"}],"included":["التنقلات من وإلى الفندق","يخت خاص ليوم كامل","معدات سنوركلينج احترافية","غداء بوفيه مأكولات بحرية ومصرية","مياه ومشروبات غازية وعصائر طازجة","مرشد متخصص في الأحياء البحرية"],"excluded":["المشروبات الكحولية","الإكراميات","التأمين على السفر"],"meetingPoint":"بهو الفندق. الاستلام متاح من كل فنادق الغردقة.","whatToBring":["ملابس سباحة","واقي شمس","كاميرا بغطاء مقاوم للماء","جاكيت خفيف"],"cancellationPolicy":"إلغاء مجاني حتى 48 ساعة قبل الإبحار. لا يُسترد المبلغ عند الإلغاء خلال 48 ساعة.","faq":[{"question":"هل مشاهدة الدلافين مضمونة؟","answer":"نشاهد الدلافين في حوالي 95% من الرحلات، لأننا نذهب إلى شعاب بيت الدلافين حيث تتواجد أسراب الدلافين الدوّارة بشكل دائم."}]},"fr":{"title":"Excursion en yacht : 3 îles et dauphins","duration":"8 heures","description":"Naviguez vers trois des plus belles îles de la mer Rouge à bord d''un yacht privé ou semi-privé et rencontrez des dauphins à long bec dans leur milieu naturel. Cette excursion haut de gamme comprend les meilleurs spots de snorkeling, un déjeuner de fruits de mer frais et la possibilité de voir des groupes de dauphins nager le long du bateau — l''une des expériences les plus mémorables d''Égypte.","highlights":["Trois îles inhabitées dont le célèbre récif de Dolphin House","Fortes chances de rencontrer des dauphins sauvages","Yacht premium avec pont ombragé et transats","Deux arrêts snorkeling de classe mondiale","Déjeuner de fruits de mer et cuisine égyptienne à bord","Petit groupe — 12 personnes maximum"],"itinerary":[{"time":"07:30","activity":"Prise en charge à l''hôtel et transfert à la marina privée"},{"time":"08:30","activity":"Bienvenue à bord — consignes de sécurité et rafraîchissements"},{"time":"09:30","activity":"Récif de Dolphin House — observation des dauphins et snorkeling"},{"time":"11:30","activity":"Première île — baignade et détente"},{"time":"13:00","activity":"Déjeuner de fruits de mer servi à bord"},{"time":"14:00","activity":"Deuxième arrêt snorkeling à Giftun Sud"},{"time":"15:30","activity":"Dernière île — temps à la plage"},{"time":"16:30","activity":"Retour vers la marina"},{"time":"17:30","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Yacht privé pour la journée","Équipement de snorkeling professionnel","Buffet de fruits de mer et cuisine égyptienne","Boissons, eau et jus frais","Guide biologiste marin"],"excluded":["Boissons alcoolisées","Pourboires","Assurance voyage"],"meetingPoint":"Hall de l''hôtel. Prise en charge dans tous les hôtels de Hurghada.","whatToBring":["Maillot de bain","Crème solaire","Appareil photo avec caisson étanche","Veste légère"],"cancellationPolicy":"Annulation gratuite jusqu''à 48 heures avant le départ. Aucun remboursement dans les 48 heures précédant le départ.","faq":[{"question":"L''observation des dauphins est-elle garantie ?","answer":"Les dauphins sont observés lors d''environ 95 % des sorties. Nous nous rendons au récif de Dolphin House, où des groupes de dauphins résident en permanence."}]},"de":{"title":"Yachtausflug zu 3 Inseln mit Delfinen","duration":"8 Stunden","description":"Segeln Sie auf einer privaten oder halbprivaten Yacht zu drei der schönsten Inseln des Roten Meeres und begegnen Sie wilden Spinnerdelfinen in ihrem natürlichen Lebensraum. Dieser Premium-Ausflug umfasst die besten Schnorchelplätze, ein frisches Fischmenü und die Chance, Delfinschulen neben dem Boot schwimmen zu sehen — eines der eindrucksvollsten Erlebnisse in Ägypten.","highlights":["Drei unbewohnte Inseln, darunter das berühmte Riff Dolphin House","Große Chance auf Begegnungen mit wilden Spinnerdelfinen","Premium-Yacht mit schattigem Deck und Sonnenliegen","Zwei erstklassige Schnorchelstopps","Frischer Fisch und ägyptisches Mittagessen an Bord","Kleine Gruppe — maximal 12 Gäste"],"itinerary":[{"time":"07:30","activity":"Abholung vom Hotel und Transfer zur privaten Marina"},{"time":"08:30","activity":"Willkommen an Bord — Sicherheitseinweisung und Erfrischungen"},{"time":"09:30","activity":"Riff Dolphin House — Delfinbeobachtung und Schnorcheln"},{"time":"11:30","activity":"Erster Inselstopp — Baden und Entspannen"},{"time":"13:00","activity":"Fisch-Mittagessen an Bord"},{"time":"14:00","activity":"Zweiter Schnorchelstopp bei Giftun Süd"},{"time":"15:30","activity":"Letzte Insel — Strandzeit"},{"time":"16:30","activity":"Rückfahrt zur Marina"},{"time":"17:30","activity":"Rücktransfer zum Hotel"}],"included":["Hoteltransfers","Private Yacht für einen ganzen Tag","Professionelle Schnorchelausrüstung","Buffet mit Fisch und ägyptischen Gerichten","Softdrinks, Wasser und frische Säfte","Meeresbiologe als Guide"],"excluded":["Alkoholische Getränke","Trinkgelder","Reiseversicherung"],"meetingPoint":"Hotellobby. Abholung von allen Hotels in Hurghada.","whatToBring":["Badekleidung","Sonnencreme","Kamera mit Unterwassergehäuse","Leichte Jacke"],"cancellationPolicy":"Kostenlose Stornierung bis 48 Stunden vor Abfahrt. Keine Erstattung innerhalb von 48 Stunden.","faq":[{"question":"Sind Delfinsichtungen garantiert?","answer":"Delfine werden bei rund 95 % der Ausflüge gesichtet. Wir fahren zum Riff Dolphin House, wo ständig Spinnerdelfine leben."}]}}'::jsonb, null, true, 4, 11, true, true, false, 2)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('hurg-4', 'hurghada', 'Cruises & Sailing', 8500, 4250, 9, array['English', 'Arabic']::text[], true, false, 'KM Luxury Yachts', array['https://images.unsplash.com/photo-1625754884730-ba1e2eaafe91?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1583157048761-ac1dba033233?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1780304348073-f690427f70ec?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1638123657021-f9aca72f8caf?w=800&h=560&fit=crop&auto=format&q=80']::text[], 5, 87, '[]'::jsonb, '{"en":{"title":"Private Yacht Charter","duration":"Full day (8–10 hrs)","description":"Experience the Red Sea in complete privacy on your own luxury yacht. You choose the islands, you set the pace. Ideal for honeymoons, anniversaries, or intimate gatherings, this exclusive charter includes a private chef, premium snorkeling equipment, and a customized itinerary tailored entirely to your wishes. This is the Red Sea as it should be experienced.","highlights":["Fully private yacht for up to 10 guests — no strangers on board","Customizable route across the best Red Sea islands","On-board private chef with à la carte menu","Premium snorkeling and paddleboard equipment","Chilled champagne and premium beverages on arrival","Dedicated host and crew throughout"],"itinerary":[{"time":"Flexible","activity":"Departure time and route customized to your preference"},{"time":"Morning","activity":"Sail to your chosen first destination"},{"time":"Midday","activity":"Private chef prepares your bespoke lunch"},{"time":"Afternoon","activity":"Islands, snorkeling, swimming, sunbathing at your leisure"},{"time":"Sunset","activity":"Sundowner cocktails on deck as we return to marina"}],"included":["Private luxury yacht for up to 10 guests","Professional captain and crew","Private chef with customized menu","All food and premium beverages","Snorkeling equipment and paddleboards","Hotel transfers"],"excluded":["Gratuities (warmly appreciated)","Specialty alcohol (on request)"],"meetingPoint":"Private marina in Hurghada. Full details provided upon booking.","whatToBring":["Swimwear","Light cover-up","Sunscreen","Camera","Anything that makes the day yours"],"cancellationPolicy":"Cancellations made 7+ days before departure receive a 50% refund. No refund within 7 days.","faq":[{"question":"Can we bring our own food and drinks?","answer":"The experience includes a private chef, but you''re welcome to bring anything additional. Let us know your preferences in advance."}]},"ar":{"title":"يخت خاص","duration":"يوم كامل (8–10 ساعات)","description":"استمتع بالبحر الأحمر بخصوصية تامة على يختك الفاخر. أنت تختار الجزر وأنت تحدد الإيقاع. مثالية لشهر العسل والمناسبات والتجمعات الخاصة، وتشمل طاهيًا خاصًا ومعدات سنوركلينج متميزة وبرنامجًا مصممًا بالكامل حسب رغبتك. هكذا يجب أن تعيش البحر الأحمر.","highlights":["يخت خاص بالكامل حتى 10 ضيوف — بدون غرباء","مسار مرن بين أجمل جزر البحر الأحمر","طاهٍ خاص على متن اليخت بقائمة حسب الطلب","معدات سنوركلينج وألواح تجديف متميزة","شمبانيا مثلجة ومشروبات فاخرة عند الوصول","مضيف وطاقم مخصص طوال اليوم"],"itinerary":[{"time":"مرن","activity":"موعد الإبحار والمسار حسب رغبتك"},{"time":"الصباح","activity":"الإبحار إلى أول وجهة تختارها"},{"time":"الظهيرة","activity":"الطاهي الخاص يحضّر غداءك حسب ذوقك"},{"time":"بعد الظهر","activity":"جزر وسنوركلينج وسباحة واستجمام كما تحب"},{"time":"الغروب","activity":"مشروبات الغروب على السطح أثناء العودة إلى المرسى"}],"included":["يخت فاخر خاص حتى 10 ضيوف","قبطان وطاقم محترف","طاهٍ خاص بقائمة طعام مخصصة","جميع الوجبات والمشروبات الفاخرة","معدات سنوركلينج وألواح تجديف","التنقلات من وإلى الفندق"],"excluded":["الإكراميات (محل تقدير)","مشروبات كحولية خاصة (عند الطلب)"],"meetingPoint":"مرسى خاص في الغردقة. يتم إرسال التفاصيل الكاملة بعد الحجز.","whatToBring":["ملابس سباحة","غطاء خفيف","واقي شمس","كاميرا","كل ما يجعل يومك مميزًا"],"cancellationPolicy":"الإلغاء قبل 7 أيام أو أكثر من الإبحار يُسترد 50% من المبلغ. لا يُسترد شيء خلال 7 أيام.","faq":[{"question":"هل يمكن إحضار طعامنا ومشروباتنا؟","answer":"التجربة تشمل طاهيًا خاصًا، لكن يمكنك إحضار أي شيء إضافي. أخبرنا بتفضيلاتك مسبقًا."}]},"fr":{"title":"Location de yacht privé","duration":"Journée complète (8–10 h)","description":"Découvrez la mer Rouge en toute intimité à bord de votre propre yacht de luxe. Vous choisissez les îles, vous fixez le rythme. Idéale pour une lune de miel, un anniversaire ou une réunion entre proches, cette location exclusive comprend un chef privé, un équipement de snorkeling haut de gamme et un itinéraire entièrement personnalisé. La mer Rouge telle qu''elle doit être vécue.","highlights":["Yacht entièrement privatisé jusqu''à 10 personnes — aucun inconnu à bord","Itinéraire sur mesure parmi les plus belles îles de la mer Rouge","Chef privé à bord avec menu à la carte","Équipement de snorkeling et paddles haut de gamme","Champagne frais et boissons premium à l''arrivée","Hôte et équipage dédiés toute la journée"],"itinerary":[{"time":"Flexible","activity":"Heure de départ et itinéraire selon vos envies"},{"time":"Matin","activity":"Navigation vers la première destination choisie"},{"time":"Midi","activity":"Le chef privé prépare votre déjeuner sur mesure"},{"time":"Après-midi","activity":"Îles, snorkeling, baignade et bronzage à votre rythme"},{"time":"Coucher du soleil","activity":"Cocktails au coucher du soleil sur le pont pendant le retour"}],"included":["Yacht de luxe privé jusqu''à 10 personnes","Capitaine et équipage professionnels","Chef privé avec menu personnalisé","Tous les repas et boissons premium","Équipement de snorkeling et paddles","Transferts depuis l''hôtel"],"excluded":["Pourboires (très appréciés)","Alcools spéciaux (sur demande)"],"meetingPoint":"Marina privée à Hurghada. Tous les détails sont communiqués après la réservation.","whatToBring":["Maillot de bain","Paréo ou couvre-maillot","Crème solaire","Appareil photo","Tout ce qui rendra la journée unique"],"cancellationPolicy":"Les annulations 7 jours ou plus avant le départ sont remboursées à 50 %. Aucun remboursement dans les 7 jours.","faq":[{"question":"Pouvons-nous apporter nos propres repas et boissons ?","answer":"L''expérience inclut un chef privé, mais vous pouvez apporter ce que vous souhaitez en plus. Indiquez-nous vos préférences à l''avance."}]},"de":{"title":"Private Yachtcharter","duration":"Ganzer Tag (8–10 Std.)","description":"Erleben Sie das Rote Meer ganz privat auf Ihrer eigenen Luxusyacht. Sie wählen die Inseln, Sie bestimmen das Tempo. Ideal für Flitterwochen, Jubiläen oder kleine Feiern — inklusive Privatkoch, hochwertiger Schnorchelausrüstung und einer komplett nach Ihren Wünschen gestalteten Route. So sollte man das Rote Meer erleben.","highlights":["Komplett private Yacht für bis zu 10 Gäste — keine Fremden an Bord","Individuelle Route zu den schönsten Inseln des Roten Meeres","Privatkoch an Bord mit À-la-carte-Menü","Hochwertige Schnorchel- und Stand-up-Paddle-Ausrüstung","Gekühlter Champagner und Premium-Getränke zur Begrüßung","Eigener Gastgeber und Crew den ganzen Tag"],"itinerary":[{"time":"Flexibel","activity":"Abfahrtszeit und Route nach Ihren Wünschen"},{"time":"Vormittag","activity":"Fahrt zu Ihrem ersten Wunschziel"},{"time":"Mittag","activity":"Der Privatkoch bereitet Ihr individuelles Mittagessen zu"},{"time":"Nachmittag","activity":"Inseln, Schnorcheln, Baden und Sonnen in Ihrem Tempo"},{"time":"Sonnenuntergang","activity":"Sundowner an Deck auf dem Rückweg zur Marina"}],"included":["Private Luxusyacht für bis zu 10 Gäste","Professioneller Kapitän und Crew","Privatkoch mit individuellem Menü","Alle Speisen und Premium-Getränke","Schnorchelausrüstung und Paddleboards","Hoteltransfers"],"excluded":["Trinkgelder (herzlich willkommen)","Spezielle Spirituosen (auf Anfrage)"],"meetingPoint":"Private Marina in Hurghada. Alle Details erhalten Sie nach der Buchung.","whatToBring":["Badekleidung","Leichte Überkleidung","Sonnencreme","Kamera","Alles, was den Tag zu Ihrem macht"],"cancellationPolicy":"Bei Stornierung 7 oder mehr Tage vor Abfahrt werden 50 % erstattet. Innerhalb von 7 Tagen keine Erstattung.","faq":[{"question":"Dürfen wir eigene Speisen und Getränke mitbringen?","answer":"Ein Privatkoch ist inklusive, aber Sie können gerne Zusätzliches mitbringen. Teilen Sie uns Ihre Wünsche vorab mit."}]}}'::jsonb, null, true, 4, 11, true, true, false, 3)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('hurg-5', 'hurghada', 'Desert & Adventure', 750, 375, 2.5, array['English', 'Arabic', 'Russian']::text[], true, true, 'Desert Riders Hurghada', array['https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1577085375786-edb0f45560aa?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1713021714419-ca3a7bc12f00?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.6, 674, '[]'::jsonb, '{"en":{"title":"Quad Bike Desert Adventure","duration":"2.5 hours","description":"Tear across Egypt''s Eastern Desert on a powerful quad bike for an adrenaline-filled adventure unlike anything else. Navigate through dramatic sand dunes, rocky plateaus, and sweeping desert panoramas. This guided ride ends at a Bedouin camp where you can enjoy tea, shisha, and the extraordinary silence of the Sahara at sunset.","highlights":["Ride across sand dunes, desert flats, and rocky terrain","Professional guided ride — all skill levels welcome","Stunning desert panoramas and photo opportunities","Bedouin camp visit with traditional tea and shisha","Sunset timing available for golden-hour photography","Safety equipment, helmet, and goggles provided"],"itinerary":[{"time":"15:30","activity":"Hotel pickup and transfer to desert base"},{"time":"16:00","activity":"Safety briefing and quad bike orientation"},{"time":"16:30","activity":"Desert ride begins — guided trail through dunes and rocky terrain"},{"time":"17:30","activity":"Bedouin camp stop — tea, coffee, and shisha"},{"time":"18:00","activity":"Sunset ride back to base"},{"time":"18:30","activity":"Return transfer to hotel"}],"included":["Hotel pickup and drop-off","Quad bike (one per person or one per couple)","Safety helmet, goggles, and gloves","Professional desert guide","Bedouin tea and coffee","Bottled water"],"excluded":["Gratuities","Shisha (available for additional fee)"],"meetingPoint":"Hotel lobby. Pickup from all Hurghada hotels.","whatToBring":["Closed-toe shoes (mandatory)","Long trousers recommended","Sunglasses","Scarf or bandana for dust protection"],"cancellationPolicy":"Free cancellation up to 24 hours before the experience. No refund within 24 hours.","faq":[{"question":"Do I need experience to ride a quad bike?","answer":"No prior experience is needed. Our guides provide a full briefing and the bikes are easy to operate. We cater to all levels."},{"question":"Is this suitable for children?","answer":"Children aged 10+ can ride as a passenger with an adult. Children aged 16+ may operate their own quad bike."}]},"ar":{"title":"مغامرة الموتوسيكلات الرباعية في الصحراء","duration":"2.5 ساعة","description":"انطلق عبر الصحراء الشرقية على موتوسيكل رباعي قوي في مغامرة مليئة بالإثارة. تنقّل بين الكثبان الرملية والهضاب الصخرية والمناظر الصحراوية الواسعة. تنتهي الجولة في مخيم بدوي حيث تستمتع بالشاي والشيشة وهدوء الصحراء المذهل وقت الغروب.","highlights":["القيادة عبر الكثبان الرملية والسهول والطرق الصخرية","جولة مع مرشد محترف — مناسبة لكل المستويات","مناظر صحراوية خلابة وفرص رائعة للتصوير","زيارة مخيم بدوي مع الشاي والشيشة","إمكانية الرحلة وقت الغروب لأجمل الصور","خوذة ونظارات ومعدات أمان مشمولة"],"itinerary":[{"time":"15:30","activity":"الاستلام من الفندق والتوجه إلى قاعدة الصحراء"},{"time":"16:00","activity":"شرح السلامة والتعرف على الموتوسيكل"},{"time":"16:30","activity":"بداية الجولة — مسار مع مرشد بين الكثبان والصخور"},{"time":"17:30","activity":"التوقف في المخيم البدوي — شاي وقهوة وشيشة"},{"time":"18:00","activity":"العودة وقت الغروب إلى القاعدة"},{"time":"18:30","activity":"العودة إلى الفندق"}],"included":["الاستلام والتوصيل من وإلى الفندق","موتوسيكل رباعي (لكل شخص أو لكل اثنين)","خوذة ونظارات وقفازات","مرشد صحراوي محترف","شاي وقهوة بدوية","مياه معبأة"],"excluded":["الإكراميات","الشيشة (برسوم إضافية)"],"meetingPoint":"بهو الفندق. الاستلام من كل فنادق الغردقة.","whatToBring":["حذاء مغلق (إلزامي)","يُفضل بنطلون طويل","نظارة شمس","وشاح أو باندانا للحماية من الغبار"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل التجربة. لا يُسترد المبلغ خلال 24 ساعة.","faq":[{"question":"هل أحتاج خبرة لقيادة الموتوسيكل الرباعي؟","answer":"لا تحتاج أي خبرة سابقة. يقدم مرشدونا شرحًا كاملًا والموتوسيكلات سهلة القيادة، ونناسب كل المستويات."},{"question":"هل الرحلة مناسبة للأطفال؟","answer":"يمكن للأطفال من 10 سنوات الركوب مع شخص بالغ، ومن 16 سنة يمكنهم قيادة موتوسيكل بأنفسهم."}]},"fr":{"title":"Aventure en quad dans le désert","duration":"2,5 heures","description":"Foncez à travers le désert oriental égyptien sur un quad puissant pour une aventure pleine d''adrénaline. Traversez dunes de sable, plateaux rocheux et vastes panoramas désertiques. Cette balade guidée se termine dans un camp bédouin où vous profiterez du thé, de la chicha et du silence extraordinaire du désert au coucher du soleil.","highlights":["Pilotage sur dunes, plaines et terrains rocheux","Balade guidée par des professionnels — tous niveaux bienvenus","Panoramas désertiques spectaculaires et belles photos","Visite d''un camp bédouin avec thé et chicha","Départ au coucher du soleil possible pour la lumière dorée","Équipement de sécurité, casque et lunettes fournis"],"itinerary":[{"time":"15:30","activity":"Prise en charge à l''hôtel et transfert à la base"},{"time":"16:00","activity":"Consignes de sécurité et prise en main du quad"},{"time":"16:30","activity":"Départ de la balade — piste guidée entre dunes et rochers"},{"time":"17:30","activity":"Arrêt au camp bédouin — thé, café et chicha"},{"time":"18:00","activity":"Retour à la base au coucher du soleil"},{"time":"18:30","activity":"Retour à l''hôtel"}],"included":["Prise en charge et retour à l''hôtel","Quad (un par personne ou un par couple)","Casque, lunettes et gants","Guide professionnel du désert","Thé et café bédouins","Eau en bouteille"],"excluded":["Pourboires","Chicha (avec supplément)"],"meetingPoint":"Hall de l''hôtel. Prise en charge dans tous les hôtels de Hurghada.","whatToBring":["Chaussures fermées (obligatoires)","Pantalon long recommandé","Lunettes de soleil","Foulard ou bandana contre la poussière"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant l''expérience. Aucun remboursement dans les 24 heures.","faq":[{"question":"Faut-il de l''expérience pour conduire un quad ?","answer":"Aucune expérience n''est nécessaire. Nos guides donnent toutes les explications et les quads sont faciles à conduire. Tous les niveaux sont acceptés."},{"question":"Est-ce adapté aux enfants ?","answer":"Les enfants dès 10 ans peuvent monter comme passagers avec un adulte. Dès 16 ans, ils peuvent conduire leur propre quad."}]},"de":{"title":"Quad-Abenteuer in der Wüste","duration":"2,5 Stunden","description":"Brausen Sie mit einem kraftvollen Quad durch Ägyptens Östliche Wüste — ein Abenteuer voller Adrenalin. Fahren Sie über Sanddünen, felsige Plateaus und durch weite Wüstenpanoramen. Die geführte Tour endet in einem Beduinencamp, wo Sie Tee, Shisha und die außergewöhnliche Stille der Wüste bei Sonnenuntergang genießen.","highlights":["Fahrt über Sanddünen, Wüstenebenen und felsiges Gelände","Professionell geführte Tour — für alle Erfahrungsstufen","Atemberaubende Wüstenpanoramen und Fotomotive","Besuch eines Beduinencamps mit Tee und Shisha","Sonnenuntergangstermin für Fotos im goldenen Licht möglich","Sicherheitsausrüstung, Helm und Brille inklusive"],"itinerary":[{"time":"15:30","activity":"Abholung vom Hotel und Transfer zur Wüstenbasis"},{"time":"16:00","activity":"Sicherheitseinweisung und Einführung ins Quad"},{"time":"16:30","activity":"Start der Tour — geführte Strecke durch Dünen und Felsen"},{"time":"17:30","activity":"Stopp im Beduinencamp — Tee, Kaffee und Shisha"},{"time":"18:00","activity":"Rückfahrt zur Basis bei Sonnenuntergang"},{"time":"18:30","activity":"Rücktransfer zum Hotel"}],"included":["Abholung und Rücktransfer vom Hotel","Quad (eines pro Person oder pro Paar)","Helm, Brille und Handschuhe","Professioneller Wüstenguide","Beduinentee und Kaffee","Wasser in Flaschen"],"excluded":["Trinkgelder","Shisha (gegen Aufpreis)"],"meetingPoint":"Hotellobby. Abholung von allen Hotels in Hurghada.","whatToBring":["Geschlossene Schuhe (Pflicht)","Lange Hose empfohlen","Sonnenbrille","Schal oder Bandana gegen Staub"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vorher. Keine Erstattung innerhalb von 24 Stunden.","faq":[{"question":"Brauche ich Erfahrung, um ein Quad zu fahren?","answer":"Keine Vorkenntnisse nötig. Unsere Guides erklären alles ausführlich und die Quads sind leicht zu fahren. Alle Erfahrungsstufen sind willkommen."},{"question":"Ist die Tour für Kinder geeignet?","answer":"Kinder ab 10 Jahren können als Beifahrer mit einem Erwachsenen mitfahren. Ab 16 Jahren dürfen sie ein eigenes Quad fahren."}]}}'::jsonb, null, true, 4, 11, true, true, false, 4)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('sharm-1', 'sharm', 'Water Sports', 750, 375, 6, array['English', 'Arabic', 'Russian', 'Italian']::text[], true, true, 'Sinai Blue Diving', array['https://images.unsplash.com/photo-1700482323555-182b61c90794?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1638123657021-f9aca72f8caf?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1583157048761-ac1dba033233?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1625754884730-ba1e2eaafe91?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.8, 723, '[]'::jsonb, '{"en":{"title":"Ras Mohammed Snorkeling & Dive Safari","duration":"6 hours","description":"Ras Mohammed National Park protects some of the most pristine coral reefs in the world — and this boat trip takes you straight to the best snorkeling and diving sites within it. The Shark Bay and Eel Garden reefs feature walls of coral dropping hundreds of metres, teeming with hundreds of species of fish. This is world-class marine life in one of Egypt''s most protected natural treasures.","highlights":["Two snorkeling and diving stops inside Ras Mohammed National Park","Shark Bay — coral walls, reef sharks, and tropical fish","Eel Garden — moray eels, turtles, and reef life","Scuba diving option for certified divers","PADI-certified dive instructor on board","All snorkeling and diving equipment included"],"itinerary":[{"time":"08:30","activity":"Hotel pickup from Sharm el-Sheikh and Na''ama Bay"},{"time":"09:30","activity":"Depart marina — briefing and equipment fitting"},{"time":"10:30","activity":"First stop: Shark Bay snorkeling or dive"},{"time":"12:30","activity":"Lunch served on board"},{"time":"13:30","activity":"Second stop: Eel Garden snorkeling or dive"},{"time":"15:30","activity":"Return to marina and hotel drop-off"}],"included":["Hotel transfers","Boat trip with park fees","Snorkeling equipment","Dive equipment (for divers)","PADI instructor","Lunch and soft drinks"],"excluded":["Dive certification (must be PADI Open Water or equivalent)","Alcoholic beverages","Gratuities"],"meetingPoint":"Hotel lobby in Sharm el-Sheikh or Na''ama Bay.","whatToBring":["Swimwear","Sunscreen (reef-safe)","Towel","Underwater camera","Dive certification card (divers)"],"cancellationPolicy":"Free cancellation up to 24 hours before departure.","faq":[{"question":"Do I need to be a certified diver?","answer":"Snorkeling is open to all. Scuba diving requires PADI Open Water certification or equivalent. We offer introductory dives for beginners."}]},"ar":{"title":"سفاري سنوركلينج وغوص في رأس محمد","duration":"6 ساعات","description":"تحمي محمية رأس محمد الوطنية بعضًا من أنقى الشعاب المرجانية في العالم، وتأخذك هذه الرحلة البحرية مباشرة إلى أفضل مواقع السنوركلينج والغوص فيها. تتميز شعاب شارك باي وحديقة ثعابين البحر بجدران مرجانية تنحدر لمئات الأمتار وتعج بمئات الأنواع من الأسماك. حياة بحرية بمستوى عالمي في واحدة من أهم الكنوز الطبيعية المحمية في مصر.","highlights":["محطتان للسنوركلينج والغوص داخل محمية رأس محمد","شارك باي — جدران مرجانية وأسماك قرش الشعاب وأسماك استوائية","حديقة ثعابين البحر — ثعابين موراي وسلاحف وحياة الشعاب","إمكانية الغوص بالأكسجين للغواصين المعتمدين","مدرب غوص معتمد من PADI على متن المركب","جميع معدات السنوركلينج والغوص مشمولة"],"itinerary":[{"time":"08:30","activity":"الاستلام من الفندق في شرم الشيخ وخليج نعمة"},{"time":"09:30","activity":"الإبحار — شرح الرحلة وتجهيز المعدات"},{"time":"10:30","activity":"المحطة الأولى: سنوركلينج أو غوص في شارك باي"},{"time":"12:30","activity":"تقديم الغداء على المركب"},{"time":"13:30","activity":"المحطة الثانية: سنوركلينج أو غوص في حديقة ثعابين البحر"},{"time":"15:30","activity":"العودة إلى المرسى والتوصيل إلى الفندق"}],"included":["التنقلات من وإلى الفندق","رحلة المركب ورسوم المحمية","معدات السنوركلينج","معدات الغوص (للغواصين)","مدرب PADI","غداء ومشروبات غازية"],"excluded":["شهادة الغوص (يلزم PADI Open Water أو ما يعادلها)","المشروبات الكحولية","الإكراميات"],"meetingPoint":"بهو الفندق في شرم الشيخ أو خليج نعمة.","whatToBring":["ملابس سباحة","واقي شمس آمن على الشعاب","منشفة","كاميرا تحت الماء","بطاقة شهادة الغوص (للغواصين)"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الإبحار.","faq":[{"question":"هل يجب أن أكون غواصًا معتمدًا؟","answer":"السنوركلينج متاح للجميع. الغوص بالأكسجين يتطلب شهادة PADI Open Water أو ما يعادلها، ونقدم غطسات تعريفية للمبتدئين."}]},"fr":{"title":"Safari snorkeling et plongée à Ras Mohammed","duration":"6 heures","description":"Le parc national de Ras Mohammed protège certains des récifs coralliens les plus préservés au monde, et cette sortie en bateau vous mène directement à ses meilleurs sites de snorkeling et de plongée. Les récifs de Shark Bay et d''Eel Garden présentent des tombants de corail plongeant à des centaines de mètres, peuplés de centaines d''espèces de poissons. Une vie marine de classe mondiale dans l''un des trésors naturels les mieux protégés d''Égypte.","highlights":["Deux arrêts snorkeling et plongée dans le parc national de Ras Mohammed","Shark Bay — tombants coralliens, requins de récif et poissons tropicaux","Eel Garden — murènes, tortues et vie récifale","Option plongée bouteille pour les plongeurs certifiés","Instructeur de plongée certifié PADI à bord","Tout l''équipement de snorkeling et de plongée inclus"],"itinerary":[{"time":"08:30","activity":"Prise en charge à l''hôtel à Charm el-Cheikh et Naama Bay"},{"time":"09:30","activity":"Départ de la marina — briefing et ajustement de l''équipement"},{"time":"10:30","activity":"Premier arrêt : snorkeling ou plongée à Shark Bay"},{"time":"12:30","activity":"Déjeuner servi à bord"},{"time":"13:30","activity":"Deuxième arrêt : snorkeling ou plongée à Eel Garden"},{"time":"15:30","activity":"Retour à la marina et à l''hôtel"}],"included":["Transferts depuis l''hôtel","Sortie en bateau avec droits du parc","Équipement de snorkeling","Équipement de plongée (pour les plongeurs)","Instructeur PADI","Déjeuner et boissons non alcoolisées"],"excluded":["Certification de plongée (PADI Open Water ou équivalent requis)","Boissons alcoolisées","Pourboires"],"meetingPoint":"Hall de l''hôtel à Charm el-Cheikh ou Naama Bay.","whatToBring":["Maillot de bain","Crème solaire sans danger pour les récifs","Serviette","Appareil photo sous-marin","Carte de certification (plongeurs)"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant le départ.","faq":[{"question":"Dois-je être plongeur certifié ?","answer":"Le snorkeling est ouvert à tous. La plongée bouteille nécessite le niveau PADI Open Water ou équivalent. Nous proposons des baptêmes pour les débutants."}]},"de":{"title":"Schnorchel- und Tauchsafari in Ras Mohammed","duration":"6 Stunden","description":"Der Ras-Mohammed-Nationalpark schützt einige der unberührtesten Korallenriffe der Welt — und dieser Bootsausflug bringt Sie direkt zu den besten Schnorchel- und Tauchplätzen. Die Riffe Shark Bay und Eel Garden bieten Korallenwände, die Hunderte Meter in die Tiefe abfallen und von Hunderten Fischarten bevölkert sind. Meeresleben von Weltklasse in einem der am besten geschützten Naturschätze Ägyptens.","highlights":["Zwei Schnorchel- und Tauchstopps im Ras-Mohammed-Nationalpark","Shark Bay — Korallenwände, Riffhaie und tropische Fische","Eel Garden — Muränen, Schildkröten und Riffleben","Gerätetauchen für zertifizierte Taucher möglich","PADI-zertifizierter Tauchlehrer an Bord","Komplette Schnorchel- und Tauchausrüstung inklusive"],"itinerary":[{"time":"08:30","activity":"Abholung vom Hotel in Scharm El-Scheich und Naama Bay"},{"time":"09:30","activity":"Abfahrt — Briefing und Anpassen der Ausrüstung"},{"time":"10:30","activity":"Erster Stopp: Schnorcheln oder Tauchen in der Shark Bay"},{"time":"12:30","activity":"Mittagessen an Bord"},{"time":"13:30","activity":"Zweiter Stopp: Schnorcheln oder Tauchen im Eel Garden"},{"time":"15:30","activity":"Rückkehr zur Marina und Rücktransfer zum Hotel"}],"included":["Hoteltransfers","Bootsausflug inkl. Parkgebühren","Schnorchelausrüstung","Tauchausrüstung (für Taucher)","PADI-Tauchlehrer","Mittagessen und Softdrinks"],"excluded":["Tauchzertifikat (PADI Open Water oder gleichwertig erforderlich)","Alkoholische Getränke","Trinkgelder"],"meetingPoint":"Hotellobby in Scharm El-Scheich oder Naama Bay.","whatToBring":["Badekleidung","Riffschonende Sonnencreme","Handtuch","Unterwasserkamera","Tauchzertifikat (für Taucher)"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor Abfahrt.","faq":[{"question":"Muss ich ein zertifizierter Taucher sein?","answer":"Schnorcheln ist für alle möglich. Gerätetauchen erfordert PADI Open Water oder gleichwertig. Für Anfänger bieten wir Schnuppertauchgänge an."}]}}'::jsonb, null, true, 4, 11, true, true, false, 0)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('sharm-2', 'sharm', 'Cruises & Sailing', 650, 325, 6, array['English', 'Arabic', 'Russian']::text[], true, true, 'Sinai Blue Diving', array['https://images.unsplash.com/photo-1638123657021-f9aca72f8caf?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1583157048761-ac1dba033233?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1700482323555-182b61c90794?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1625754884730-ba1e2eaafe91?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.6, 412, '[]'::jsonb, '{"en":{"title":"White Island Boat Trip","duration":"6 hours","description":"Sail to the stunning White Island — a pristine sandbar in the Straits of Tiran that appears and disappears with the tide. The surrounding reef is one of the richest in the Red Sea, home to schools of barracuda, Napoleon wrasse, and colourful reef fish in water of extraordinary clarity. This is a full day of sun, sea, snorkeling, and total relaxation.","highlights":["White Island sandbar — swim in crystal-clear turquoise shallows","Two snorkeling stops on the renowned Tiran reefs","Tiran Island and the four coral reef systems of the Straits","Fresh seafood and Egyptian lunch on board","Peaceful, less crowded than Ras Mohammed"],"itinerary":[{"time":"08:00","activity":"Hotel pickup"},{"time":"09:00","activity":"Depart Sharm marina"},{"time":"10:30","activity":"First snorkeling stop — Tiran reef"},{"time":"12:00","activity":"White Island — swimming and beach time"},{"time":"13:00","activity":"Lunch on board"},{"time":"14:00","activity":"Second snorkeling stop"},{"time":"16:00","activity":"Return to marina — hotel drop-off"}],"included":["Hotel transfers","Boat trip","Snorkeling equipment","Lunch and drinks"],"excluded":["Alcoholic beverages","Gratuities"],"meetingPoint":"Hotel lobby in Sharm el-Sheikh or Na''ama Bay.","whatToBring":["Swimwear","Reef-safe sunscreen","Towel"],"cancellationPolicy":"Free cancellation up to 24 hours before departure.","faq":[]},"ar":{"title":"رحلة بالمركب إلى الجزيرة البيضاء","duration":"6 ساعات","description":"أبحر إلى الجزيرة البيضاء الساحرة — لسان رملي بكر في مضيق تيران يظهر ويختفي مع المد والجزر. الشعاب المحيطة بها من أغنى شعاب البحر الأحمر، وتعيش فيها أسراب الباراكودا وسمك النابليون وأسماك الشعاب الملونة في مياه شديدة الصفاء. يوم كامل من الشمس والبحر والسنوركلينج والاسترخاء التام.","highlights":["الجزيرة البيضاء — سباحة في مياه فيروزية ضحلة وصافية","محطتان للسنوركلينج على شعاب تيران الشهيرة","جزيرة تيران ونظم الشعاب المرجانية الأربعة في المضيق","غداء مأكولات بحرية ومصرية طازجة على المركب","هادئة وأقل ازدحامًا من رأس محمد"],"itinerary":[{"time":"08:00","activity":"الاستلام من الفندق"},{"time":"09:00","activity":"الإبحار من مرسى شرم"},{"time":"10:30","activity":"المحطة الأولى للسنوركلينج — شعاب تيران"},{"time":"12:00","activity":"الجزيرة البيضاء — سباحة ووقت على الشاطئ"},{"time":"13:00","activity":"الغداء على المركب"},{"time":"14:00","activity":"المحطة الثانية للسنوركلينج"},{"time":"16:00","activity":"العودة إلى المرسى — التوصيل إلى الفندق"}],"included":["التنقلات من وإلى الفندق","رحلة المركب","معدات السنوركلينج","الغداء والمشروبات"],"excluded":["المشروبات الكحولية","الإكراميات"],"meetingPoint":"بهو الفندق في شرم الشيخ أو خليج نعمة.","whatToBring":["ملابس سباحة","واقي شمس آمن على الشعاب","منشفة"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الإبحار.","faq":[]},"fr":{"title":"Excursion en bateau à l''île Blanche","duration":"6 heures","description":"Naviguez vers la magnifique île Blanche, un banc de sable préservé dans le détroit de Tiran qui apparaît et disparaît au gré des marées. Le récif environnant est l''un des plus riches de la mer Rouge : bancs de barracudas, napoléons et poissons colorés dans une eau d''une clarté exceptionnelle. Une journée complète de soleil, de mer, de snorkeling et de détente.","highlights":["Banc de sable de l''île Blanche — baignade dans une eau turquoise cristalline","Deux arrêts snorkeling sur les célèbres récifs de Tiran","L''île de Tiran et les quatre récifs coralliens du détroit","Déjeuner de fruits de mer et cuisine égyptienne à bord","Paisible et moins fréquenté que Ras Mohammed"],"itinerary":[{"time":"08:00","activity":"Prise en charge à l''hôtel"},{"time":"09:00","activity":"Départ de la marina de Charm"},{"time":"10:30","activity":"Premier arrêt snorkeling — récif de Tiran"},{"time":"12:00","activity":"Île Blanche — baignade et plage"},{"time":"13:00","activity":"Déjeuner à bord"},{"time":"14:00","activity":"Deuxième arrêt snorkeling"},{"time":"16:00","activity":"Retour à la marina — retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Sortie en bateau","Équipement de snorkeling","Déjeuner et boissons"],"excluded":["Boissons alcoolisées","Pourboires"],"meetingPoint":"Hall de l''hôtel à Charm el-Cheikh ou Naama Bay.","whatToBring":["Maillot de bain","Crème solaire sans danger pour les récifs","Serviette"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant le départ.","faq":[]},"de":{"title":"Bootsausflug zur Weißen Insel","duration":"6 Stunden","description":"Segeln Sie zur traumhaften Weißen Insel — einer unberührten Sandbank in der Straße von Tiran, die mit den Gezeiten auftaucht und verschwindet. Das umliegende Riff gehört zu den artenreichsten des Roten Meeres: Barrakudaschwärme, Napoleon-Lippfische und bunte Rifffische in außergewöhnlich klarem Wasser. Ein ganzer Tag voller Sonne, Meer, Schnorcheln und Entspannung.","highlights":["Sandbank der Weißen Insel — Baden in kristallklarem, türkisem Flachwasser","Zwei Schnorchelstopps an den berühmten Tiran-Riffen","Die Insel Tiran und die vier Korallenriffe der Meerenge","Frischer Fisch und ägyptisches Mittagessen an Bord","Ruhig und weniger überlaufen als Ras Mohammed"],"itinerary":[{"time":"08:00","activity":"Abholung vom Hotel"},{"time":"09:00","activity":"Abfahrt von der Marina in Scharm"},{"time":"10:30","activity":"Erster Schnorchelstopp — Tiran-Riff"},{"time":"12:00","activity":"Weiße Insel — Baden und Strandzeit"},{"time":"13:00","activity":"Mittagessen an Bord"},{"time":"14:00","activity":"Zweiter Schnorchelstopp"},{"time":"16:00","activity":"Rückkehr zur Marina — Rücktransfer zum Hotel"}],"included":["Hoteltransfers","Bootsausflug","Schnorchelausrüstung","Mittagessen und Getränke"],"excluded":["Alkoholische Getränke","Trinkgelder"],"meetingPoint":"Hotellobby in Scharm El-Scheich oder Naama Bay.","whatToBring":["Badekleidung","Riffschonende Sonnencreme","Handtuch"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor Abfahrt.","faq":[]}}'::jsonb, null, true, 4, 11, true, true, false, 1)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('sharm-3', 'sharm', 'Desert & Adventure', 850, 425, 3, array['English', 'Arabic', 'Russian']::text[], true, true, 'Sinai Desert Riders', array['https://images.unsplash.com/photo-1577085375786-edb0f45560aa?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1713021714419-ca3a7bc12f00?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.7, 534, '[]'::jsonb, '{"en":{"title":"Sinai Desert ATV Safari","duration":"3 hours","description":"The Sinai Peninsula''s dramatic desert landscape — red and ochre mountains, sweeping plains, and ancient Bedouin trails — is best explored by ATV. This guided ride takes you through breathtaking desert terrain with sweeping views of the Red Sea and the mountains of Saudi Arabia across the water. The tour ends at a Bedouin camp for traditional hospitality under the stars.","highlights":["ATV ride through Sinai Desert terrain — dunes, rocky trails, and mountain views","Panoramic views of the Red Sea and Tiran Island","Bedouin camp visit — tea, shisha, and stargazing","Sunset timing for golden-hour photography","All safety equipment provided"],"itinerary":[{"time":"15:30","activity":"Hotel pickup"},{"time":"16:00","activity":"Safety briefing and ATV orientation"},{"time":"16:30","activity":"Desert ride begins — varied terrain with panoramic stops"},{"time":"17:30","activity":"Bedouin camp — sunset views, tea, and shisha"},{"time":"18:30","activity":"Return transfer to hotel"}],"included":["Hotel transfers","ATV","Safety equipment","Bedouin tea","Guide"],"excluded":["Shisha (optional, paid at camp)","Gratuities"],"meetingPoint":"Hotel lobby in Sharm el-Sheikh or Na''ama Bay.","whatToBring":["Closed shoes","Long trousers","Sunglasses","Scarf for dust protection"],"cancellationPolicy":"Free cancellation up to 24 hours before the experience.","faq":[]},"ar":{"title":"سفاري الموتوسيكلات الرباعية في صحراء سيناء","duration":"3 ساعات","description":"أفضل طريقة لاستكشاف صحراء سيناء المذهلة — بجبالها الحمراء والمغرة وسهولها الواسعة ودروبها البدوية القديمة — هي الموتوسيكل الرباعي. تأخذك هذه الجولة مع مرشد عبر تضاريس صحراوية خلابة مع إطلالات على البحر الأحمر وجبال السعودية على الضفة الأخرى، وتنتهي في مخيم بدوي لكرم الضيافة التقليدي تحت النجوم.","highlights":["جولة عبر تضاريس صحراء سيناء — كثبان ودروب صخرية وإطلالات جبلية","إطلالات بانورامية على البحر الأحمر وجزيرة تيران","زيارة مخيم بدوي — شاي وشيشة ومشاهدة النجوم","توقيت الغروب لأجمل الصور","جميع معدات الأمان مشمولة"],"itinerary":[{"time":"15:30","activity":"الاستلام من الفندق"},{"time":"16:00","activity":"شرح السلامة والتعرف على الموتوسيكل"},{"time":"16:30","activity":"بداية الجولة — تضاريس متنوعة مع وقفات للمشاهدة"},{"time":"17:30","activity":"المخيم البدوي — مشاهدة الغروب والشاي والشيشة"},{"time":"18:30","activity":"العودة إلى الفندق"}],"included":["التنقلات من وإلى الفندق","موتوسيكل رباعي","معدات الأمان","شاي بدوي","مرشد"],"excluded":["الشيشة (اختيارية، تُدفع في المخيم)","الإكراميات"],"meetingPoint":"بهو الفندق في شرم الشيخ أو خليج نعمة.","whatToBring":["حذاء مغلق","بنطلون طويل","نظارة شمس","وشاح للحماية من الغبار"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل التجربة.","faq":[]},"fr":{"title":"Safari en quad dans le désert du Sinaï","duration":"3 heures","description":"Les paysages spectaculaires du Sinaï — montagnes rouges et ocre, vastes plaines et anciennes pistes bédouines — se découvrent idéalement en quad. Cette balade guidée traverse des terrains désertiques à couper le souffle, avec vue sur la mer Rouge et les montagnes d''Arabie saoudite sur l''autre rive. Elle se termine dans un camp bédouin pour une hospitalité traditionnelle sous les étoiles.","highlights":["Quad à travers le désert du Sinaï — dunes, pistes rocheuses et montagnes","Vues panoramiques sur la mer Rouge et l''île de Tiran","Visite d''un camp bédouin — thé, chicha et étoiles","Départ au coucher du soleil pour de superbes photos","Tout l''équipement de sécurité fourni"],"itinerary":[{"time":"15:30","activity":"Prise en charge à l''hôtel"},{"time":"16:00","activity":"Consignes de sécurité et prise en main du quad"},{"time":"16:30","activity":"Départ — terrains variés et arrêts panoramiques"},{"time":"17:30","activity":"Camp bédouin — coucher du soleil, thé et chicha"},{"time":"18:30","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Quad","Équipement de sécurité","Thé bédouin","Guide"],"excluded":["Chicha (facultative, payable au camp)","Pourboires"],"meetingPoint":"Hall de l''hôtel à Charm el-Cheikh ou Naama Bay.","whatToBring":["Chaussures fermées","Pantalon long","Lunettes de soleil","Foulard contre la poussière"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant l''expérience.","faq":[]},"de":{"title":"Quad-Safari in der Sinai-Wüste","duration":"3 Stunden","description":"Die dramatische Wüstenlandschaft des Sinai — rote und ockerfarbene Berge, weite Ebenen und alte Beduinenpfade — erkundet man am besten mit dem Quad. Diese geführte Tour führt durch atemberaubendes Gelände mit Blick auf das Rote Meer und die Berge Saudi-Arabiens auf der anderen Seite. Sie endet in einem Beduinencamp mit traditioneller Gastfreundschaft unter den Sternen.","highlights":["Quadfahrt durch die Sinai-Wüste — Dünen, Felspfade und Bergblicke","Panoramablicke auf das Rote Meer und die Insel Tiran","Besuch eines Beduinencamps — Tee, Shisha und Sternenhimmel","Sonnenuntergangstermin für Fotos im goldenen Licht","Komplette Sicherheitsausrüstung inklusive"],"itinerary":[{"time":"15:30","activity":"Abholung vom Hotel"},{"time":"16:00","activity":"Sicherheitseinweisung und Einführung ins Quad"},{"time":"16:30","activity":"Start der Tour — abwechslungsreiches Gelände mit Panoramastopps"},{"time":"17:30","activity":"Beduinencamp — Sonnenuntergang, Tee und Shisha"},{"time":"18:30","activity":"Rücktransfer zum Hotel"}],"included":["Hoteltransfers","Quad","Sicherheitsausrüstung","Beduinentee","Guide"],"excluded":["Shisha (optional, im Camp zu bezahlen)","Trinkgelder"],"meetingPoint":"Hotellobby in Scharm El-Scheich oder Naama Bay.","whatToBring":["Geschlossene Schuhe","Lange Hose","Sonnenbrille","Schal gegen Staub"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vorher.","faq":[]}}'::jsonb, null, true, 4, 11, true, true, false, 2)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('sharm-4', 'sharm', 'Water Sports', 1800, 900, 3, array['English', 'Arabic', 'Russian', 'German', 'Italian']::text[], true, true, 'Sinai Blue Diving', array['https://images.unsplash.com/photo-1638123657021-f9aca72f8caf?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1700482323555-182b61c90794?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1583157048761-ac1dba033233?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.9, 298, '[]'::jsonb, '{"en":{"title":"Intro Scuba Diving Experience","duration":"3 hours","description":"No certification required. Our PADI instructors give you everything you need to breathe underwater for the first time at one of the world''s best diving destinations. After a thorough pool briefing, you''ll enter the crystal-clear Red Sea for a guided reef dive alongside your instructor. The reefs of Sharm el-Sheikh have a density of marine life that rivals anywhere on earth.","highlights":["No prior experience required — full PADI instructor guidance","Pool session to learn breathing and basic skills","Open-water reef dive at a protected site","Maximum 2 students per instructor for safety and personal attention","All equipment provided — wetsuit, tank, BCD, mask","Underwater photos taken by your instructor"],"itinerary":[{"time":"09:00","activity":"Hotel pickup and transfer to dive center"},{"time":"09:30","activity":"Theory briefing and equipment fitting"},{"time":"10:00","activity":"Pool session — breathing and basic skills"},{"time":"11:00","activity":"Transfer to dive site"},{"time":"11:30","activity":"Open-water reef dive (approximately 40 minutes)"},{"time":"12:30","activity":"Debrief and hotel drop-off"}],"included":["Hotel transfers","PADI instructor","All dive equipment","Pool session","Open-water dive","Underwater photos"],"excluded":["Gratuities","Personal diving certification (separate course available)"],"meetingPoint":"Hotel lobby in Sharm el-Sheikh or Na''ama Bay.","whatToBring":["Swimwear","Towel","Sunscreen","Change of clothes"],"cancellationPolicy":"Free cancellation up to 24 hours before the experience.","faq":[{"question":"Is this safe for non-swimmers?","answer":"Basic swimming ability is required — you should be comfortable in water. Full flotation equipment is always worn."}]},"ar":{"title":"تجربة الغوص للمبتدئين","duration":"3 ساعات","description":"لا تحتاج أي شهادة. يقدم لك مدربونا المعتمدون من PADI كل ما تحتاجه لتتنفس تحت الماء لأول مرة في واحدة من أفضل وجهات الغوص في العالم. بعد شرح وافٍ في حمام السباحة، تنزل إلى مياه البحر الأحمر الصافية لغطسة على الشعاب برفقة مدربك. كثافة الحياة البحرية في شعاب شرم الشيخ تنافس أي مكان في العالم.","highlights":["لا تحتاج خبرة سابقة — إرشاد كامل من مدرب PADI","جلسة في حمام السباحة لتعلم التنفس والمهارات الأساسية","غطسة في البحر المفتوح على شعاب محمية","طالبان كحد أقصى لكل مدرب للأمان والاهتمام الشخصي","جميع المعدات مشمولة — بدلة وأسطوانة وسترة توازن وقناع","صور تحت الماء يلتقطها مدربك"],"itinerary":[{"time":"09:00","activity":"الاستلام من الفندق والتوجه إلى مركز الغوص"},{"time":"09:30","activity":"شرح نظري وتجهيز المعدات"},{"time":"10:00","activity":"جلسة حمام السباحة — التنفس والمهارات الأساسية"},{"time":"11:00","activity":"الانتقال إلى موقع الغوص"},{"time":"11:30","activity":"غطسة في البحر المفتوح (حوالي 40 دقيقة)"},{"time":"12:30","activity":"مراجعة التجربة والتوصيل إلى الفندق"}],"included":["التنقلات من وإلى الفندق","مدرب PADI","جميع معدات الغوص","جلسة حمام السباحة","غطسة في البحر المفتوح","صور تحت الماء"],"excluded":["الإكراميات","شهادة الغوص الشخصية (دورة منفصلة متاحة)"],"meetingPoint":"بهو الفندق في شرم الشيخ أو خليج نعمة.","whatToBring":["ملابس سباحة","منشفة","واقي شمس","ملابس للتغيير"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل التجربة.","faq":[{"question":"هل التجربة آمنة لغير السباحين؟","answer":"يلزم إجادة السباحة الأساسية وأن تكون مرتاحًا في الماء. يتم ارتداء معدات الطفو الكاملة طوال الوقت."}]},"fr":{"title":"Baptême de plongée sous-marine","duration":"3 heures","description":"Aucune certification requise. Nos instructeurs PADI vous donnent tout ce qu''il faut pour respirer sous l''eau pour la première fois dans l''une des meilleures destinations de plongée au monde. Après un briefing complet en piscine, vous entrerez dans les eaux cristallines de la mer Rouge pour une plongée guidée sur le récif aux côtés de votre instructeur. La densité de vie marine des récifs de Charm el-Cheikh rivalise avec les plus beaux sites de la planète.","highlights":["Aucune expérience requise — encadrement complet par un instructeur PADI","Séance en piscine pour apprendre la respiration et les bases","Plongée en mer sur un site protégé","2 élèves maximum par instructeur pour la sécurité","Tout l''équipement fourni — combinaison, bouteille, gilet, masque","Photos sous-marines prises par votre instructeur"],"itinerary":[{"time":"09:00","activity":"Prise en charge à l''hôtel et transfert au centre de plongée"},{"time":"09:30","activity":"Briefing théorique et ajustement de l''équipement"},{"time":"10:00","activity":"Séance en piscine — respiration et exercices de base"},{"time":"11:00","activity":"Transfert vers le site de plongée"},{"time":"11:30","activity":"Plongée en mer sur le récif (environ 40 minutes)"},{"time":"12:30","activity":"Débriefing et retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Instructeur PADI","Tout l''équipement de plongée","Séance en piscine","Plongée en mer","Photos sous-marines"],"excluded":["Pourboires","Certification de plongée personnelle (cours séparé disponible)"],"meetingPoint":"Hall de l''hôtel à Charm el-Cheikh ou Naama Bay.","whatToBring":["Maillot de bain","Serviette","Crème solaire","Vêtements de rechange"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant l''expérience.","faq":[{"question":"Est-ce sûr pour les non-nageurs ?","answer":"Il faut savoir nager un minimum et être à l''aise dans l''eau. Un équipement de flottaison complet est porté en permanence."}]},"de":{"title":"Schnuppertauchen für Einsteiger","duration":"3 Stunden","description":"Kein Tauchschein nötig. Unsere PADI-Tauchlehrer geben Ihnen alles mit, um an einem der besten Tauchreviere der Welt zum ersten Mal unter Wasser zu atmen. Nach einer gründlichen Einweisung im Pool geht es ins kristallklare Rote Meer zu einem geführten Rifftauchgang an der Seite Ihres Tauchlehrers. Die Riffe von Scharm El-Scheich bieten eine Dichte an Meeresleben, die weltweit ihresgleichen sucht.","highlights":["Keine Vorkenntnisse nötig — volle Betreuung durch PADI-Tauchlehrer","Pool-Session zum Erlernen von Atmung und Grundlagen","Freiwassertauchgang an einem geschützten Riff","Maximal 2 Schüler pro Tauchlehrer für Sicherheit und persönliche Betreuung","Komplette Ausrüstung — Anzug, Flasche, Jacket, Maske","Unterwasserfotos von Ihrem Tauchlehrer"],"itinerary":[{"time":"09:00","activity":"Abholung vom Hotel und Transfer zur Tauchbasis"},{"time":"09:30","activity":"Theorie-Briefing und Anpassen der Ausrüstung"},{"time":"10:00","activity":"Pool-Session — Atmung und Grundübungen"},{"time":"11:00","activity":"Transfer zum Tauchplatz"},{"time":"11:30","activity":"Freiwasser-Rifftauchgang (ca. 40 Minuten)"},{"time":"12:30","activity":"Nachbesprechung und Rücktransfer zum Hotel"}],"included":["Hoteltransfers","PADI-Tauchlehrer","Komplette Tauchausrüstung","Pool-Session","Freiwassertauchgang","Unterwasserfotos"],"excluded":["Trinkgelder","Eigener Tauchschein (separater Kurs möglich)"],"meetingPoint":"Hotellobby in Scharm El-Scheich oder Naama Bay.","whatToBring":["Badekleidung","Handtuch","Sonnencreme","Wechselkleidung"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vorher.","faq":[{"question":"Ist das sicher für Nichtschwimmer?","answer":"Grundlegende Schwimmkenntnisse sind erforderlich und Sie sollten sich im Wasser wohlfühlen. Eine vollständige Auftriebsausrüstung wird die ganze Zeit getragen."}]}}'::jsonb, null, true, 4, 11, true, true, false, 3)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('sharm-5', 'sharm', 'Desert & Adventure', 950, 475, 1.5, array['English', 'Arabic', 'Russian']::text[], true, true, 'Fly High Sharm', array['https://images.unsplash.com/photo-1625754884730-ba1e2eaafe91?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1583157048761-ac1dba033233?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1638123657021-f9aca72f8caf?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1700482323555-182b61c90794?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.6, 456, '[]'::jsonb, '{"en":{"title":"Parasailing over the Red Sea","duration":"1.5 hours","description":"Soar 150 metres above the turquoise Red Sea on a tandem parasail for a bird''s-eye view of Sharm el-Sheikh, Tiran Island, and the Sinai mountains. The launch and landing are from the motorboat — no beach run required — and the flight is smooth, peaceful, and breathtaking. Pairs go together, making this perfect for couples or friends.","highlights":["150-metre flight above the Red Sea — panoramic views in every direction","Tandem option for couples or friends flying together","Smooth boat launch and landing — no running required","Views of Tiran Island, the Sinai mountains, and Sharm coastline","GoPro footage included"],"itinerary":[{"time":"10:00","activity":"Hotel pickup"},{"time":"10:30","activity":"Arrive at beach — briefing and equipment fitting"},{"time":"11:00","activity":"Parasail flight — approximately 15 minutes in the air"},{"time":"11:30","activity":"Landing on motorboat — GoPro footage review"},{"time":"12:00","activity":"Return to hotel"}],"included":["Hotel transfers","Parasail flight","Life jacket","GoPro footage"],"excluded":["Gratuities"],"meetingPoint":"Hotel lobby in Sharm el-Sheikh or Na''ama Bay.","whatToBring":["Swimwear","Sunglasses","Secure footwear","Sunscreen"],"cancellationPolicy":"Free cancellation up to 24 hours before. Rescheduled if wind conditions are unsafe.","faq":[{"question":"Is there a weight limit?","answer":"For safety reasons, maximum single participant weight is 120 kg. Tandem maximum combined weight is 200 kg."}]},"ar":{"title":"الباراشوت فوق البحر الأحمر","duration":"1.5 ساعة","description":"حلّق على ارتفاع 150 مترًا فوق مياه البحر الأحمر الفيروزية بالباراشوت المزدوج، واستمتع بإطلالة علوية على شرم الشيخ وجزيرة تيران وجبال سيناء. الإقلاع والهبوط من القارب مباشرة بدون جري على الشاطئ، والطيران هادئ وسلس ومذهل. يمكن لشخصين الطيران معًا، فهي مثالية للأزواج والأصدقاء.","highlights":["طيران على ارتفاع 150 مترًا فوق البحر الأحمر — إطلالة في كل اتجاه","إمكانية الطيران المزدوج للأزواج أو الأصدقاء","إقلاع وهبوط سلس من القارب — بدون جري","إطلالات على جزيرة تيران وجبال سيناء وساحل شرم","تصوير فيديو GoPro مشمول"],"itinerary":[{"time":"10:00","activity":"الاستلام من الفندق"},{"time":"10:30","activity":"الوصول إلى الشاطئ — شرح وتجهيز المعدات"},{"time":"11:00","activity":"رحلة الباراشوت — حوالي 15 دقيقة في الجو"},{"time":"11:30","activity":"الهبوط على القارب — مشاهدة فيديو GoPro"},{"time":"12:00","activity":"العودة إلى الفندق"}],"included":["التنقلات من وإلى الفندق","رحلة الباراشوت","سترة نجاة","فيديو GoPro"],"excluded":["الإكراميات"],"meetingPoint":"بهو الفندق في شرم الشيخ أو خليج نعمة.","whatToBring":["ملابس سباحة","نظارة شمس","حذاء مثبت جيدًا","واقي شمس"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الموعد. تُعاد الجدولة إذا كانت الرياح غير آمنة.","faq":[{"question":"هل يوجد حد للوزن؟","answer":"لأسباب تتعلق بالسلامة، الحد الأقصى لوزن الفرد 120 كجم، والحد الأقصى للوزن المجمّع في الطيران المزدوج 200 كجم."}]},"fr":{"title":"Parachute ascensionnel au-dessus de la mer Rouge","duration":"1,5 heure","description":"Envolez-vous à 150 mètres au-dessus de la mer Rouge turquoise en parachute ascensionnel biplace, avec une vue plongeante sur Charm el-Cheikh, l''île de Tiran et les montagnes du Sinaï. Décollage et atterrissage se font depuis le bateau — inutile de courir sur la plage — et le vol est doux, paisible et époustouflant. On vole à deux : parfait pour les couples ou les amis.","highlights":["Vol à 150 mètres au-dessus de la mer Rouge — panorama à 360°","Option biplace pour voler en couple ou entre amis","Décollage et atterrissage en douceur depuis le bateau","Vue sur l''île de Tiran, les montagnes du Sinaï et la côte de Charm","Vidéo GoPro incluse"],"itinerary":[{"time":"10:00","activity":"Prise en charge à l''hôtel"},{"time":"10:30","activity":"Arrivée à la plage — briefing et équipement"},{"time":"11:00","activity":"Vol en parachute — environ 15 minutes dans les airs"},{"time":"11:30","activity":"Atterrissage sur le bateau — visionnage de la vidéo GoPro"},{"time":"12:00","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Vol en parachute ascensionnel","Gilet de sauvetage","Vidéo GoPro"],"excluded":["Pourboires"],"meetingPoint":"Hall de l''hôtel à Charm el-Cheikh ou Naama Bay.","whatToBring":["Maillot de bain","Lunettes de soleil","Chaussures bien attachées","Crème solaire"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant. Report si le vent rend le vol dangereux.","faq":[{"question":"Y a-t-il une limite de poids ?","answer":"Pour des raisons de sécurité, le poids maximum est de 120 kg en solo et de 200 kg cumulés en biplace."}]},"de":{"title":"Parasailing über dem Roten Meer","duration":"1,5 Stunden","description":"Schweben Sie beim Tandem-Parasailing 150 Meter über dem türkisblauen Roten Meer und genießen Sie die Vogelperspektive auf Scharm El-Scheich, die Insel Tiran und die Sinai-Berge. Start und Landung erfolgen direkt vom Motorboot — kein Anlauf am Strand nötig — und der Flug ist ruhig, friedlich und atemberaubend. Zwei Personen fliegen zusammen: perfekt für Paare oder Freunde.","highlights":["Flug in 150 Metern Höhe über dem Roten Meer — Panorama in alle Richtungen","Tandemflug für Paare oder Freunde","Sanfter Start und Landung vom Boot — kein Laufen nötig","Blick auf die Insel Tiran, die Sinai-Berge und die Küste von Scharm","GoPro-Video inklusive"],"itinerary":[{"time":"10:00","activity":"Abholung vom Hotel"},{"time":"10:30","activity":"Ankunft am Strand — Einweisung und Ausrüstung"},{"time":"11:00","activity":"Parasailing-Flug — etwa 15 Minuten in der Luft"},{"time":"11:30","activity":"Landung auf dem Boot — GoPro-Video ansehen"},{"time":"12:00","activity":"Rücktransfer zum Hotel"}],"included":["Hoteltransfers","Parasailing-Flug","Schwimmweste","GoPro-Video"],"excluded":["Trinkgelder"],"meetingPoint":"Hotellobby in Scharm El-Scheich oder Naama Bay.","whatToBring":["Badekleidung","Sonnenbrille","Festes Schuhwerk","Sonnencreme"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vorher. Verschiebung, wenn der Wind zu stark ist.","faq":[{"question":"Gibt es eine Gewichtsgrenze?","answer":"Aus Sicherheitsgründen liegt das Höchstgewicht bei 120 kg für Einzelflieger und 200 kg zusammen beim Tandemflug."}]}}'::jsonb, null, true, 4, 11, true, true, false, 4)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('cairo-1', 'cairo', 'Cultural & Historical', 1450, 725, 4, array['English', 'Arabic', 'German', 'Italian']::text[], true, true, 'Cairo Heritage Tours', array['https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844610-40f1ad10d07e?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1539768942893-daf53e448371?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.9, 428, '[]'::jsonb, '{"en":{"title":"Grand Egyptian Museum Private Tour","duration":"4 hours","description":"Explore one of the world''s greatest museums with a certified Egyptologist who brings ancient history to life. The Grand Egyptian Museum houses over 100,000 artefacts including the complete treasures of Tutankhamun. Skip the general queues and access the private galleries for an intimate encounter with 5,000 years of human civilization.","highlights":["Private certified Egyptologist guide for your group only","Full Tutankhamun treasure collection including the golden death mask","Access to the Grand Atrium with the 11-meter Ramesses II statue","Behind-the-scenes access to galleries before they open to the public","Detailed commentary on hieroglyphics, mummification, and royal dynasties","Skip-the-line entry tickets included"],"itinerary":[{"time":"08:30","activity":"Hotel pickup from Cairo or Giza"},{"time":"09:30","activity":"Arrive at the Grand Egyptian Museum — skip-the-line entry"},{"time":"09:45","activity":"Grand Atrium and Ramesses II statue"},{"time":"10:30","activity":"Tutankhamun galleries — 5,400+ artefacts"},{"time":"12:00","activity":"Royal Mummies Hall and ancient jewellery"},{"time":"13:00","activity":"Final walk through civilisation halls"},{"time":"13:30","activity":"Return transfer to hotel"}],"included":["Hotel pickup and drop-off","Skip-the-line GEM entrance tickets","Private licensed Egyptologist guide","Bottled water"],"excluded":["Personal shopping","Camera permits","Gratuities"],"meetingPoint":"Hotel lobby. Service available from Cairo, Giza, and Zamalek.","whatToBring":["Comfortable walking shoes","Light jacket (museum is air-conditioned)","Camera"],"cancellationPolicy":"Free cancellation up to 24 hours before the experience.","faq":[{"question":"Is the golden mask of Tutankhamun on display?","answer":"Yes — the complete Tutankhamun collection including the iconic golden death mask is permanently housed at the Grand Egyptian Museum."}]},"ar":{"title":"جولة خاصة في المتحف المصري الكبير","duration":"4 ساعات","description":"استكشف أحد أعظم متاحف العالم مع عالم مصريات معتمد يعيد الحياة إلى التاريخ القديم. يضم المتحف المصري الكبير أكثر من 100 ألف قطعة أثرية، منها كنوز توت عنخ آمون كاملة. تجاوز طوابير الانتظار وادخل القاعات الخاصة في لقاء قريب مع 5000 عام من الحضارة الإنسانية.","highlights":["مرشد خاص معتمد في علم المصريات لمجموعتك فقط","مجموعة كنوز توت عنخ آمون كاملة ومنها القناع الذهبي","البهو العظيم وتمثال رمسيس الثاني بارتفاع 11 مترًا","دخول بعض القاعات قبل فتحها للجمهور","شرح تفصيلي عن الهيروغليفية والتحنيط والأسرات الملكية","تذاكر دخول بدون انتظار مشمولة"],"itinerary":[{"time":"08:30","activity":"الاستلام من الفندق في القاهرة أو الجيزة"},{"time":"09:30","activity":"الوصول إلى المتحف المصري الكبير — دخول بدون انتظار"},{"time":"09:45","activity":"البهو العظيم وتمثال رمسيس الثاني"},{"time":"10:30","activity":"قاعات توت عنخ آمون — أكثر من 5400 قطعة"},{"time":"12:00","activity":"قاعة المومياوات الملكية والحلي القديمة"},{"time":"13:00","activity":"جولة أخيرة في قاعات الحضارة"},{"time":"13:30","activity":"العودة إلى الفندق"}],"included":["الاستلام والتوصيل من وإلى الفندق","تذاكر دخول المتحف بدون انتظار","مرشد خاص مرخّص في علم المصريات","مياه معبأة"],"excluded":["المشتريات الشخصية","تصاريح التصوير","الإكراميات"],"meetingPoint":"بهو الفندق. الخدمة متاحة من القاهرة والجيزة والزمالك.","whatToBring":["حذاء مريح للمشي","جاكيت خفيف (المتحف مكيّف)","كاميرا"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل التجربة.","faq":[{"question":"هل قناع توت عنخ آمون الذهبي معروض؟","answer":"نعم، مجموعة توت عنخ آمون كاملة ومنها القناع الذهبي الشهير معروضة بشكل دائم في المتحف المصري الكبير."}]},"fr":{"title":"Visite privée du Grand Musée égyptien","duration":"4 heures","description":"Explorez l''un des plus grands musées du monde avec un égyptologue diplômé qui fait revivre l''histoire antique. Le Grand Musée égyptien abrite plus de 100 000 objets, dont l''intégralité du trésor de Toutânkhamon. Évitez les files d''attente et accédez aux galeries privées pour une rencontre intime avec 5 000 ans de civilisation.","highlights":["Guide égyptologue diplômé privé, uniquement pour votre groupe","La collection complète de Toutânkhamon, dont le masque funéraire en or","Le Grand Atrium et la statue de Ramsès II de 11 mètres","Accès à certaines galeries avant leur ouverture au public","Explications détaillées sur les hiéroglyphes, la momification et les dynasties","Billets coupe-file inclus"],"itinerary":[{"time":"08:30","activity":"Prise en charge à l''hôtel au Caire ou à Gizeh"},{"time":"09:30","activity":"Arrivée au Grand Musée égyptien — entrée coupe-file"},{"time":"09:45","activity":"Grand Atrium et statue de Ramsès II"},{"time":"10:30","activity":"Galeries de Toutânkhamon — plus de 5 400 objets"},{"time":"12:00","activity":"Salle des momies royales et bijoux antiques"},{"time":"13:00","activity":"Dernière promenade dans les salles de la civilisation"},{"time":"13:30","activity":"Retour à l''hôtel"}],"included":["Prise en charge et retour à l''hôtel","Billets d''entrée coupe-file au GEM","Guide égyptologue privé agréé","Eau en bouteille"],"excluded":["Achats personnels","Permis photo","Pourboires"],"meetingPoint":"Hall de l''hôtel. Service disponible au Caire, à Gizeh et à Zamalek.","whatToBring":["Chaussures de marche confortables","Veste légère (le musée est climatisé)","Appareil photo"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant l''expérience.","faq":[{"question":"Le masque d''or de Toutânkhamon est-il exposé ?","answer":"Oui, la collection complète de Toutânkhamon, y compris le célèbre masque funéraire en or, est exposée en permanence au Grand Musée égyptien."}]},"de":{"title":"Private Tour durch das Große Ägyptische Museum","duration":"4 Stunden","description":"Entdecken Sie eines der größten Museen der Welt mit einem zertifizierten Ägyptologen, der die Geschichte lebendig werden lässt. Das Große Ägyptische Museum beherbergt über 100.000 Artefakte, darunter den vollständigen Schatz des Tutanchamun. Umgehen Sie die Warteschlangen und erleben Sie in den privaten Galerien eine persönliche Begegnung mit 5.000 Jahren Zivilisation.","highlights":["Privater, zertifizierter Ägyptologe nur für Ihre Gruppe","Die komplette Tutanchamun-Sammlung inklusive der goldenen Totenmaske","Das Große Atrium mit der 11 Meter hohen Statue von Ramses II.","Zugang zu Galerien vor der Öffnung für die Öffentlichkeit","Ausführliche Erklärungen zu Hieroglyphen, Mumifizierung und Dynastien","Tickets ohne Anstehen inklusive"],"itinerary":[{"time":"08:30","activity":"Abholung vom Hotel in Kairo oder Gizeh"},{"time":"09:30","activity":"Ankunft am Großen Ägyptischen Museum — Eintritt ohne Anstehen"},{"time":"09:45","activity":"Großes Atrium und Statue von Ramses II."},{"time":"10:30","activity":"Tutanchamun-Galerien — über 5.400 Objekte"},{"time":"12:00","activity":"Saal der Königsmumien und antiker Schmuck"},{"time":"13:00","activity":"Abschließender Rundgang durch die Zivilisationssäle"},{"time":"13:30","activity":"Rücktransfer zum Hotel"}],"included":["Abholung und Rücktransfer vom Hotel","GEM-Tickets ohne Anstehen","Privater, lizenzierter Ägyptologe","Wasser in Flaschen"],"excluded":["Persönliche Einkäufe","Fotogenehmigungen","Trinkgelder"],"meetingPoint":"Hotellobby. Service in Kairo, Gizeh und Zamalek.","whatToBring":["Bequeme Schuhe","Leichte Jacke (das Museum ist klimatisiert)","Kamera"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vorher.","faq":[{"question":"Ist die goldene Maske des Tutanchamun ausgestellt?","answer":"Ja — die komplette Tutanchamun-Sammlung einschließlich der berühmten goldenen Totenmaske ist dauerhaft im Großen Ägyptischen Museum zu sehen."}]}}'::jsonb, null, true, 4, 11, true, true, false, 0)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('cairo-2', 'cairo', 'Cultural & Historical', 1200, 600, 5, array['English', 'Arabic', 'German', 'Italian', 'Russian']::text[], true, true, 'Pharaoh''s Path', array['https://images.unsplash.com/photo-1539768942893-daf53e448371?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844610-40f1ad10d07e?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.8, 1204, '[]'::jsonb, '{"en":{"title":"Pyramids & Sphinx Private Tour","duration":"5 hours","description":"Stand before the last surviving wonder of the ancient world with a private Egyptologist guide who knows every stone. This tour covers the Great Pyramid of Khufu, the Pyramid of Khafre, the Pyramid of Menkaure, and the iconic Great Sphinx — with optional entry inside the pyramid chambers. This is not a group bus tour: it''s a thoughtful, unhurried exploration of one of humanity''s greatest achievements.","highlights":["Private guide for your group — no strangers, no rushing","Great Pyramid, Pyramid of Khafre, and Pyramid of Menkaure","The Great Sphinx and the Valley Temple","Optional interior entry to a pyramid chamber","Panoramic photo spot with all three pyramids","Camel or horse ride option (paid locally)"],"itinerary":[{"time":"07:00","activity":"Hotel pickup from Cairo or Giza"},{"time":"08:00","activity":"Arrive at Giza Plateau — Great Pyramid of Khufu"},{"time":"09:30","activity":"Pyramid of Khafre and panoramic viewpoint"},{"time":"10:30","activity":"The Great Sphinx and Valley Temple"},{"time":"11:30","activity":"Solar Boat Museum"},{"time":"12:30","activity":"Return transfer to hotel"}],"included":["Hotel pickup and drop-off","Entry tickets to the Giza Plateau","Private licensed Egyptologist guide","Air-conditioned vehicle","Bottled water"],"excluded":["Interior pyramid entry (optional, paid locally)","Camel or horse ride","Gratuities"],"meetingPoint":"Hotel lobby. Available from all Cairo and Giza hotels.","whatToBring":["Comfortable shoes","Sun hat and sunscreen","Camera"],"cancellationPolicy":"Free cancellation up to 24 hours before the tour.","faq":[{"question":"Can we go inside the pyramid?","answer":"Yes — interior entry to the Great Pyramid is available for an additional fee paid on site. The guide will explain what to expect."}]},"ar":{"title":"جولة خاصة للأهرامات وأبو الهول","duration":"5 ساعات","description":"قف أمام آخر عجائب الدنيا السبع القديمة الباقية مع مرشد خاص في علم المصريات يعرف كل حجر فيها. تشمل الجولة الهرم الأكبر لخوفو وهرم خفرع وهرم منكاورع وتمثال أبو الهول الشهير، مع إمكانية دخول غرف الهرم. هذه ليست رحلة أتوبيس جماعية، بل استكشاف هادئ ومتأنٍ لواحد من أعظم إنجازات البشرية.","highlights":["مرشد خاص لمجموعتك — بدون غرباء وبدون استعجال","الهرم الأكبر وهرم خفرع وهرم منكاورع","أبو الهول ومعبد الوادي","إمكانية دخول إحدى غرف الهرم (اختياري)","نقطة تصوير بانورامية للأهرامات الثلاثة","إمكانية ركوب الجمل أو الحصان (يُدفع في الموقع)"],"itinerary":[{"time":"07:00","activity":"الاستلام من الفندق في القاهرة أو الجيزة"},{"time":"08:00","activity":"الوصول إلى هضبة الجيزة — الهرم الأكبر لخوفو"},{"time":"09:30","activity":"هرم خفرع ونقطة المشاهدة البانورامية"},{"time":"10:30","activity":"أبو الهول ومعبد الوادي"},{"time":"11:30","activity":"متحف مركب الشمس"},{"time":"12:30","activity":"العودة إلى الفندق"}],"included":["الاستلام والتوصيل من وإلى الفندق","تذاكر دخول هضبة الجيزة","مرشد خاص مرخّص في علم المصريات","سيارة مكيّفة","مياه معبأة"],"excluded":["دخول الهرم من الداخل (اختياري، يُدفع في الموقع)","ركوب الجمل أو الحصان","الإكراميات"],"meetingPoint":"بهو الفندق. متاح من كل فنادق القاهرة والجيزة.","whatToBring":["حذاء مريح","قبعة وواقي شمس","كاميرا"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الجولة.","faq":[{"question":"هل يمكننا دخول الهرم؟","answer":"نعم، دخول الهرم الأكبر من الداخل متاح برسوم إضافية تُدفع في الموقع، وسيشرح لك المرشد ما ستراه."}]},"fr":{"title":"Visite privée des pyramides et du Sphinx","duration":"5 heures","description":"Tenez-vous devant la dernière merveille du monde antique encore debout, avec un égyptologue privé qui en connaît chaque pierre. La visite comprend la Grande Pyramide de Khéops, les pyramides de Khéphren et de Mykérinos et le célèbre Grand Sphinx, avec possibilité d''entrer dans une chambre funéraire. Pas de visite en bus bondé : une découverte sereine et sans précipitation de l''une des plus grandes réalisations de l''humanité.","highlights":["Guide privé pour votre groupe — sans inconnus, sans précipitation","Grande Pyramide, pyramides de Khéphren et de Mykérinos","Le Grand Sphinx et le temple de la Vallée","Entrée facultative dans une chambre de pyramide","Point de vue panoramique sur les trois pyramides","Balade à dos de chameau ou de cheval possible (à régler sur place)"],"itinerary":[{"time":"07:00","activity":"Prise en charge à l''hôtel au Caire ou à Gizeh"},{"time":"08:00","activity":"Arrivée sur le plateau de Gizeh — Grande Pyramide de Khéops"},{"time":"09:30","activity":"Pyramide de Khéphren et point de vue panoramique"},{"time":"10:30","activity":"Le Grand Sphinx et le temple de la Vallée"},{"time":"11:30","activity":"Musée de la barque solaire"},{"time":"12:30","activity":"Retour à l''hôtel"}],"included":["Prise en charge et retour à l''hôtel","Billets d''entrée du plateau de Gizeh","Guide égyptologue privé agréé","Véhicule climatisé","Eau en bouteille"],"excluded":["Entrée dans la pyramide (facultative, à régler sur place)","Balade à chameau ou à cheval","Pourboires"],"meetingPoint":"Hall de l''hôtel. Disponible dans tous les hôtels du Caire et de Gizeh.","whatToBring":["Chaussures confortables","Chapeau et crème solaire","Appareil photo"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la visite.","faq":[{"question":"Peut-on entrer dans la pyramide ?","answer":"Oui, l''accès à l''intérieur de la Grande Pyramide est possible moyennant un supplément payé sur place. Le guide vous expliquera ce que vous verrez."}]},"de":{"title":"Private Tour zu Pyramiden und Sphinx","duration":"5 Stunden","description":"Stehen Sie vor dem letzten erhaltenen Weltwunder der Antike — mit einem privaten Ägyptologen, der jeden Stein kennt. Die Tour umfasst die Cheops-Pyramide, die Chephren- und die Mykerinos-Pyramide sowie die berühmte Große Sphinx, auf Wunsch mit Besuch einer Grabkammer. Keine Massenbustour, sondern eine ruhige, ausführliche Erkundung einer der größten Leistungen der Menschheit.","highlights":["Privater Guide für Ihre Gruppe — keine Fremden, keine Eile","Cheops-, Chephren- und Mykerinos-Pyramide","Die Große Sphinx und der Taltempel","Optionaler Besuch einer Pyramidenkammer","Panorama-Fotopunkt mit allen drei Pyramiden","Kamel- oder Pferderitt möglich (vor Ort zu bezahlen)"],"itinerary":[{"time":"07:00","activity":"Abholung vom Hotel in Kairo oder Gizeh"},{"time":"08:00","activity":"Ankunft auf dem Gizeh-Plateau — Cheops-Pyramide"},{"time":"09:30","activity":"Chephren-Pyramide und Panoramapunkt"},{"time":"10:30","activity":"Die Große Sphinx und der Taltempel"},{"time":"11:30","activity":"Sonnenbarken-Museum"},{"time":"12:30","activity":"Rücktransfer zum Hotel"}],"included":["Abholung und Rücktransfer vom Hotel","Eintritt zum Gizeh-Plateau","Privater, lizenzierter Ägyptologe","Klimatisiertes Fahrzeug","Wasser in Flaschen"],"excluded":["Eintritt in die Pyramide (optional, vor Ort)","Kamel- oder Pferderitt","Trinkgelder"],"meetingPoint":"Hotellobby. Von allen Hotels in Kairo und Gizeh.","whatToBring":["Bequeme Schuhe","Sonnenhut und Sonnencreme","Kamera"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Tour.","faq":[{"question":"Können wir in die Pyramide hinein?","answer":"Ja, der Zugang ins Innere der Cheops-Pyramide ist gegen eine vor Ort zu zahlende Gebühr möglich. Ihr Guide erklärt Ihnen, was Sie erwartet."}]}}'::jsonb, null, true, 4, 11, true, true, false, 1)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('cairo-3', 'cairo', 'Cultural & Historical', 550, 275, 4, array['English', 'Arabic', 'German']::text[], true, true, 'Cairo Hidden Paths', array['https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1539768942893-daf53e448371?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844610-40f1ad10d07e?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.7, 332, '[]'::jsonb, '{"en":{"title":"Old Cairo & Islamic Quarter Walking Tour","duration":"4 hours","description":"Walk through a city within a city — the medieval Islamic quarter of Cairo that UNESCO has declared a World Heritage Site. Your guide takes you through narrow alleys that have barely changed since the 10th century, past ancient mosques, covered bazaars, craftsmen''s workshops, and hidden courtyards. This is Cairo beyond the tourist sites.","highlights":["Al-Muizz Street — the world''s longest open-air museum of Islamic architecture","Khan el-Khalili bazaar — Egypt''s most famous market","Al-Azhar Mosque — over 1,000 years of Islamic scholarship","Coptic Cairo — ancient churches and the Hanging Church","Traditional tea in a 14th-century caravanserai","Small group maximum 8 people"],"itinerary":[{"time":"09:00","activity":"Meet at Al-Hussein Mosque, Islamic Quarter"},{"time":"09:15","activity":"Al-Muizz Street and Fatimid city gates"},{"time":"10:00","activity":"Al-Azhar Mosque visit"},{"time":"10:45","activity":"Khan el-Khalili bazaar — craft workshops and tea"},{"time":"12:00","activity":"Coptic Cairo — Hanging Church and Ben Ezra Synagogue"},{"time":"13:00","activity":"Tour ends. Optional lunch nearby."}],"included":["Private licensed guide","Entrance fees to religious sites","Traditional Egyptian tea","Bottled water"],"excluded":["Lunch","Shopping","Transportation to meeting point","Gratuities"],"meetingPoint":"Al-Hussein Mosque courtyard, Islamic Cairo. Hotel pickup available for extra charge.","whatToBring":["Comfortable walking shoes","Modest clothing (shoulders and knees covered — scarves provided if needed)","Cash for shopping"],"cancellationPolicy":"Free cancellation up to 24 hours before the tour.","faq":[{"question":"Do I need to dress modestly?","answer":"Yes, for mosque visits shoulders and knees should be covered. We provide scarves and covers at no extra cost."}]},"ar":{"title":"جولة سيرًا في القاهرة القديمة والقاهرة الإسلامية","duration":"4 ساعات","description":"تجوّل في مدينة داخل المدينة — القاهرة الإسلامية التاريخية المسجلة على قائمة اليونسكو للتراث العالمي. يأخذك المرشد عبر حواري ضيقة لم تتغير كثيرًا منذ القرن العاشر، مرورًا بالمساجد العريقة والأسواق المسقوفة وورش الحرفيين والأفنية الخفية. هذه هي القاهرة بعيدًا عن المزارات السياحية المعتادة.","highlights":["شارع المعز — أكبر متحف مفتوح للعمارة الإسلامية في العالم","خان الخليلي — أشهر أسواق مصر","الجامع الأزهر — أكثر من 1000 عام من العلم","مصر القديمة — الكنائس التاريخية والكنيسة المعلقة","شاي تقليدي في وكالة من القرن الرابع عشر","مجموعة صغيرة لا تتجاوز 8 أشخاص"],"itinerary":[{"time":"09:00","activity":"اللقاء عند مسجد الحسين في القاهرة الإسلامية"},{"time":"09:15","activity":"شارع المعز وأبواب القاهرة الفاطمية"},{"time":"10:00","activity":"زيارة الجامع الأزهر"},{"time":"10:45","activity":"خان الخليلي — ورش الحرف اليدوية والشاي"},{"time":"12:00","activity":"مصر القديمة — الكنيسة المعلقة ومعبد بن عزرا"},{"time":"13:00","activity":"نهاية الجولة. إمكانية الغداء في مكان قريب."}],"included":["مرشد خاص مرخّص","رسوم دخول المواقع الدينية","شاي مصري تقليدي","مياه معبأة"],"excluded":["الغداء","المشتريات","المواصلات إلى نقطة اللقاء","الإكراميات"],"meetingPoint":"ساحة مسجد الحسين بالقاهرة الإسلامية. الاستلام من الفندق متاح برسوم إضافية.","whatToBring":["حذاء مريح للمشي","ملابس محتشمة (تغطي الكتفين والركبتين — نوفر أوشحة عند الحاجة)","نقود للتسوق"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الجولة.","faq":[{"question":"هل يجب ارتداء ملابس محتشمة؟","answer":"نعم، لزيارة المساجد يجب تغطية الكتفين والركبتين، ونوفر الأوشحة والأغطية مجانًا."}]},"fr":{"title":"Promenade dans le Vieux-Caire et le quartier islamique","duration":"4 heures","description":"Parcourez une ville dans la ville : le Caire islamique médiéval, inscrit au patrimoine mondial de l''UNESCO. Votre guide vous emmène dans des ruelles qui ont à peine changé depuis le Xe siècle, entre mosquées anciennes, bazars couverts, ateliers d''artisans et cours cachées. Le Caire au-delà des sites touristiques.","highlights":["Rue Al-Muizz — le plus grand musée à ciel ouvert d''architecture islamique","Bazar de Khan el-Khalili — le marché le plus célèbre d''Égypte","Mosquée Al-Azhar — plus de 1 000 ans de savoir","Le Caire copte — églises anciennes et Église suspendue","Thé traditionnel dans un caravansérail du XIVe siècle","Petit groupe de 8 personnes maximum"],"itinerary":[{"time":"09:00","activity":"Rendez-vous à la mosquée Al-Hussein, quartier islamique"},{"time":"09:15","activity":"Rue Al-Muizz et portes de la ville fatimide"},{"time":"10:00","activity":"Visite de la mosquée Al-Azhar"},{"time":"10:45","activity":"Bazar de Khan el-Khalili — ateliers d''artisans et thé"},{"time":"12:00","activity":"Le Caire copte — Église suspendue et synagogue Ben Ezra"},{"time":"13:00","activity":"Fin de la visite. Déjeuner possible à proximité."}],"included":["Guide privé agréé","Droits d''entrée des sites religieux","Thé égyptien traditionnel","Eau en bouteille"],"excluded":["Déjeuner","Achats","Transport jusqu''au point de rendez-vous","Pourboires"],"meetingPoint":"Cour de la mosquée Al-Hussein, Caire islamique. Prise en charge à l''hôtel possible avec supplément.","whatToBring":["Chaussures de marche confortables","Tenue correcte (épaules et genoux couverts — foulards fournis si besoin)","Espèces pour les achats"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la visite.","faq":[{"question":"Faut-il une tenue correcte ?","answer":"Oui, pour visiter les mosquées, les épaules et les genoux doivent être couverts. Nous fournissons gratuitement foulards et étoles."}]},"de":{"title":"Rundgang durch Alt-Kairo und das Islamische Viertel","duration":"4 Stunden","description":"Spazieren Sie durch eine Stadt in der Stadt — das mittelalterliche islamische Kairo, UNESCO-Weltkulturerbe. Ihr Guide führt Sie durch enge Gassen, die sich seit dem 10. Jahrhundert kaum verändert haben, vorbei an alten Moscheen, überdachten Basaren, Handwerkerwerkstätten und versteckten Innenhöfen. Kairo jenseits der Touristenpfade.","highlights":["Al-Muizz-Straße — das größte Freilichtmuseum islamischer Architektur","Basar Khan el-Khalili — Ägyptens berühmtester Markt","Al-Azhar-Moschee — über 1.000 Jahre Gelehrsamkeit","Koptisches Kairo — alte Kirchen und die Hängende Kirche","Traditioneller Tee in einer Karawanserei aus dem 14. Jahrhundert","Kleine Gruppe mit maximal 8 Personen"],"itinerary":[{"time":"09:00","activity":"Treffpunkt an der Al-Hussein-Moschee im Islamischen Viertel"},{"time":"09:15","activity":"Al-Muizz-Straße und fatimidische Stadttore"},{"time":"10:00","activity":"Besuch der Al-Azhar-Moschee"},{"time":"10:45","activity":"Basar Khan el-Khalili — Werkstätten und Tee"},{"time":"12:00","activity":"Koptisches Kairo — Hängende Kirche und Ben-Esra-Synagoge"},{"time":"13:00","activity":"Ende der Tour. Mittagessen in der Nähe möglich."}],"included":["Privater, lizenzierter Guide","Eintritt zu religiösen Stätten","Traditioneller ägyptischer Tee","Wasser in Flaschen"],"excluded":["Mittagessen","Einkäufe","Anfahrt zum Treffpunkt","Trinkgelder"],"meetingPoint":"Innenhof der Al-Hussein-Moschee, Islamisches Kairo. Hotelabholung gegen Aufpreis möglich.","whatToBring":["Bequeme Schuhe","Angemessene Kleidung (Schultern und Knie bedeckt — Tücher werden bei Bedarf gestellt)","Bargeld zum Einkaufen"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Tour.","faq":[{"question":"Muss ich mich bedeckt kleiden?","answer":"Ja, für Moscheebesuche müssen Schultern und Knie bedeckt sein. Tücher und Umhänge stellen wir kostenlos zur Verfügung."}]}}'::jsonb, null, true, 4, 11, true, true, false, 2)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('cairo-4', 'cairo', 'Cruises & Sailing', 980, 490, 3, array['English', 'Arabic']::text[], true, true, 'Nile Star Cruises', array['https://images.unsplash.com/photo-1730190202188-bc742975d595?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1734777360073-397330427a3f?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1684100096410-fd39cdff91a3?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1707266327255-1f0199f22b33?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1625754884730-ba1e2eaafe91?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.5, 987, '[]'::jsonb, '{"en":{"title":"Nile Dinner Cruise","duration":"3 hours","description":"Glide along the Nile at night on a beautifully lit dinner cruise, watching Cairo''s skyline shimmer on the water. Enjoy a lavish buffet dinner with Egyptian and international dishes, live oriental music, and traditional Tanoura whirling dervish and belly dance performances. The Nile at night is one of Cairo''s great spectacles.","highlights":["Two-deck Nile cruise ship with panoramic views","Lavish buffet — Egyptian mezze, grills, and desserts","Live oriental music and traditional performances","Tanoura dance and belly dance show","Views of Cairo, Zamalek, and the iconic bridges lit at night"],"itinerary":[{"time":"20:00","activity":"Hotel pickup and transfer to Nile marina"},{"time":"20:30","activity":"Board the cruise ship — welcome drinks"},{"time":"21:00","activity":"Cruise departs — dinner service begins"},{"time":"21:30","activity":"Live music and cultural performances"},{"time":"23:00","activity":"Return to dock"},{"time":"23:30","activity":"Hotel drop-off"}],"included":["Hotel transfers","Cruise ticket","Buffet dinner","Soft drinks and juices","Live entertainment"],"excluded":["Alcoholic beverages","Gratuities"],"meetingPoint":"Hotel pickup throughout Cairo.","whatToBring":["Smart-casual attire","Camera"],"cancellationPolicy":"Free cancellation up to 24 hours before departure.","faq":[{"question":"Is alcohol available?","answer":"Yes, alcoholic beverages are available for purchase on board."}]},"ar":{"title":"عشاء على متن مركب في النيل","duration":"3 ساعات","description":"تهادَ على مياه النيل ليلًا في رحلة عشاء على مركب مضاء بشكل رائع، وشاهد أضواء القاهرة تتلألأ على صفحة الماء. استمتع ببوفيه عشاء فاخر من الأطباق المصرية والعالمية، وموسيقى شرقية حية، وعروض التنورة والرقص الشرقي. النيل ليلًا من أجمل مشاهد القاهرة.","highlights":["مركب نيلي بطابقين وإطلالات بانورامية","بوفيه فاخر — مقبلات مصرية ومشويات وحلويات","موسيقى شرقية حية وعروض تراثية","عرض التنورة والرقص الشرقي","إطلالة على القاهرة والزمالك والكباري المضاءة ليلًا"],"itinerary":[{"time":"20:00","activity":"الاستلام من الفندق والتوجه إلى مرسى النيل"},{"time":"20:30","activity":"الصعود إلى المركب — مشروبات ترحيبية"},{"time":"21:00","activity":"انطلاق المركب — بداية تقديم العشاء"},{"time":"21:30","activity":"موسيقى حية وعروض فنية"},{"time":"23:00","activity":"العودة إلى المرسى"},{"time":"23:30","activity":"التوصيل إلى الفندق"}],"included":["التنقلات من وإلى الفندق","تذكرة الرحلة النيلية","بوفيه العشاء","مشروبات غازية وعصائر","العروض الفنية الحية"],"excluded":["المشروبات الكحولية","الإكراميات"],"meetingPoint":"الاستلام من الفنادق في كل أنحاء القاهرة.","whatToBring":["ملابس أنيقة غير رسمية","كاميرا"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الانطلاق.","faq":[{"question":"هل تتوفر المشروبات الكحولية؟","answer":"نعم، المشروبات الكحولية متاحة للشراء على متن المركب."}]},"fr":{"title":"Dîner-croisière sur le Nil","duration":"3 heures","description":"Glissez sur le Nil de nuit à bord d''un bateau joliment illuminé et regardez les lumières du Caire scintiller sur l''eau. Savourez un généreux buffet de plats égyptiens et internationaux, de la musique orientale live et des spectacles traditionnels de danse Tanoura et de danse orientale. Le Nil la nuit est l''un des grands spectacles du Caire.","highlights":["Bateau de croisière à deux ponts avec vue panoramique","Généreux buffet — mezzés égyptiens, grillades et desserts","Musique orientale live et spectacles traditionnels","Danse Tanoura et danse orientale","Le Caire, Zamalek et les ponts illuminés de nuit"],"itinerary":[{"time":"20:00","activity":"Prise en charge à l''hôtel et transfert à l''embarcadère"},{"time":"20:30","activity":"Embarquement — boissons de bienvenue"},{"time":"21:00","activity":"Départ de la croisière — début du dîner"},{"time":"21:30","activity":"Musique live et spectacles culturels"},{"time":"23:00","activity":"Retour au quai"},{"time":"23:30","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Billet de croisière","Dîner buffet","Boissons non alcoolisées et jus","Animations live"],"excluded":["Boissons alcoolisées","Pourboires"],"meetingPoint":"Prise en charge dans tous les hôtels du Caire.","whatToBring":["Tenue décontractée chic","Appareil photo"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant le départ.","faq":[{"question":"L''alcool est-il disponible ?","answer":"Oui, des boissons alcoolisées sont en vente à bord."}]},"de":{"title":"Dinner-Kreuzfahrt auf dem Nil","duration":"3 Stunden","description":"Gleiten Sie nachts auf einem stimmungsvoll beleuchteten Schiff über den Nil und sehen Sie Kairos Skyline auf dem Wasser glitzern. Genießen Sie ein reichhaltiges Buffet mit ägyptischen und internationalen Gerichten, orientalische Live-Musik sowie traditionelle Tanoura- und Bauchtanz-Shows. Der Nil bei Nacht ist eines der großen Spektakel Kairos.","highlights":["Zweistöckiges Nilschiff mit Panoramablick","Reichhaltiges Buffet — ägyptische Mezze, Gegrilltes und Desserts","Orientalische Live-Musik und traditionelle Darbietungen","Tanoura- und Bauchtanz-Show","Blick auf Kairo, Zamalek und die beleuchteten Brücken"],"itinerary":[{"time":"20:00","activity":"Abholung vom Hotel und Transfer zur Nil-Anlegestelle"},{"time":"20:30","activity":"Einschiffung — Begrüßungsgetränke"},{"time":"21:00","activity":"Abfahrt — das Dinner beginnt"},{"time":"21:30","activity":"Live-Musik und kulturelle Darbietungen"},{"time":"23:00","activity":"Rückkehr zur Anlegestelle"},{"time":"23:30","activity":"Rücktransfer zum Hotel"}],"included":["Hoteltransfers","Ticket für die Nilfahrt","Dinnerbuffet","Softdrinks und Säfte","Live-Unterhaltung"],"excluded":["Alkoholische Getränke","Trinkgelder"],"meetingPoint":"Abholung von Hotels in ganz Kairo.","whatToBring":["Elegante Freizeitkleidung","Kamera"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor Abfahrt.","faq":[{"question":"Gibt es Alkohol an Bord?","answer":"Ja, alkoholische Getränke können an Bord gekauft werden."}]}}'::jsonb, null, true, 4, 11, true, true, false, 3)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('cairo-5', 'cairo', 'Cultural & Historical', 880, 440, 7, array['English', 'Arabic', 'Italian']::text[], true, true, 'Pharaoh''s Path', array['https://images.unsplash.com/photo-1587975844610-40f1ad10d07e?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1539768942893-daf53e448371?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.8, 213, '[]'::jsonb, '{"en":{"title":"Saqqara, Memphis & Dahshur Private Tour","duration":"7 hours","description":"Venture beyond Giza to the older, quieter pyramid fields of Saqqara, Memphis, and Dahshur. See the world''s first pyramid — Djoser''s Step Pyramid — and descend into ancient tombs decorated with vivid murals. Visit the ancient capital of Memphis and the hauntingly beautiful Bent Pyramid at Dahshur. These sites see a fraction of Giza''s visitors — making this the connoisseur''s choice.","highlights":["Saqqara''s Step Pyramid — the world''s oldest monumental stone structure (2650 BC)","Decorated tombs of Mereruka, Kagemni, and Unas","Memphis — ancient capital with colossal statue of Ramesses II","Dahshur — the Bent Pyramid and Red Pyramid, rarely visited","Fully private tour with certified Egyptologist"],"itinerary":[{"time":"08:00","activity":"Hotel pickup from Cairo or Giza"},{"time":"09:00","activity":"Saqqara — Step Pyramid, tomb complexes"},{"time":"11:00","activity":"Memphis open-air museum"},{"time":"12:00","activity":"Lunch at local restaurant (included)"},{"time":"13:00","activity":"Dahshur — Bent Pyramid and Red Pyramid"},{"time":"15:00","activity":"Return to hotel"}],"included":["Hotel transfers","All entrance fees","Private Egyptologist guide","Lunch","Bottled water"],"excluded":["Personal shopping","Gratuities"],"meetingPoint":"Hotel lobby throughout Cairo and Giza.","whatToBring":["Comfortable shoes","Sun protection","Camera","Torch (for tomb interiors)"],"cancellationPolicy":"Free cancellation up to 24 hours before the tour.","faq":[{"question":"Are these pyramids less crowded than Giza?","answer":"Significantly less. Saqqara and Dahshur attract a fraction of Giza''s visitors. You''ll often have sites to yourself."}]},"ar":{"title":"جولة خاصة في سقارة وممفيس ودهشور","duration":"7 ساعات","description":"انطلق أبعد من الجيزة إلى مناطق الأهرامات الأقدم والأهدأ في سقارة وممفيس ودهشور. شاهد أول هرم في العالم — هرم زوسر المدرج — وانزل إلى مقابر قديمة مزينة بنقوش ملونة زاهية. زر العاصمة القديمة ممفيس والهرم المنحني الساحر في دهشور. هذه المواقع لا يزورها إلا جزء بسيط من زوار الجيزة، مما يجعلها اختيار الخبراء.","highlights":["هرم سقارة المدرج — أقدم بناء حجري ضخم في العالم (2650 ق.م)","مقابر مريروكا وكاجمني وأوناس المزينة","ممفيس — العاصمة القديمة وتمثال رمسيس الثاني الضخم","دهشور — الهرم المنحني والهرم الأحمر، قليلا الزوار","جولة خاصة بالكامل مع عالم مصريات معتمد"],"itinerary":[{"time":"08:00","activity":"الاستلام من الفندق في القاهرة أو الجيزة"},{"time":"09:00","activity":"سقارة — الهرم المدرج ومجمعات المقابر"},{"time":"11:00","activity":"متحف ممفيس المفتوح"},{"time":"12:00","activity":"الغداء في مطعم محلي (مشمول)"},{"time":"13:00","activity":"دهشور — الهرم المنحني والهرم الأحمر"},{"time":"15:00","activity":"العودة إلى الفندق"}],"included":["التنقلات من وإلى الفندق","جميع رسوم الدخول","مرشد خاص في علم المصريات","الغداء","مياه معبأة"],"excluded":["المشتريات الشخصية","الإكراميات"],"meetingPoint":"بهو الفندق في القاهرة والجيزة.","whatToBring":["حذاء مريح","حماية من الشمس","كاميرا","كشاف (لداخل المقابر)"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الجولة.","faq":[{"question":"هل هذه الأهرامات أقل ازدحامًا من الجيزة؟","answer":"أقل بكثير. سقارة ودهشور لا يزورهما إلا جزء صغير من زوار الجيزة، وكثيرًا ما تكون المواقع لك وحدك."}]},"fr":{"title":"Visite privée de Saqqarah, Memphis et Dahchour","duration":"7 heures","description":"Allez au-delà de Gizeh vers les nécropoles plus anciennes et plus paisibles de Saqqarah, Memphis et Dahchour. Découvrez la première pyramide du monde — la pyramide à degrés de Djéser — et descendez dans des tombeaux ornés de peintures éclatantes. Visitez l''ancienne capitale Memphis et la saisissante pyramide rhomboïdale de Dahchour. Ces sites reçoivent une fraction des visiteurs de Gizeh : le choix des connaisseurs.","highlights":["Pyramide à degrés de Saqqarah — le plus ancien grand monument en pierre (2650 av. J.-C.)","Tombeaux décorés de Mérérouka, Kagemni et Ounas","Memphis — ancienne capitale et colosse de Ramsès II","Dahchour — pyramides rhomboïdale et rouge, rarement visitées","Visite entièrement privée avec un égyptologue diplômé"],"itinerary":[{"time":"08:00","activity":"Prise en charge à l''hôtel au Caire ou à Gizeh"},{"time":"09:00","activity":"Saqqarah — pyramide à degrés et ensembles funéraires"},{"time":"11:00","activity":"Musée en plein air de Memphis"},{"time":"12:00","activity":"Déjeuner dans un restaurant local (inclus)"},{"time":"13:00","activity":"Dahchour — pyramide rhomboïdale et pyramide rouge"},{"time":"15:00","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Tous les droits d''entrée","Guide égyptologue privé","Déjeuner","Eau en bouteille"],"excluded":["Achats personnels","Pourboires"],"meetingPoint":"Hall de l''hôtel au Caire et à Gizeh.","whatToBring":["Chaussures confortables","Protection solaire","Appareil photo","Lampe de poche (pour l''intérieur des tombeaux)"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la visite.","faq":[{"question":"Ces pyramides sont-elles moins fréquentées que Gizeh ?","answer":"Beaucoup moins. Saqqarah et Dahchour n''attirent qu''une fraction des visiteurs de Gizeh, et vous aurez souvent les sites pour vous seuls."}]},"de":{"title":"Private Tour nach Sakkara, Memphis und Dahschur","duration":"7 Stunden","description":"Entdecken Sie jenseits von Gizeh die älteren, ruhigeren Pyramidenfelder von Sakkara, Memphis und Dahschur. Sehen Sie die erste Pyramide der Welt — die Stufenpyramide des Djoser — und steigen Sie in Gräber mit leuchtenden Wandmalereien hinab. Besuchen Sie die alte Hauptstadt Memphis und die eindrucksvolle Knickpyramide von Dahschur. Diese Stätten sehen nur einen Bruchteil der Besucher von Gizeh — die Wahl für Kenner.","highlights":["Stufenpyramide von Sakkara — das älteste monumentale Steinbauwerk der Welt (2650 v. Chr.)","Bemalte Gräber von Mereruka, Kagemni und Unas","Memphis — alte Hauptstadt mit der Kolossalstatue von Ramses II.","Dahschur — Knick- und Rote Pyramide, selten besucht","Komplett private Tour mit zertifiziertem Ägyptologen"],"itinerary":[{"time":"08:00","activity":"Abholung vom Hotel in Kairo oder Gizeh"},{"time":"09:00","activity":"Sakkara — Stufenpyramide und Grabanlagen"},{"time":"11:00","activity":"Freilichtmuseum Memphis"},{"time":"12:00","activity":"Mittagessen in einem lokalen Restaurant (inklusive)"},{"time":"13:00","activity":"Dahschur — Knickpyramide und Rote Pyramide"},{"time":"15:00","activity":"Rückfahrt zum Hotel"}],"included":["Hoteltransfers","Alle Eintrittsgelder","Privater Ägyptologe","Mittagessen","Wasser in Flaschen"],"excluded":["Persönliche Einkäufe","Trinkgelder"],"meetingPoint":"Hotellobby in Kairo und Gizeh.","whatToBring":["Bequeme Schuhe","Sonnenschutz","Kamera","Taschenlampe (für die Grabkammern)"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Tour.","faq":[{"question":"Sind diese Pyramiden weniger überlaufen als Gizeh?","answer":"Deutlich weniger. Sakkara und Dahschur ziehen nur einen Bruchteil der Besucher von Gizeh an — oft haben Sie die Stätten fast für sich allein."}]}}'::jsonb, null, true, 4, 11, true, true, false, 4)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('luxor-1', 'luxor', 'Cultural & Historical', 1650, 825, 5, array['English', 'Arabic', 'German', 'Italian']::text[], true, true, 'Thebes Heritage', array['https://images.unsplash.com/photo-1713021714419-ca3a7bc12f00?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844610-40f1ad10d07e?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.9, 567, '[]'::jsonb, '{"en":{"title":"Valley of the Kings Private Tour","duration":"5 hours","description":"Descend into the royal necropolis of Egypt''s greatest pharaohs. The Valley of the Kings holds 63 known tombs — your private Egyptologist will take you inside the finest, with detailed commentary on the vivid painted walls that have preserved stories of the afterlife for over 3,000 years. This is one of the most powerful encounters with the ancient world.","highlights":["Entry to three royal tombs including the tomb of Ramesses IV or VI","Optional entry to Tutankhamun''s tomb (additional fee)","Hatshepsut''s funerary temple at Deir el-Bahari","The Colossi of Memnon — twin statues standing since 1350 BC","Private certified Egyptologist guide"],"itinerary":[{"time":"06:30","activity":"Hotel pickup from Luxor — beat the heat and crowds"},{"time":"07:00","activity":"Colossi of Memnon — photo stop and explanation"},{"time":"07:30","activity":"Valley of the Kings — three royal tombs"},{"time":"10:00","activity":"Temple of Hatshepsut at Deir el-Bahari"},{"time":"12:00","activity":"Return to hotel"}],"included":["Hotel transfers","Valley of the Kings entry (3 tombs)","Deir el-Bahari temple entry","Private Egyptologist guide","Air-conditioned vehicle","Bottled water"],"excluded":["Tutankhamun''s tomb entry (optional)","Gratuities"],"meetingPoint":"Hotel lobby in Luxor East or West Bank.","whatToBring":["Comfortable shoes","Torch (useful in tombs)","Sun hat","Camera"],"cancellationPolicy":"Free cancellation up to 24 hours before the tour.","faq":[{"question":"Is photography allowed in the tombs?","answer":"Photography is permitted in most tombs. Tutankhamun''s tomb requires a separate photography permit. Flash is not allowed."}]},"ar":{"title":"جولة خاصة في وادي الملوك","duration":"5 ساعات","description":"انزل إلى المقبرة الملكية لأعظم فراعنة مصر. يضم وادي الملوك 63 مقبرة معروفة، وسيأخذك مرشدك الخاص في علم المصريات إلى أجملها، مع شرح تفصيلي للنقوش الملونة التي حفظت حكايات العالم الآخر لأكثر من 3000 عام. واحدة من أقوى لحظات اللقاء مع العالم القديم.","highlights":["دخول ثلاث مقابر ملكية منها مقبرة رمسيس الرابع أو السادس","إمكانية دخول مقبرة توت عنخ آمون (برسوم إضافية)","معبد حتشبسوت الجنائزي في الدير البحري","تمثالا ممنون — قائمان منذ عام 1350 ق.م","مرشد خاص معتمد في علم المصريات"],"itinerary":[{"time":"06:30","activity":"الاستلام من الفندق في الأقصر — قبل الحر والزحام"},{"time":"07:00","activity":"تمثالا ممنون — وقفة للتصوير والشرح"},{"time":"07:30","activity":"وادي الملوك — ثلاث مقابر ملكية"},{"time":"10:00","activity":"معبد حتشبسوت بالدير البحري"},{"time":"12:00","activity":"العودة إلى الفندق"}],"included":["التنقلات من وإلى الفندق","دخول وادي الملوك (3 مقابر)","دخول معبد الدير البحري","مرشد خاص في علم المصريات","سيارة مكيّفة","مياه معبأة"],"excluded":["دخول مقبرة توت عنخ آمون (اختياري)","الإكراميات"],"meetingPoint":"بهو الفندق في البر الشرقي أو الغربي بالأقصر.","whatToBring":["حذاء مريح","كشاف (مفيد داخل المقابر)","قبعة شمس","كاميرا"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الجولة.","faq":[{"question":"هل التصوير مسموح داخل المقابر؟","answer":"التصوير مسموح في معظم المقابر. مقبرة توت عنخ آمون تحتاج تصريح تصوير منفصل، والفلاش غير مسموح."}]},"fr":{"title":"Visite privée de la Vallée des Rois","duration":"5 heures","description":"Descendez dans la nécropole royale des plus grands pharaons d''Égypte. La Vallée des Rois compte 63 tombeaux connus ; votre égyptologue privé vous emmène dans les plus beaux, avec des explications détaillées sur les parois peintes qui racontent l''au-delà depuis plus de 3 000 ans. L''une des rencontres les plus fortes avec le monde antique.","highlights":["Entrée dans trois tombeaux royaux, dont celui de Ramsès IV ou VI","Entrée facultative dans le tombeau de Toutânkhamon (supplément)","Le temple funéraire d''Hatchepsout à Deir el-Bahari","Les colosses de Memnon — debout depuis 1350 av. J.-C.","Guide égyptologue diplômé privé"],"itinerary":[{"time":"06:30","activity":"Prise en charge à l''hôtel à Louxor — avant la chaleur et la foule"},{"time":"07:00","activity":"Colosses de Memnon — arrêt photo et explications"},{"time":"07:30","activity":"Vallée des Rois — trois tombeaux royaux"},{"time":"10:00","activity":"Temple d''Hatchepsout à Deir el-Bahari"},{"time":"12:00","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Entrée à la Vallée des Rois (3 tombeaux)","Entrée au temple de Deir el-Bahari","Guide égyptologue privé","Véhicule climatisé","Eau en bouteille"],"excluded":["Entrée au tombeau de Toutânkhamon (facultative)","Pourboires"],"meetingPoint":"Hall de l''hôtel sur la rive est ou ouest de Louxor.","whatToBring":["Chaussures confortables","Lampe de poche (utile dans les tombeaux)","Chapeau","Appareil photo"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la visite.","faq":[{"question":"Les photos sont-elles autorisées dans les tombeaux ?","answer":"La photographie est autorisée dans la plupart des tombeaux. Celui de Toutânkhamon nécessite un permis séparé. Le flash est interdit."}]},"de":{"title":"Private Tour ins Tal der Könige","duration":"5 Stunden","description":"Steigen Sie hinab in die königliche Nekropole der größten Pharaonen Ägyptens. Das Tal der Könige umfasst 63 bekannte Gräber — Ihr privater Ägyptologe führt Sie in die schönsten und erklärt ausführlich die farbenprächtigen Wandmalereien, die seit über 3.000 Jahren Geschichten vom Jenseits bewahren. Eine der eindrucksvollsten Begegnungen mit der Antike.","highlights":["Eintritt in drei Königsgräber, darunter das Grab von Ramses IV. oder VI.","Optionaler Besuch des Grabes von Tutanchamun (Aufpreis)","Der Totentempel der Hatschepsut in Deir el-Bahari","Die Memnonkolosse — Zwillingsstatuen seit 1350 v. Chr.","Privater, zertifizierter Ägyptologe"],"itinerary":[{"time":"06:30","activity":"Abholung vom Hotel in Luxor — vor Hitze und Andrang"},{"time":"07:00","activity":"Memnonkolosse — Fotostopp und Erklärung"},{"time":"07:30","activity":"Tal der Könige — drei Königsgräber"},{"time":"10:00","activity":"Tempel der Hatschepsut in Deir el-Bahari"},{"time":"12:00","activity":"Rückfahrt zum Hotel"}],"included":["Hoteltransfers","Eintritt Tal der Könige (3 Gräber)","Eintritt Tempel Deir el-Bahari","Privater Ägyptologe","Klimatisiertes Fahrzeug","Wasser in Flaschen"],"excluded":["Eintritt Grab des Tutanchamun (optional)","Trinkgelder"],"meetingPoint":"Hotellobby am Ost- oder Westufer von Luxor.","whatToBring":["Bequeme Schuhe","Taschenlampe (nützlich in den Gräbern)","Sonnenhut","Kamera"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Tour.","faq":[{"question":"Darf man in den Gräbern fotografieren?","answer":"In den meisten Gräbern ist Fotografieren erlaubt. Für das Grab des Tutanchamun ist eine separate Fotogenehmigung nötig. Blitz ist verboten."}]}}'::jsonb, null, true, 4, 11, true, true, false, 0)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('luxor-2', 'luxor', 'Nature & Wildlife', 3200, 1600, 1, array['English', 'Arabic']::text[], true, false, 'Sky Luxor Balloons', array['https://images.unsplash.com/photo-1777672351192-a7220589c25e?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1703902770170-7cc56c8c3067?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1737819605173-9ddc0178102a?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1713021714419-ca3a7bc12f00?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1684100096410-fd39cdff91a3?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.9, 1102, '[]'::jsonb, '{"en":{"title":"Hot Air Balloon over Luxor at Sunrise","duration":"1 hour flight","description":"Float silently above the world''s greatest concentration of ancient monuments as the sun rises over the Nile Valley. The temples, the tombs, the green strip of the Nile against the limestone desert — seen from above at dawn, Luxor is simply breathtaking. This one-hour flight is considered by many travelers to be the single best experience in all of Egypt.","highlights":["One-hour sunrise balloon flight over the West Bank of Luxor","Bird''s-eye views of the Valley of the Kings, Karnak, and the Nile","Expert pilot with thousands of flight hours","Champagne celebration on landing","Certificate of flight provided","Pre-dawn hotel pickup for optimum sunrise timing"],"itinerary":[{"time":"04:00","activity":"Hotel pickup from Luxor — while the city sleeps"},{"time":"04:45","activity":"Arrive at launch site — witness balloon inflation"},{"time":"05:30","activity":"Take off at first light"},{"time":"06:30","activity":"Landing followed by champagne celebration"},{"time":"07:30","activity":"Return transfer to hotel"}],"included":["Hotel pickup and drop-off","One-hour balloon flight","Champagne on landing","Flight certificate"],"excluded":["Travel insurance","Gratuities"],"meetingPoint":"Hotel lobby in Luxor. Pickup time confirmed the evening before.","whatToBring":["Warm layer (it is cool before sunrise)","Camera","Comfortable footwear"],"cancellationPolicy":"Full refund if the flight is cancelled due to weather conditions. No refund for guest cancellations within 48 hours.","faq":[{"question":"Is this safe?","answer":"Hot air ballooning in Luxor is regulated by the Egyptian Civil Aviation Authority. Our company meets the highest international safety standards and our pilots are fully certified."},{"question":"What is the minimum age?","answer":"Minimum age is 6 years. Children must be able to stand unassisted for the full duration of the flight."}]},"ar":{"title":"منطاد فوق الأقصر وقت الشروق","duration":"رحلة طيران ساعة واحدة","description":"حلّق في هدوء فوق أكبر تجمع للآثار القديمة في العالم بينما تشرق الشمس على وادي النيل. المعابد والمقابر وشريط النيل الأخضر وسط الصحراء الجيرية — الأقصر من أعلى وقت الفجر مشهد يخطف الأنفاس. يعتبر كثير من المسافرين رحلة الساعة هذه أجمل تجربة في مصر كلها.","highlights":["رحلة منطاد لمدة ساعة وقت الشروق فوق البر الغربي بالأقصر","إطلالة علوية على وادي الملوك والكرنك والنيل","طيار خبير بآلاف ساعات الطيران","احتفال بالشمبانيا بعد الهبوط","شهادة طيران تذكارية","استلام قبل الفجر من الفندق للحاق بأفضل توقيت للشروق"],"itinerary":[{"time":"04:00","activity":"الاستلام من الفندق في الأقصر — والمدينة نائمة"},{"time":"04:45","activity":"الوصول إلى موقع الإقلاع — مشاهدة نفخ المنطاد"},{"time":"05:30","activity":"الإقلاع مع أول ضوء"},{"time":"06:30","activity":"الهبوط ثم الاحتفال بالشمبانيا"},{"time":"07:30","activity":"العودة إلى الفندق"}],"included":["الاستلام والتوصيل من وإلى الفندق","رحلة منطاد لمدة ساعة","شمبانيا بعد الهبوط","شهادة طيران"],"excluded":["التأمين على السفر","الإكراميات"],"meetingPoint":"بهو الفندق في الأقصر. يتم تأكيد موعد الاستلام في الليلة السابقة.","whatToBring":["ملابس دافئة (الجو بارد قبل الشروق)","كاميرا","حذاء مريح"],"cancellationPolicy":"استرداد كامل إذا أُلغيت الرحلة بسبب الطقس. لا يُسترد المبلغ عند إلغاء الضيف خلال 48 ساعة.","faq":[{"question":"هل الرحلة آمنة؟","answer":"رحلات المنطاد في الأقصر تخضع لرقابة سلطة الطيران المدني المصري، وشركتنا تلتزم بأعلى معايير السلامة الدولية وطيارونا معتمدون بالكامل."},{"question":"ما الحد الأدنى للسن؟","answer":"الحد الأدنى 6 سنوات، ويجب أن يستطيع الطفل الوقوف بمفرده طوال مدة الرحلة."}]},"fr":{"title":"Montgolfière au lever du soleil sur Louxor","duration":"Vol d''1 heure","description":"Flottez en silence au-dessus de la plus grande concentration de monuments antiques au monde pendant que le soleil se lève sur la vallée du Nil. Temples, tombeaux, ruban vert du Nil contre le désert calcaire : vue d''en haut à l''aube, Louxor est tout simplement à couper le souffle. Beaucoup de voyageurs considèrent ce vol d''une heure comme la plus belle expérience d''Égypte.","highlights":["Vol d''une heure au lever du soleil au-dessus de la rive ouest","Vue aérienne sur la Vallée des Rois, Karnak et le Nil","Pilote expérimenté totalisant des milliers d''heures de vol","Champagne à l''atterrissage","Certificat de vol remis","Prise en charge avant l''aube pour un lever de soleil parfait"],"itinerary":[{"time":"04:00","activity":"Prise en charge à l''hôtel à Louxor — pendant que la ville dort"},{"time":"04:45","activity":"Arrivée au site de décollage — gonflage du ballon"},{"time":"05:30","activity":"Décollage aux premières lueurs"},{"time":"06:30","activity":"Atterrissage suivi du champagne"},{"time":"07:30","activity":"Retour à l''hôtel"}],"included":["Prise en charge et retour à l''hôtel","Vol en montgolfière d''une heure","Champagne à l''atterrissage","Certificat de vol"],"excluded":["Assurance voyage","Pourboires"],"meetingPoint":"Hall de l''hôtel à Louxor. L''heure de prise en charge est confirmée la veille.","whatToBring":["Une couche chaude (il fait frais avant l''aube)","Appareil photo","Chaussures confortables"],"cancellationPolicy":"Remboursement intégral si le vol est annulé pour cause météo. Aucun remboursement pour une annulation du client dans les 48 heures.","faq":[{"question":"Est-ce sûr ?","answer":"Les vols en montgolfière à Louxor sont contrôlés par l''Autorité égyptienne de l''aviation civile. Notre compagnie respecte les plus hautes normes internationales et nos pilotes sont entièrement certifiés."},{"question":"Quel est l''âge minimum ?","answer":"L''âge minimum est de 6 ans. Les enfants doivent pouvoir rester debout seuls pendant tout le vol."}]},"de":{"title":"Heißluftballon über Luxor bei Sonnenaufgang","duration":"1 Stunde Flug","description":"Schweben Sie lautlos über die größte Ansammlung antiker Monumente der Welt, während die Sonne über dem Niltal aufgeht. Tempel, Gräber, das grüne Band des Nils vor der Kalksteinwüste — Luxor ist von oben im Morgengrauen einfach atemberaubend. Viele Reisende halten diesen einstündigen Flug für das schönste Erlebnis in ganz Ägypten.","highlights":["Einstündige Ballonfahrt bei Sonnenaufgang über dem Westufer von Luxor","Vogelperspektive auf das Tal der Könige, Karnak und den Nil","Erfahrener Pilot mit Tausenden Flugstunden","Champagner nach der Landung","Fahrtzertifikat","Abholung vor Sonnenaufgang für das perfekte Timing"],"itinerary":[{"time":"04:00","activity":"Abholung vom Hotel in Luxor — während die Stadt schläft"},{"time":"04:45","activity":"Ankunft am Startplatz — Befüllen des Ballons"},{"time":"05:30","activity":"Start beim ersten Licht"},{"time":"06:30","activity":"Landung mit anschließender Champagnerfeier"},{"time":"07:30","activity":"Rücktransfer zum Hotel"}],"included":["Abholung und Rücktransfer vom Hotel","Einstündige Ballonfahrt","Champagner nach der Landung","Fahrtzertifikat"],"excluded":["Reiseversicherung","Trinkgelder"],"meetingPoint":"Hotellobby in Luxor. Die Abholzeit wird am Vorabend bestätigt.","whatToBring":["Warme Schicht (vor Sonnenaufgang ist es kühl)","Kamera","Bequemes Schuhwerk"],"cancellationPolicy":"Volle Erstattung, wenn die Fahrt wetterbedingt ausfällt. Keine Erstattung bei Stornierung durch den Gast innerhalb von 48 Stunden.","faq":[{"question":"Ist das sicher?","answer":"Ballonfahrten in Luxor werden von der ägyptischen Zivilluftfahrtbehörde überwacht. Unser Unternehmen erfüllt höchste internationale Sicherheitsstandards und unsere Piloten sind voll zertifiziert."},{"question":"Wie hoch ist das Mindestalter?","answer":"Das Mindestalter beträgt 6 Jahre. Kinder müssen während der gesamten Fahrt ohne Hilfe stehen können."}]}}'::jsonb, null, true, 4, 11, true, true, false, 1)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('luxor-3', 'luxor', 'Cultural & Historical', 850, 425, 2.5, array['English', 'Arabic', 'French']::text[], true, true, 'Thebes Heritage', array['https://images.unsplash.com/photo-1587975844610-40f1ad10d07e?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1713021714419-ca3a7bc12f00?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.8, 445, '[]'::jsonb, '{"en":{"title":"Karnak Temple at Sunset","duration":"2.5 hours","description":"The Karnak Temple complex is the largest religious structure ever built by mankind — and it is most magnificent at golden hour. Walk the avenue of ram-headed sphinxes, stand beneath 134 towering hypostyle columns, and watch the sandstone glow amber in the setting sun. Your Egyptologist guide decodes thousands of inscriptions and carvings as twilight transforms this ancient sacred precinct.","highlights":["Sunset timing for spectacular photography and cooler temperatures","The Great Hypostyle Hall — 134 massive columns, the largest ever constructed","Avenue of Sphinxes stretching to Luxor Temple","Sacred Lake and the granite Scarab of Amenhotep III","Private Egyptologist guide for in-depth insight"],"itinerary":[{"time":"15:30","activity":"Hotel pickup"},{"time":"16:00","activity":"Arrive at Karnak — entrance and orientation"},{"time":"16:15","activity":"Ram-headed sphinx avenue and First Pylon"},{"time":"16:45","activity":"Great Hypostyle Hall — detailed guided tour"},{"time":"17:30","activity":"Sacred Lake, Festival Hall, and Obelisks"},{"time":"18:15","activity":"Free time and photography at golden hour"},{"time":"18:45","activity":"Return to hotel"}],"included":["Hotel transfers","Karnak entry ticket","Private Egyptologist guide","Bottled water"],"excluded":["Gratuities"],"meetingPoint":"Hotel lobby in Luxor.","whatToBring":["Camera","Comfortable shoes","Light jacket for after sunset"],"cancellationPolicy":"Free cancellation up to 24 hours before the tour.","faq":[]},"ar":{"title":"معبد الكرنك وقت الغروب","duration":"2.5 ساعة","description":"مجمع معابد الكرنك هو أكبر بناء ديني شيّده الإنسان، وأروع ما يكون وقت الساعة الذهبية. امشِ في طريق الكباش، وقف تحت 134 عمودًا شاهقًا في بهو الأعمدة، وشاهد الحجر الرملي يتوهج بلون الكهرمان مع غروب الشمس. يشرح لك مرشدك آلاف النقوش والكتابات بينما يغيّر الشفق ملامح هذا المكان المقدس القديم.","highlights":["توقيت الغروب لتصوير مذهل ودرجات حرارة ألطف","بهو الأعمدة الكبير — 134 عمودًا ضخمًا، الأكبر في التاريخ","طريق الكباش الممتد حتى معبد الأقصر","البحيرة المقدسة وجعران أمنحتب الثالث الجرانيتي","مرشد خاص في علم المصريات لشرح متعمق"],"itinerary":[{"time":"15:30","activity":"الاستلام من الفندق"},{"time":"16:00","activity":"الوصول إلى الكرنك — الدخول والتعريف"},{"time":"16:15","activity":"طريق الكباش والصرح الأول"},{"time":"16:45","activity":"بهو الأعمدة الكبير — جولة مفصلة"},{"time":"17:30","activity":"البحيرة المقدسة وقاعة الاحتفالات والمسلات"},{"time":"18:15","activity":"وقت حر للتصوير في الساعة الذهبية"},{"time":"18:45","activity":"العودة إلى الفندق"}],"included":["التنقلات من وإلى الفندق","تذكرة دخول الكرنك","مرشد خاص في علم المصريات","مياه معبأة"],"excluded":["الإكراميات"],"meetingPoint":"بهو الفندق في الأقصر.","whatToBring":["كاميرا","حذاء مريح","جاكيت خفيف لما بعد الغروب"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الجولة.","faq":[]},"fr":{"title":"Le temple de Karnak au coucher du soleil","duration":"2,5 heures","description":"Le complexe de Karnak est le plus grand édifice religieux jamais construit par l''homme — et il est sublime à l''heure dorée. Parcourez l''allée des sphinx à tête de bélier, tenez-vous sous les 134 colonnes de la salle hypostyle et regardez le grès s''embraser au soleil couchant. Votre égyptologue déchiffre inscriptions et bas-reliefs tandis que le crépuscule transforme ce sanctuaire millénaire.","highlights":["Visite au coucher du soleil : photos spectaculaires et températures plus douces","La grande salle hypostyle — 134 colonnes géantes, les plus grandes jamais bâties","L''allée des sphinx menant au temple de Louxor","Le lac sacré et le scarabée de granit d''Amenhotep III","Guide égyptologue privé pour des explications approfondies"],"itinerary":[{"time":"15:30","activity":"Prise en charge à l''hôtel"},{"time":"16:00","activity":"Arrivée à Karnak — entrée et présentation"},{"time":"16:15","activity":"Allée des sphinx criocéphales et premier pylône"},{"time":"16:45","activity":"Grande salle hypostyle — visite détaillée"},{"time":"17:30","activity":"Lac sacré, salle des fêtes et obélisques"},{"time":"18:15","activity":"Temps libre et photos à l''heure dorée"},{"time":"18:45","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Billet d''entrée à Karnak","Guide égyptologue privé","Eau en bouteille"],"excluded":["Pourboires"],"meetingPoint":"Hall de l''hôtel à Louxor.","whatToBring":["Appareil photo","Chaussures confortables","Veste légère pour après le coucher du soleil"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la visite.","faq":[]},"de":{"title":"Karnak-Tempel bei Sonnenuntergang","duration":"2,5 Stunden","description":"Der Tempelkomplex von Karnak ist das größte religiöse Bauwerk, das je von Menschen errichtet wurde — und zur goldenen Stunde am prachtvollsten. Schreiten Sie die Allee der widderköpfigen Sphingen entlang, stehen Sie unter 134 gewaltigen Säulen des Säulensaals und sehen Sie den Sandstein im Abendlicht bernsteinfarben leuchten. Ihr Ägyptologe entschlüsselt Inschriften und Reliefs, während die Dämmerung diesen heiligen Ort verwandelt.","highlights":["Besuch bei Sonnenuntergang: spektakuläre Fotos und angenehmere Temperaturen","Der Große Säulensaal — 134 gewaltige Säulen, die größten je gebauten","Die Sphingenallee bis zum Luxor-Tempel","Der Heilige See und der Granitskarabäus Amenophis'' III.","Privater Ägyptologe für tiefe Einblicke"],"itinerary":[{"time":"15:30","activity":"Abholung vom Hotel"},{"time":"16:00","activity":"Ankunft in Karnak — Eintritt und Einführung"},{"time":"16:15","activity":"Widdersphingen-Allee und Erster Pylon"},{"time":"16:45","activity":"Großer Säulensaal — ausführliche Führung"},{"time":"17:30","activity":"Heiliger See, Festtempel und Obelisken"},{"time":"18:15","activity":"Freie Zeit und Fotos zur goldenen Stunde"},{"time":"18:45","activity":"Rückfahrt zum Hotel"}],"included":["Hoteltransfers","Eintritt Karnak","Privater Ägyptologe","Wasser in Flaschen"],"excluded":["Trinkgelder"],"meetingPoint":"Hotellobby in Luxor.","whatToBring":["Kamera","Bequeme Schuhe","Leichte Jacke für nach Sonnenuntergang"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Tour.","faq":[]}}'::jsonb, null, true, 4, 11, true, true, false, 2)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('luxor-4', 'luxor', 'Cultural & Historical', 700, 350, 2, array['English', 'Arabic']::text[], true, true, 'Thebes Heritage', array['https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844610-40f1ad10d07e?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1539768942893-daf53e448371?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.7, 298, '[]'::jsonb, '{"en":{"title":"Luxor Temple by Night","duration":"2 hours","description":"Luxor Temple is among the most beautifully illuminated ancient monuments in the world. After dark, the sandstone glows a warm gold against the night sky — dramatically different from the daytime experience. Walk the colonnaded hall of Amenhotep III, stand before the Abu el-Haggag Mosque built atop the ancient temple, and feel the layers of 3,000 years of continuous human presence at this extraordinary site.","highlights":["Luxor Temple fully illuminated after dark — stunning light and shadow","Colossal statues of Ramesses II at the entrance pylon","The magnificent colonnade of Amenhotep III","Abu el-Haggag Mosque — built inside the ancient temple","The Luxor corniche promenade by night"],"itinerary":[{"time":"19:30","activity":"Hotel pickup"},{"time":"20:00","activity":"Luxor Temple — entrance pylon and statues"},{"time":"20:30","activity":"Colonnaded hall and inner sanctuaries"},{"time":"21:15","activity":"Photography and free exploration"},{"time":"21:45","activity":"Evening walk along the Luxor corniche"},{"time":"22:15","activity":"Return to hotel"}],"included":["Hotel transfers","Luxor Temple entry ticket","Private guide","Bottled water"],"excluded":["Gratuities"],"meetingPoint":"Hotel lobby in Luxor.","whatToBring":["Camera (tripod recommended for night shots)","Light jacket"],"cancellationPolicy":"Free cancellation up to 24 hours before the tour.","faq":[]},"ar":{"title":"معبد الأقصر ليلًا","duration":"ساعتان","description":"معبد الأقصر من أجمل الآثار القديمة إضاءةً في العالم. بعد حلول الظلام يتوهج الحجر الرملي بلون ذهبي دافئ على خلفية السماء الليلية — تجربة مختلفة تمامًا عن النهار. امشِ في رواق أعمدة أمنحتب الثالث، وقف أمام مسجد أبو الحجاج المبني فوق المعبد القديم، واشعر بطبقات 3000 عام من الوجود الإنساني المتواصل في هذا المكان الاستثنائي.","highlights":["معبد الأقصر مضاءً بالكامل ليلًا — ضوء وظلال مذهلة","تماثيل رمسيس الثاني الضخمة عند الصرح","رواق أعمدة أمنحتب الثالث الرائع","مسجد أبو الحجاج — مبني داخل المعبد القديم","كورنيش الأقصر ليلًا"],"itinerary":[{"time":"19:30","activity":"الاستلام من الفندق"},{"time":"20:00","activity":"معبد الأقصر — الصرح والتماثيل"},{"time":"20:30","activity":"بهو الأعمدة والمقاصير الداخلية"},{"time":"21:15","activity":"تصوير واستكشاف حر"},{"time":"21:45","activity":"تمشية مسائية على كورنيش الأقصر"},{"time":"22:15","activity":"العودة إلى الفندق"}],"included":["التنقلات من وإلى الفندق","تذكرة دخول معبد الأقصر","مرشد خاص","مياه معبأة"],"excluded":["الإكراميات"],"meetingPoint":"بهو الفندق في الأقصر.","whatToBring":["كاميرا (يُنصح بحامل ثلاثي للتصوير الليلي)","جاكيت خفيف"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الجولة.","faq":[]},"fr":{"title":"Le temple de Louxor de nuit","duration":"2 heures","description":"Le temple de Louxor est l''un des monuments antiques les mieux éclairés au monde. À la nuit tombée, le grès prend une teinte dorée chaleureuse contre le ciel nocturne — une expérience très différente de la visite de jour. Parcourez la colonnade d''Amenhotep III, admirez la mosquée Abou el-Haggag bâtie sur le temple antique et ressentez 3 000 ans de présence humaine continue sur ce site extraordinaire.","highlights":["Le temple de Louxor entièrement illuminé — jeux d''ombre et de lumière","Colosses de Ramsès II devant le pylône d''entrée","La magnifique colonnade d''Amenhotep III","La mosquée Abou el-Haggag — construite dans le temple antique","La corniche de Louxor de nuit"],"itinerary":[{"time":"19:30","activity":"Prise en charge à l''hôtel"},{"time":"20:00","activity":"Temple de Louxor — pylône d''entrée et statues"},{"time":"20:30","activity":"Salle à colonnes et sanctuaires intérieurs"},{"time":"21:15","activity":"Photos et exploration libre"},{"time":"21:45","activity":"Promenade du soir sur la corniche de Louxor"},{"time":"22:15","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Billet d''entrée au temple de Louxor","Guide privé","Eau en bouteille"],"excluded":["Pourboires"],"meetingPoint":"Hall de l''hôtel à Louxor.","whatToBring":["Appareil photo (trépied conseillé pour les photos de nuit)","Veste légère"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la visite.","faq":[]},"de":{"title":"Luxor-Tempel bei Nacht","duration":"2 Stunden","description":"Der Luxor-Tempel gehört zu den am schönsten beleuchteten antiken Monumenten der Welt. Nach Einbruch der Dunkelheit leuchtet der Sandstein warm golden vor dem Nachthimmel — ganz anders als am Tag. Gehen Sie durch die Kolonnade Amenophis'' III., stehen Sie vor der Abu-el-Haggag-Moschee, die auf dem antiken Tempel errichtet wurde, und spüren Sie 3.000 Jahre ununterbrochene menschliche Präsenz an diesem außergewöhnlichen Ort.","highlights":["Der Luxor-Tempel nachts voll beleuchtet — faszinierendes Licht- und Schattenspiel","Kolossalstatuen Ramses'' II. am Eingangspylon","Die prachtvolle Kolonnade Amenophis'' III.","Die Abu-el-Haggag-Moschee — im antiken Tempel erbaut","Die Corniche von Luxor bei Nacht"],"itinerary":[{"time":"19:30","activity":"Abholung vom Hotel"},{"time":"20:00","activity":"Luxor-Tempel — Eingangspylon und Statuen"},{"time":"20:30","activity":"Säulenhalle und innere Heiligtümer"},{"time":"21:15","activity":"Fotos und freie Erkundung"},{"time":"21:45","activity":"Abendspaziergang an der Corniche von Luxor"},{"time":"22:15","activity":"Rückfahrt zum Hotel"}],"included":["Hoteltransfers","Eintritt Luxor-Tempel","Privater Guide","Wasser in Flaschen"],"excluded":["Trinkgelder"],"meetingPoint":"Hotellobby in Luxor.","whatToBring":["Kamera (Stativ für Nachtaufnahmen empfohlen)","Leichte Jacke"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Tour.","faq":[]}}'::jsonb, null, true, 4, 11, true, true, false, 3)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('luxor-5', 'luxor', 'Cultural & Historical', 1100, 550, 9, array['English', 'Arabic']::text[], true, true, 'Thebes Heritage', array['https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844610-40f1ad10d07e?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1713021714419-ca3a7bc12f00?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.9, 176, '[]'::jsonb, '{"en":{"title":"Dendera & Abydos Temples Day Trip","duration":"9 hours","description":"Journey beyond Luxor to two of Egypt''s most spectacular and least visited temples. Dendera features the only complete zodiac ceiling in the ancient world. Abydos holds the finest painted reliefs anywhere in Egypt — colours so vivid they appear freshly applied. These sites receive a small fraction of Karnak''s visitors, making this a genuinely special, unhurried encounter with ancient Egypt.","highlights":["Dendera Temple of Hathor — the most complete Roman-era temple in Egypt","The famous Dendera Zodiac ceiling and crypts","Abydos Temple of Seti I — finest painted reliefs in Egypt","The Osireion — a mysterious underground cenotaph","Private certified Egyptologist guide throughout"],"itinerary":[{"time":"07:00","activity":"Hotel pickup"},{"time":"09:00","activity":"Dendera Temple complex"},{"time":"11:30","activity":"Drive to Abydos"},{"time":"13:00","activity":"Lunch at local restaurant (included)"},{"time":"14:00","activity":"Abydos Temple of Seti I and Osireion"},{"time":"17:00","activity":"Return to Luxor hotel"}],"included":["Hotel transfers","All entry fees","Private Egyptologist guide","Lunch","Bottled water"],"excluded":["Personal shopping","Gratuities"],"meetingPoint":"Hotel lobby in Luxor.","whatToBring":["Comfortable shoes","Torch (useful in crypts)","Camera"],"cancellationPolicy":"Free cancellation up to 24 hours before the tour.","faq":[]},"ar":{"title":"رحلة يوم إلى معبدي دندرة وأبيدوس","duration":"9 ساعات","description":"انطلق أبعد من الأقصر إلى اثنين من أروع معابد مصر وأقلها زيارة. يضم معبد دندرة سقف الأبراج الكامل الوحيد في العالم القديم، ويحتوي معبد أبيدوس على أجمل النقوش الملونة في مصر بألوان زاهية كأنها رُسمت بالأمس. لا يزور هذه المواقع إلا جزء صغير من زوار الكرنك، مما يجعلها لقاءً هادئًا ومميزًا بمصر القديمة.","highlights":["معبد حتحور بدندرة — أكمل معبد من العصر الروماني في مصر","سقف الأبراج الشهير والسراديب في دندرة","معبد سيتي الأول بأبيدوس — أجمل النقوش الملونة في مصر","الأوزيريون — نصب تذكاري غامض تحت الأرض","مرشد خاص معتمد في علم المصريات طوال اليوم"],"itinerary":[{"time":"07:00","activity":"الاستلام من الفندق"},{"time":"09:00","activity":"مجمع معبد دندرة"},{"time":"11:30","activity":"الانتقال إلى أبيدوس"},{"time":"13:00","activity":"الغداء في مطعم محلي (مشمول)"},{"time":"14:00","activity":"معبد سيتي الأول والأوزيريون بأبيدوس"},{"time":"17:00","activity":"العودة إلى الفندق في الأقصر"}],"included":["التنقلات من وإلى الفندق","جميع رسوم الدخول","مرشد خاص في علم المصريات","الغداء","مياه معبأة"],"excluded":["المشتريات الشخصية","الإكراميات"],"meetingPoint":"بهو الفندق في الأقصر.","whatToBring":["حذاء مريح","كشاف (مفيد في السراديب)","كاميرا"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الجولة.","faq":[]},"fr":{"title":"Excursion d''une journée à Dendérah et Abydos","duration":"9 heures","description":"Partez au-delà de Louxor vers deux des temples les plus spectaculaires et les moins visités d''Égypte. Dendérah possède le seul plafond zodiacal complet du monde antique. Abydos abrite les plus beaux reliefs peints d''Égypte, aux couleurs si vives qu''elles semblent fraîchement appliquées. Ces sites reçoivent une petite fraction des visiteurs de Karnak : une rencontre rare et sereine avec l''Égypte antique.","highlights":["Temple d''Hathor à Dendérah — le temple d''époque romaine le plus complet d''Égypte","Le célèbre zodiaque de Dendérah et les cryptes","Temple de Séthi Ier à Abydos — les plus beaux reliefs peints d''Égypte","L''Osiréion — un mystérieux cénotaphe souterrain","Guide égyptologue diplômé privé toute la journée"],"itinerary":[{"time":"07:00","activity":"Prise en charge à l''hôtel"},{"time":"09:00","activity":"Complexe du temple de Dendérah"},{"time":"11:30","activity":"Route vers Abydos"},{"time":"13:00","activity":"Déjeuner dans un restaurant local (inclus)"},{"time":"14:00","activity":"Temple de Séthi Ier et Osiréion à Abydos"},{"time":"17:00","activity":"Retour à l''hôtel à Louxor"}],"included":["Transferts depuis l''hôtel","Tous les droits d''entrée","Guide égyptologue privé","Déjeuner","Eau en bouteille"],"excluded":["Achats personnels","Pourboires"],"meetingPoint":"Hall de l''hôtel à Louxor.","whatToBring":["Chaussures confortables","Lampe de poche (utile dans les cryptes)","Appareil photo"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la visite.","faq":[]},"de":{"title":"Tagesausflug zu den Tempeln von Dendera und Abydos","duration":"9 Stunden","description":"Reisen Sie über Luxor hinaus zu zwei der spektakulärsten und am wenigsten besuchten Tempel Ägyptens. Dendera besitzt die einzige vollständige Tierkreisdecke der Antike. Abydos birgt die schönsten bemalten Reliefs Ägyptens — in so leuchtenden Farben, als wären sie gerade erst aufgetragen worden. Diese Stätten sehen nur einen kleinen Bruchteil der Besucher von Karnak: eine wirklich besondere, ruhige Begegnung mit dem alten Ägypten.","highlights":["Hathor-Tempel von Dendera — der vollständigste Tempel der Römerzeit in Ägypten","Der berühmte Tierkreis von Dendera und die Krypten","Tempel Sethos'' I. in Abydos — die schönsten bemalten Reliefs Ägyptens","Das Osireion — ein geheimnisvolles unterirdisches Kenotaph","Privater, zertifizierter Ägyptologe den ganzen Tag"],"itinerary":[{"time":"07:00","activity":"Abholung vom Hotel"},{"time":"09:00","activity":"Tempelanlage von Dendera"},{"time":"11:30","activity":"Fahrt nach Abydos"},{"time":"13:00","activity":"Mittagessen in einem lokalen Restaurant (inklusive)"},{"time":"14:00","activity":"Tempel Sethos'' I. und Osireion in Abydos"},{"time":"17:00","activity":"Rückfahrt zum Hotel in Luxor"}],"included":["Hoteltransfers","Alle Eintrittsgelder","Privater Ägyptologe","Mittagessen","Wasser in Flaschen"],"excluded":["Persönliche Einkäufe","Trinkgelder"],"meetingPoint":"Hotellobby in Luxor.","whatToBring":["Bequeme Schuhe","Taschenlampe (nützlich in den Krypten)","Kamera"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Tour.","faq":[]}}'::jsonb, null, true, 4, 11, true, true, false, 4)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('aswan-1', 'aswan', 'Cultural & Historical', 950, 475, 3, array['English', 'Arabic', 'German']::text[], true, true, 'Aswan Nile Tours', array['https://images.unsplash.com/photo-1684100096410-fd39cdff91a3?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1707266327255-1f0199f22b33?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1648139209977-61e0e6ed68b9?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.8, 312, '[]'::jsonb, '{"en":{"title":"Philae Temple Motorboat Tour","duration":"3 hours","description":"Boat across Nasser Lake to the island temple of Philae — the jewel of Egyptian temples dedicated to the goddess Isis. Rescued stone by stone from rising floodwaters in one of history''s greatest archaeological rescue operations, Philae sits on its own island and is accessible only by boat. At sunset, the pink granite glows against the deep blue Nile in one of Egypt''s most romantic settings.","highlights":["Motorboat transfer across Lake Nasser to Philae Island","Temple of Isis — the last active pagan temple in the Roman world","Kiosk of Trajan — Egypt''s most photographed ancient structure","Sound and Light Show option in the evening","Private Egyptologist guide"],"itinerary":[{"time":"15:00","activity":"Hotel pickup from Aswan"},{"time":"15:30","activity":"Arrive at Shellal dock — board motorboat"},{"time":"16:00","activity":"Philae Island — Temple of Isis guided tour"},{"time":"17:30","activity":"Kiosk of Trajan and photography"},{"time":"18:00","activity":"Return motorboat to dock"},{"time":"18:30","activity":"Return to hotel"}],"included":["Hotel transfers","Motorboat transfer","Philae entry ticket","Private guide","Bottled water"],"excluded":["Sound & Light Show (optional evening event)","Gratuities"],"meetingPoint":"Hotel lobby in Aswan.","whatToBring":["Camera","Comfortable shoes","Sun protection"],"cancellationPolicy":"Free cancellation up to 24 hours before the tour.","faq":[]},"ar":{"title":"جولة بالقارب إلى معبد فيلة","duration":"3 ساعات","description":"اعبر بالقارب إلى معبد فيلة على جزيرته — جوهرة المعابد المصرية المكرّس للإلهة إيزيس. أُنقذ المعبد حجرًا حجرًا من مياه الفيضان في واحدة من أعظم عمليات الإنقاذ الأثري في التاريخ، ويقع على جزيرة لا يمكن الوصول إليها إلا بالقارب. وقت الغروب يتوهج الجرانيت الوردي أمام زرقة النيل في واحد من أكثر الأماكن رومانسية في مصر.","highlights":["قارب بمحرك إلى جزيرة فيلة","معبد إيزيس — آخر معبد وثني ظل يعمل في العالم الروماني","كشك تراجان — من أكثر الآثار المصرية تصويرًا","إمكانية حضور عرض الصوت والضوء مساءً","مرشد خاص في علم المصريات"],"itinerary":[{"time":"15:00","activity":"الاستلام من الفندق في أسوان"},{"time":"15:30","activity":"الوصول إلى مرسى الشلال — ركوب القارب"},{"time":"16:00","activity":"جزيرة فيلة — جولة في معبد إيزيس"},{"time":"17:30","activity":"كشك تراجان والتصوير"},{"time":"18:00","activity":"العودة بالقارب إلى المرسى"},{"time":"18:30","activity":"العودة إلى الفندق"}],"included":["التنقلات من وإلى الفندق","القارب ذهابًا وعودة","تذكرة دخول فيلة","مرشد خاص","مياه معبأة"],"excluded":["عرض الصوت والضوء (فعالية مسائية اختيارية)","الإكراميات"],"meetingPoint":"بهو الفندق في أسوان.","whatToBring":["كاميرا","حذاء مريح","حماية من الشمس"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الجولة.","faq":[]},"fr":{"title":"Visite du temple de Philae en bateau","duration":"3 heures","description":"Rejoignez en bateau le temple insulaire de Philae, joyau des temples égyptiens dédié à la déesse Isis. Sauvé pierre par pierre de la montée des eaux lors de l''une des plus grandes opérations de sauvetage archéologique de l''histoire, Philae se dresse sur son île, accessible uniquement par bateau. Au coucher du soleil, le granit rose rayonne face au bleu profond du Nil : l''un des lieux les plus romantiques d''Égypte.","highlights":["Traversée en bateau à moteur jusqu''à l''île de Philae","Temple d''Isis — le dernier temple païen actif du monde romain","Kiosque de Trajan — l''un des monuments les plus photographiés d''Égypte","Spectacle son et lumière possible en soirée","Guide égyptologue privé"],"itinerary":[{"time":"15:00","activity":"Prise en charge à l''hôtel à Assouan"},{"time":"15:30","activity":"Arrivée au quai de Shellal — embarquement"},{"time":"16:00","activity":"Île de Philae — visite guidée du temple d''Isis"},{"time":"17:30","activity":"Kiosque de Trajan et photos"},{"time":"18:00","activity":"Retour en bateau au quai"},{"time":"18:30","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Traversée en bateau à moteur","Billet d''entrée à Philae","Guide privé","Eau en bouteille"],"excluded":["Spectacle son et lumière (soirée facultative)","Pourboires"],"meetingPoint":"Hall de l''hôtel à Assouan.","whatToBring":["Appareil photo","Chaussures confortables","Protection solaire"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la visite.","faq":[]},"de":{"title":"Motorboot-Tour zum Philae-Tempel","duration":"3 Stunden","description":"Fahren Sie mit dem Boot zum Inseltempel von Philae — dem Juwel unter den ägyptischen Tempeln, der Göttin Isis geweiht. Bei einer der größten archäologischen Rettungsaktionen der Geschichte Stein für Stein vor den Fluten gerettet, liegt Philae auf einer eigenen Insel und ist nur per Boot erreichbar. Bei Sonnenuntergang leuchtet der rosa Granit vor dem tiefblauen Nil — einer der romantischsten Orte Ägyptens.","highlights":["Motorbootfahrt zur Insel Philae","Isis-Tempel — der letzte aktive heidnische Tempel der römischen Welt","Trajan-Kiosk — eines der meistfotografierten Bauwerke Ägyptens","Abends optional Licht- und Tonshow","Privater Ägyptologe"],"itinerary":[{"time":"15:00","activity":"Abholung vom Hotel in Assuan"},{"time":"15:30","activity":"Ankunft am Anleger Shellal — Einstieg ins Motorboot"},{"time":"16:00","activity":"Insel Philae — Führung durch den Isis-Tempel"},{"time":"17:30","activity":"Trajan-Kiosk und Fotos"},{"time":"18:00","activity":"Rückfahrt mit dem Boot zum Anleger"},{"time":"18:30","activity":"Rücktransfer zum Hotel"}],"included":["Hoteltransfers","Motorbootfahrt","Eintritt Philae","Privater Guide","Wasser in Flaschen"],"excluded":["Licht- und Tonshow (optionale Abendveranstaltung)","Trinkgelder"],"meetingPoint":"Hotellobby in Assuan.","whatToBring":["Kamera","Bequeme Schuhe","Sonnenschutz"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Tour.","faq":[]}}'::jsonb, null, true, 4, 11, true, true, false, 0)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('aswan-2', 'aswan', 'Cultural & Historical', 2800, 1400, 10.5, array['English', 'Arabic', 'German']::text[], true, true, 'Aswan Nile Tours', array['https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1539768942893-daf53e448371?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1553913861-c0fddf2619ee?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844610-40f1ad10d07e?w=800&h=560&fit=crop&auto=format&q=80']::text[], 5, 489, '[]'::jsonb, '{"en":{"title":"Abu Simbel Temples Day Trip","duration":"Full day (10–11 hrs)","description":"The great temples of Abu Simbel are among the most awe-inspiring monuments on earth. Carved directly into the mountainside by Ramesses II over 3,200 years ago and relocated — intact — to save them from the rising waters of Lake Nasser, they represent both ancient genius and modern engineering marvel. An early morning convoy from Aswan arrives as the temples are bathed in golden desert light.","highlights":["The Great Temple of Ramesses II — four colossal statues, 20 metres tall","The smaller Temple of Hathor, dedicated to Nefertari","Incredible painted interior reliefs and hypostyle hall","Sunrise arrival for the best light and thinnest crowds","Private Egyptologist guide"],"itinerary":[{"time":"03:30","activity":"Hotel pickup for the pre-dawn convoy"},{"time":"07:00","activity":"Arrive at Abu Simbel as the temples catch the morning sun"},{"time":"07:15","activity":"Great Temple of Ramesses II — guided tour"},{"time":"09:00","activity":"Temple of Hathor (Nefertari) — guided tour"},{"time":"10:00","activity":"Free photography time and independent exploration"},{"time":"10:30","activity":"Depart for Aswan"},{"time":"14:00","activity":"Return to hotel"}],"included":["Hotel pickup and drop-off","Air-conditioned convoy vehicle","Abu Simbel entry tickets","Private Egyptologist guide","Breakfast en route","Bottled water"],"excluded":["Gratuities","Personal shopping"],"meetingPoint":"Hotel lobby in Aswan.","whatToBring":["Camera","Comfortable shoes","Warm layer (departure is pre-dawn)","Sunscreen"],"cancellationPolicy":"Free cancellation up to 48 hours before the tour.","faq":[{"question":"Why is the pickup so early?","answer":"Abu Simbel is 280 km from Aswan and vehicles travel in a convoy for safety. Arriving at sunrise offers the best light and the fewest crowds."}]},"ar":{"title":"رحلة يوم إلى معابد أبو سمبل","duration":"يوم كامل (10–11 ساعة)","description":"معابد أبو سمبل العظيمة من أكثر الآثار إبهارًا على وجه الأرض. نحتها رمسيس الثاني في قلب الجبل منذ أكثر من 3200 عام، ثم نُقلت كما هي لإنقاذها من مياه بحيرة ناصر، فهي شاهد على عبقرية القدماء ومعجزة الهندسة الحديثة معًا. تنطلق القافلة من أسوان فجرًا وتصل والمعابد تغمرها أشعة الصحراء الذهبية.","highlights":["معبد رمسيس الثاني الكبير — أربعة تماثيل ضخمة بارتفاع 20 مترًا","معبد حتحور الصغير المكرّس للملكة نفرتاري","نقوش داخلية ملونة رائعة وبهو أعمدة","الوصول وقت الشروق لأفضل إضاءة وأقل زحام","مرشد خاص في علم المصريات"],"itinerary":[{"time":"03:30","activity":"الاستلام من الفندق للحاق بقافلة الفجر"},{"time":"07:00","activity":"الوصول إلى أبو سمبل مع شمس الصباح على المعابد"},{"time":"07:15","activity":"معبد رمسيس الثاني الكبير — جولة مع المرشد"},{"time":"09:00","activity":"معبد حتحور (نفرتاري) — جولة مع المرشد"},{"time":"10:00","activity":"وقت حر للتصوير والاستكشاف"},{"time":"10:30","activity":"التحرك إلى أسوان"},{"time":"14:00","activity":"العودة إلى الفندق"}],"included":["الاستلام والتوصيل من وإلى الفندق","سيارة مكيّفة ضمن القافلة","تذاكر دخول أبو سمبل","مرشد خاص في علم المصريات","إفطار في الطريق","مياه معبأة"],"excluded":["الإكراميات","المشتريات الشخصية"],"meetingPoint":"بهو الفندق في أسوان.","whatToBring":["كاميرا","حذاء مريح","ملابس دافئة (التحرك قبل الفجر)","واقي شمس"],"cancellationPolicy":"إلغاء مجاني حتى 48 ساعة قبل الجولة.","faq":[{"question":"لماذا الاستلام مبكر جدًا؟","answer":"أبو سمبل تبعد 280 كم عن أسوان والسيارات تتحرك في قافلة لدواعي الأمان. الوصول وقت الشروق يضمن أفضل إضاءة وأقل زحام."}]},"fr":{"title":"Excursion d''une journée aux temples d''Abou Simbel","duration":"Journée complète (10–11 h)","description":"Les grands temples d''Abou Simbel comptent parmi les monuments les plus impressionnants de la planète. Taillés à même la montagne par Ramsès II il y a plus de 3 200 ans, puis déplacés intacts pour échapper aux eaux du lac Nasser, ils témoignent à la fois du génie antique et de la prouesse moderne. Le convoi part d''Assouan au petit matin et arrive quand les temples baignent dans la lumière dorée du désert.","highlights":["Le grand temple de Ramsès II — quatre colosses de 20 mètres","Le petit temple d''Hathor, dédié à Néfertari","Superbes reliefs peints et salle hypostyle","Arrivée au lever du soleil : meilleure lumière et moins de monde","Guide égyptologue privé"],"itinerary":[{"time":"03:30","activity":"Prise en charge à l''hôtel pour le convoi de l''aube"},{"time":"07:00","activity":"Arrivée à Abou Simbel sous le soleil du matin"},{"time":"07:15","activity":"Grand temple de Ramsès II — visite guidée"},{"time":"09:00","activity":"Temple d''Hathor (Néfertari) — visite guidée"},{"time":"10:00","activity":"Temps libre pour les photos et l''exploration"},{"time":"10:30","activity":"Départ vers Assouan"},{"time":"14:00","activity":"Retour à l''hôtel"}],"included":["Prise en charge et retour à l''hôtel","Véhicule climatisé en convoi","Billets d''entrée à Abou Simbel","Guide égyptologue privé","Petit-déjeuner en route","Eau en bouteille"],"excluded":["Pourboires","Achats personnels"],"meetingPoint":"Hall de l''hôtel à Assouan.","whatToBring":["Appareil photo","Chaussures confortables","Une couche chaude (départ avant l''aube)","Crème solaire"],"cancellationPolicy":"Annulation gratuite jusqu''à 48 heures avant la visite.","faq":[{"question":"Pourquoi un départ si matinal ?","answer":"Abou Simbel est à 280 km d''Assouan et les véhicules circulent en convoi pour des raisons de sécurité. Arriver au lever du soleil offre la meilleure lumière et le moins de monde."}]},"de":{"title":"Tagesausflug zu den Tempeln von Abu Simbel","duration":"Ganzer Tag (10–11 Std.)","description":"Die großen Tempel von Abu Simbel gehören zu den beeindruckendsten Monumenten der Erde. Vor über 3.200 Jahren von Ramses II. direkt in den Berg gehauen und später vollständig versetzt, um sie vor dem Wasser des Nassersees zu retten, stehen sie für antikes Genie und moderne Ingenieurskunst zugleich. Der Konvoi startet frühmorgens in Assuan und erreicht die Tempel, wenn sie im goldenen Wüstenlicht erstrahlen.","highlights":["Der Große Tempel Ramses'' II. — vier Kolossalstatuen, 20 Meter hoch","Der kleinere Hathor-Tempel, Nefertari geweiht","Prachtvoll bemalte Innenreliefs und Säulenhalle","Ankunft bei Sonnenaufgang: bestes Licht, wenig Andrang","Privater Ägyptologe"],"itinerary":[{"time":"03:30","activity":"Abholung vom Hotel für den Konvoi vor Sonnenaufgang"},{"time":"07:00","activity":"Ankunft in Abu Simbel in der Morgensonne"},{"time":"07:15","activity":"Großer Tempel Ramses'' II. — Führung"},{"time":"09:00","activity":"Hathor-Tempel (Nefertari) — Führung"},{"time":"10:00","activity":"Freie Zeit für Fotos und eigene Erkundung"},{"time":"10:30","activity":"Abfahrt nach Assuan"},{"time":"14:00","activity":"Rückkehr zum Hotel"}],"included":["Abholung und Rücktransfer vom Hotel","Klimatisiertes Fahrzeug im Konvoi","Eintritt Abu Simbel","Privater Ägyptologe","Frühstück unterwegs","Wasser in Flaschen"],"excluded":["Trinkgelder","Persönliche Einkäufe"],"meetingPoint":"Hotellobby in Assuan.","whatToBring":["Kamera","Bequeme Schuhe","Warme Schicht (Abfahrt vor Sonnenaufgang)","Sonnencreme"],"cancellationPolicy":"Kostenlose Stornierung bis 48 Stunden vor der Tour.","faq":[{"question":"Warum ist die Abholung so früh?","answer":"Abu Simbel liegt 280 km von Assuan entfernt und die Fahrzeuge fahren aus Sicherheitsgründen im Konvoi. Die Ankunft bei Sonnenaufgang bietet das beste Licht und den geringsten Andrang."}]}}'::jsonb, null, true, 4, 11, true, true, false, 1)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('aswan-3', 'aswan', 'Cultural & Historical', 650, 325, 3, array['English', 'Arabic']::text[], true, true, 'Aswan Nile Tours', array['https://images.unsplash.com/photo-1648139209977-61e0e6ed68b9?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1684100096410-fd39cdff91a3?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1707266327255-1f0199f22b33?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.6, 234, '[]'::jsonb, '{"en":{"title":"Nubian Village Experience","duration":"3 hours","description":"Cross the Nile by traditional felucca to visit an authentic Nubian village on the West Bank. The Nubian people have one of the world''s oldest continuous civilizations, and their painted houses, music, and traditions are unlike anything else in Egypt. Share tea and karkade with a Nubian family, see the village Nile crocodiles, and browse hand-made crafts in this warm, genuine cultural encounter.","highlights":["Traditional felucca crossing to the West Bank","Walking tour of a colorfully painted Nubian village","Cultural exchange with a Nubian family home visit","Traditional karkade tea and Nubian coffee","Live Nubian music demonstration","Interaction with the village crocodiles"],"itinerary":[{"time":"10:00","activity":"Hotel pickup"},{"time":"10:30","activity":"Board felucca — sail to Nubian village"},{"time":"11:00","activity":"Village walking tour with local guide"},{"time":"11:30","activity":"Nubian family home visit — tea and conversation"},{"time":"12:30","activity":"Music, crafts, and crocodile encounter"},{"time":"13:00","activity":"Felucca return and hotel drop-off"}],"included":["Hotel transfers","Felucca crossing","Local guide","Karkade tea","Bottled water"],"excluded":["Craft shopping","Gratuities"],"meetingPoint":"Hotel lobby in Aswan.","whatToBring":["Cash for craft shopping","Camera","Comfortable footwear"],"cancellationPolicy":"Free cancellation up to 24 hours before the experience.","faq":[]},"ar":{"title":"تجربة القرية النوبية","duration":"3 ساعات","description":"اعبر النيل بالفلوكة التقليدية لزيارة قرية نوبية أصيلة على البر الغربي. الشعب النوبي صاحب واحدة من أقدم الحضارات المستمرة في العالم، وبيوته الملونة وموسيقاه وتقاليده لا مثيل لها في مصر. تناول الشاي والكركديه مع عائلة نوبية، وشاهد تماسيح القرية، وتصفح المشغولات اليدوية في لقاء ثقافي دافئ وحقيقي.","highlights":["عبور النيل بالفلوكة التقليدية إلى البر الغربي","جولة سيرًا في قرية نوبية ببيوتها الملونة","زيارة بيت عائلة نوبية وتبادل ثقافي","كركديه تقليدي وقهوة نوبية","عرض حي للموسيقى النوبية","التعرف على تماسيح القرية"],"itinerary":[{"time":"10:00","activity":"الاستلام من الفندق"},{"time":"10:30","activity":"ركوب الفلوكة — الإبحار إلى القرية النوبية"},{"time":"11:00","activity":"جولة في القرية مع مرشد محلي"},{"time":"11:30","activity":"زيارة بيت عائلة نوبية — شاي وحديث"},{"time":"12:30","activity":"موسيقى ومشغولات يدوية والتماسيح"},{"time":"13:00","activity":"العودة بالفلوكة والتوصيل إلى الفندق"}],"included":["التنقلات من وإلى الفندق","عبور النيل بالفلوكة","مرشد محلي","كركديه","مياه معبأة"],"excluded":["شراء المشغولات اليدوية","الإكراميات"],"meetingPoint":"بهو الفندق في أسوان.","whatToBring":["نقود لشراء المشغولات","كاميرا","حذاء مريح"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل التجربة.","faq":[]},"fr":{"title":"Découverte d’un village nubien","duration":"3 heures","description":"Traversez le Nil en felouque traditionnelle pour visiter un authentique village nubien sur la rive ouest. Le peuple nubien possède l''une des plus anciennes civilisations continues du monde, et ses maisons peintes, sa musique et ses traditions sont uniques en Égypte. Partagez thé et karkadé avec une famille nubienne, voyez les crocodiles du village et découvrez l''artisanat local lors d''une rencontre chaleureuse et authentique.","highlights":["Traversée en felouque traditionnelle vers la rive ouest","Promenade dans un village nubien aux maisons colorées","Visite chez une famille nubienne et échange culturel","Karkadé traditionnel et café nubien","Démonstration de musique nubienne","Rencontre avec les crocodiles du village"],"itinerary":[{"time":"10:00","activity":"Prise en charge à l''hôtel"},{"time":"10:30","activity":"Embarquement en felouque — navigation vers le village nubien"},{"time":"11:00","activity":"Visite du village avec un guide local"},{"time":"11:30","activity":"Visite chez une famille nubienne — thé et discussion"},{"time":"12:30","activity":"Musique, artisanat et crocodiles"},{"time":"13:00","activity":"Retour en felouque et à l''hôtel"}],"included":["Transferts depuis l''hôtel","Traversée en felouque","Guide local","Karkadé","Eau en bouteille"],"excluded":["Achats d''artisanat","Pourboires"],"meetingPoint":"Hall de l''hôtel à Assouan.","whatToBring":["Espèces pour l''artisanat","Appareil photo","Chaussures confortables"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant l''expérience.","faq":[]},"de":{"title":"Erlebnis im nubischen Dorf","duration":"3 Stunden","description":"Überqueren Sie den Nil mit einer traditionellen Feluke und besuchen Sie ein authentisches nubisches Dorf am Westufer. Die Nubier haben eine der ältesten durchgehenden Kulturen der Welt, und ihre bemalten Häuser, ihre Musik und ihre Traditionen sind in Ägypten einzigartig. Trinken Sie Tee und Karkadeh mit einer nubischen Familie, sehen Sie die Krokodile des Dorfes und stöbern Sie in handgemachtem Kunsthandwerk — eine herzliche, echte Begegnung.","highlights":["Überfahrt mit der traditionellen Feluke zum Westufer","Rundgang durch ein farbenfroh bemaltes nubisches Dorf","Besuch bei einer nubischen Familie und kultureller Austausch","Traditioneller Karkadeh und nubischer Kaffee","Live-Vorführung nubischer Musik","Begegnung mit den Krokodilen des Dorfes"],"itinerary":[{"time":"10:00","activity":"Abholung vom Hotel"},{"time":"10:30","activity":"Einstieg in die Feluke — Fahrt zum nubischen Dorf"},{"time":"11:00","activity":"Dorfrundgang mit lokalem Guide"},{"time":"11:30","activity":"Besuch bei einer nubischen Familie — Tee und Gespräche"},{"time":"12:30","activity":"Musik, Kunsthandwerk und Krokodile"},{"time":"13:00","activity":"Rückfahrt mit der Feluke und Transfer zum Hotel"}],"included":["Hoteltransfers","Überfahrt mit der Feluke","Lokaler Guide","Karkadeh","Wasser in Flaschen"],"excluded":["Einkauf von Kunsthandwerk","Trinkgelder"],"meetingPoint":"Hotellobby in Assuan.","whatToBring":["Bargeld für Kunsthandwerk","Kamera","Bequemes Schuhwerk"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vorher.","faq":[]}}'::jsonb, null, true, 4, 11, true, true, false, 2)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('aswan-4', 'aswan', 'Cruises & Sailing', 450, 225, 2, array['English', 'Arabic']::text[], false, true, 'Aswan Felucca Co.', array['https://images.unsplash.com/photo-1707266327255-1f0199f22b33?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1684100096410-fd39cdff91a3?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1648139209977-61e0e6ed68b9?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.7, 521, '[]'::jsonb, '{"en":{"title":"Felucca Sunset Sail on the Nile","duration":"2 hours","description":"There is no more peaceful way to experience Aswan than a traditional felucca sail at sunset. Drift silently past granite islands, Elephantine Island, and the Botanical Garden as the sky turns gold and pink above the desert. This is the simplest and most beautiful experience on the Nile — the unhurried pace, the gentle wind, the silence.","highlights":["Traditional Egyptian felucca — no engine, pure sail","Sunset timing for extraordinary sky colors over the Nile","Views of Elephantine Island, Kitchener''s Island, and Aga Khan Mausoleum","Karkade (hibiscus tea) and fresh fruit served on board","Maximum 8 guests — intimate and peaceful"],"itinerary":[{"time":"16:30","activity":"Meet at the felucca dock near the Aswan corniche"},{"time":"16:45","activity":"Set sail — captain explains the islands"},{"time":"17:30","activity":"Reach the best sunset viewpoint — karkade and fruit served"},{"time":"18:30","activity":"Sail back to dock"}],"included":["Felucca hire","Captain","Karkade tea and fruit"],"excluded":["Hotel transfer (walking distance from most corniche hotels)","Gratuities"],"meetingPoint":"Aswan Corniche, near the Mövenpick Hotel dock. 5-minute walk from most corniche hotels.","whatToBring":["Light jacket (it cools after sunset)","Camera","Small cash for gratuity"],"cancellationPolicy":"Free cancellation up to 24 hours before the sail.","faq":[{"question":"Is this suitable for children?","answer":"Yes — felucca sailing is peaceful and safe for children of all ages. Life vests are available."}]},"ar":{"title":"رحلة فلوكة في النيل وقت الغروب","duration":"ساعتان","description":"لا توجد طريقة أهدأ للاستمتاع بأسوان من رحلة فلوكة تقليدية وقت الغروب. انساب بهدوء بين الجزر الجرانيتية وجزيرة الفنتين والحديقة النباتية بينما تتلون السماء بالذهبي والوردي فوق الصحراء. أبسط وأجمل تجربة على النيل — الإيقاع الهادئ والنسيم اللطيف والسكون.","highlights":["فلوكة مصرية تقليدية — بدون محرك، شراع فقط","توقيت الغروب لألوان سماء مذهلة فوق النيل","إطلالة على جزيرة الفنتين وجزيرة النباتات وضريح الأغاخان","كركديه وفاكهة طازجة على متن الفلوكة","8 ضيوف كحد أقصى — هادئة وخاصة"],"itinerary":[{"time":"16:30","activity":"اللقاء عند مرسى الفلوكة بجوار كورنيش أسوان"},{"time":"16:45","activity":"الإبحار — الريّس يشرح الجزر"},{"time":"17:30","activity":"الوصول لأفضل نقطة لمشاهدة الغروب — تقديم الكركديه والفاكهة"},{"time":"18:30","activity":"العودة إلى المرسى"}],"included":["إيجار الفلوكة","الريّس","كركديه وفاكهة"],"excluded":["التوصيل من الفندق (على مسافة مشي من معظم فنادق الكورنيش)","الإكراميات"],"meetingPoint":"كورنيش أسوان، بجوار مرسى فندق موفنبيك. 5 دقائق سيرًا من معظم فنادق الكورنيش.","whatToBring":["جاكيت خفيف (الجو يبرد بعد الغروب)","كاميرا","نقود قليلة للإكرامية"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الإبحار.","faq":[{"question":"هل الرحلة مناسبة للأطفال؟","answer":"نعم، رحلة الفلوكة هادئة وآمنة للأطفال من كل الأعمار، وتتوفر سترات نجاة."}]},"fr":{"title":"Balade en felouque au coucher du soleil","duration":"2 heures","description":"Il n''y a pas de façon plus paisible de découvrir Assouan qu''une balade en felouque traditionnelle au coucher du soleil. Glissez en silence entre les îles de granit, l''île Éléphantine et le Jardin botanique tandis que le ciel se teinte d''or et de rose au-dessus du désert. L''expérience la plus simple et la plus belle sur le Nil : rythme lent, brise légère, silence.","highlights":["Felouque égyptienne traditionnelle — sans moteur, uniquement à la voile","Au coucher du soleil, pour des couleurs extraordinaires sur le Nil","Vue sur l''île Éléphantine, l''île Kitchener et le mausolée de l''Aga Khan","Karkadé (thé d''hibiscus) et fruits frais servis à bord","8 personnes maximum — intime et paisible"],"itinerary":[{"time":"16:30","activity":"Rendez-vous à l''embarcadère des felouques près de la corniche"},{"time":"16:45","activity":"Départ — le capitaine présente les îles"},{"time":"17:30","activity":"Meilleur point de vue du coucher du soleil — karkadé et fruits"},{"time":"18:30","activity":"Retour à l''embarcadère"}],"included":["Location de la felouque","Capitaine","Karkadé et fruits"],"excluded":["Transfert depuis l''hôtel (à pied depuis la plupart des hôtels de la corniche)","Pourboires"],"meetingPoint":"Corniche d''Assouan, près du quai de l''hôtel Mövenpick. À 5 minutes à pied de la plupart des hôtels de la corniche.","whatToBring":["Veste légère (il fait frais après le coucher du soleil)","Appareil photo","Un peu d''espèces pour le pourboire"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la balade.","faq":[{"question":"Est-ce adapté aux enfants ?","answer":"Oui, la felouque est paisible et sûre pour les enfants de tout âge. Des gilets de sauvetage sont disponibles."}]},"de":{"title":"Feluken-Fahrt auf dem Nil bei Sonnenuntergang","duration":"2 Stunden","description":"Es gibt keine friedlichere Art, Assuan zu erleben, als eine Fahrt mit der traditionellen Feluke bei Sonnenuntergang. Gleiten Sie lautlos vorbei an Granitinseln, der Insel Elephantine und dem Botanischen Garten, während sich der Himmel über der Wüste golden und rosa färbt. Das einfachste und schönste Erlebnis auf dem Nil — gemächliches Tempo, sanfter Wind, Stille.","highlights":["Traditionelle ägyptische Feluke — kein Motor, nur Segel","Sonnenuntergang mit außergewöhnlichen Himmelsfarben über dem Nil","Blick auf die Insel Elephantine, die Kitchener-Insel und das Aga-Khan-Mausoleum","Karkadeh (Hibiskustee) und frisches Obst an Bord","Maximal 8 Gäste — persönlich und ruhig"],"itinerary":[{"time":"16:30","activity":"Treffpunkt am Feluken-Anleger an der Corniche von Assuan"},{"time":"16:45","activity":"Ablegen — der Kapitän erklärt die Inseln"},{"time":"17:30","activity":"Bester Aussichtspunkt für den Sonnenuntergang — Karkadeh und Obst"},{"time":"18:30","activity":"Rückfahrt zum Anleger"}],"included":["Feluken-Miete","Kapitän","Karkadeh und Obst"],"excluded":["Hoteltransfer (von den meisten Corniche-Hotels zu Fuß erreichbar)","Trinkgelder"],"meetingPoint":"Corniche von Assuan, nahe dem Anleger des Mövenpick-Hotels. 5 Gehminuten von den meisten Corniche-Hotels.","whatToBring":["Leichte Jacke (nach Sonnenuntergang wird es kühl)","Kamera","Etwas Bargeld für Trinkgeld"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Fahrt.","faq":[{"question":"Ist das für Kinder geeignet?","answer":"Ja, eine Feluken-Fahrt ist ruhig und sicher für Kinder jeden Alters. Schwimmwesten sind vorhanden."}]}}'::jsonb, null, true, 4, 11, true, true, false, 3)
insert into public.experiences (id, destination_id, category, price, child_price, duration_hours, tour_languages, pickup_available, free_cancellation, provider, photos, rating, review_count, reviews, content, max_guests, children_allowed, child_min_age, child_max_age, infants_allowed, published, featured, sort_order) values ('aswan-5', 'aswan', 'Cultural & Historical', 800, 400, 3, array['English', 'Arabic']::text[], true, true, 'Aswan Nile Tours', array['https://images.unsplash.com/photo-1713021714419-ca3a7bc12f00?w=1200&h=800&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1684100096410-fd39cdff91a3?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1587975844577-56dfe5d3fca8?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1559738933-d69ac3ff674b?w=800&h=560&fit=crop&auto=format&q=80', 'https://images.unsplash.com/photo-1707266327255-1f0199f22b33?w=800&h=560&fit=crop&auto=format&q=80']::text[], 4.4, 187, '[]'::jsonb, '{"en":{"title":"Aswan High Dam & Unfinished Obelisk Tour","duration":"3 hours","description":"A half-day tour combining modern and ancient engineering feats. The Aswan High Dam is one of the 20th century''s greatest infrastructure achievements — your guide explains how it transformed Egypt''s economy and agriculture while flooding Nubia. The Unfinished Obelisk in the ancient granite quarries reveals exactly how the Egyptians carved these massive monuments — abandoned 3,500 years ago mid-cut.","highlights":["Aswan High Dam — engineering wonder that reshaped modern Egypt","View over Lake Nasser — the world''s largest artificial lake","The Unfinished Obelisk — abandoned in the quarry 3,500 years ago","Insight into ancient stone-cutting and obelisk transportation techniques","Contrast of ancient and modern Egyptian ingenuity"],"itinerary":[{"time":"09:00","activity":"Hotel pickup"},{"time":"09:30","activity":"Aswan High Dam — viewpoint and guided explanation"},{"time":"10:30","activity":"Drive to the ancient granite quarries"},{"time":"11:00","activity":"The Unfinished Obelisk — full guided tour"},{"time":"12:00","activity":"Return to hotel"}],"included":["Hotel transfers","Entry fees","Guide","Bottled water"],"excluded":["Gratuities"],"meetingPoint":"Hotel lobby in Aswan.","whatToBring":["Comfortable shoes","Sun hat","Camera"],"cancellationPolicy":"Free cancellation up to 24 hours before the tour.","faq":[]},"ar":{"title":"جولة السد العالي والمسلة الناقصة","duration":"3 ساعات","description":"جولة نصف يوم تجمع بين إنجازات هندسية حديثة وقديمة. السد العالي من أعظم مشروعات البنية التحتية في القرن العشرين، وسيشرح لك المرشد كيف غيّر اقتصاد مصر وزراعتها بينما غمر بلاد النوبة. وتكشف المسلة الناقصة في محاجر الجرانيت القديمة كيف نحت المصريون هذه الآثار الضخمة — وقد تُركت في منتصف النحت منذ 3500 عام.","highlights":["السد العالي — معجزة هندسية غيّرت مصر الحديثة","إطلالة على بحيرة ناصر — من أكبر البحيرات الصناعية في العالم","المسلة الناقصة — متروكة في المحجر منذ 3500 عام","تعرّف على طرق قطع الحجر ونقل المسلات قديمًا","مقارنة بين عبقرية المصريين قديمًا وحديثًا"],"itinerary":[{"time":"09:00","activity":"الاستلام من الفندق"},{"time":"09:30","activity":"السد العالي — نقطة المشاهدة والشرح"},{"time":"10:30","activity":"الانتقال إلى محاجر الجرانيت القديمة"},{"time":"11:00","activity":"المسلة الناقصة — جولة كاملة مع المرشد"},{"time":"12:00","activity":"العودة إلى الفندق"}],"included":["التنقلات من وإلى الفندق","رسوم الدخول","مرشد","مياه معبأة"],"excluded":["الإكراميات"],"meetingPoint":"بهو الفندق في أسوان.","whatToBring":["حذاء مريح","قبعة شمس","كاميرا"],"cancellationPolicy":"إلغاء مجاني حتى 24 ساعة قبل الجولة.","faq":[]},"fr":{"title":"Haut barrage d''Assouan et obélisque inachevé","duration":"3 heures","description":"Une demi-journée qui réunit prouesses d''ingénierie modernes et antiques. Le haut barrage d''Assouan est l''une des plus grandes réalisations du XXe siècle ; votre guide explique comment il a transformé l''économie et l''agriculture égyptiennes tout en submergeant la Nubie. L''obélisque inachevé, dans les anciennes carrières de granit, révèle comment les Égyptiens taillaient ces monuments colossaux — abandonné en cours de taille il y a 3 500 ans.","highlights":["Le haut barrage — prouesse technique qui a transformé l''Égypte moderne","Vue sur le lac Nasser, l''un des plus grands lacs artificiels du monde","L''obélisque inachevé — abandonné dans la carrière il y a 3 500 ans","Les techniques antiques de taille de la pierre et de transport des obélisques","Le contraste entre génie égyptien ancien et moderne"],"itinerary":[{"time":"09:00","activity":"Prise en charge à l''hôtel"},{"time":"09:30","activity":"Haut barrage — point de vue et explications"},{"time":"10:30","activity":"Route vers les anciennes carrières de granit"},{"time":"11:00","activity":"L''obélisque inachevé — visite guidée complète"},{"time":"12:00","activity":"Retour à l''hôtel"}],"included":["Transferts depuis l''hôtel","Droits d''entrée","Guide","Eau en bouteille"],"excluded":["Pourboires"],"meetingPoint":"Hall de l''hôtel à Assouan.","whatToBring":["Chaussures confortables","Chapeau","Appareil photo"],"cancellationPolicy":"Annulation gratuite jusqu''à 24 heures avant la visite.","faq":[]},"de":{"title":"Assuan-Hochdamm und unvollendeter Obelisk","duration":"3 Stunden","description":"Eine Halbtagestour, die moderne und antike Ingenieurskunst verbindet. Der Assuan-Hochdamm ist eine der größten Infrastrukturleistungen des 20. Jahrhunderts — Ihr Guide erklärt, wie er Ägyptens Wirtschaft und Landwirtschaft veränderte und zugleich Nubien überflutete. Der unvollendete Obelisk in den antiken Granitsteinbrüchen zeigt genau, wie die Ägypter diese gewaltigen Monumente schufen — vor 3.500 Jahren mitten in der Arbeit aufgegeben.","highlights":["Assuan-Hochdamm — ein technisches Wunder, das das moderne Ägypten prägte","Blick auf den Nassersee, einen der größten Stauseen der Welt","Der unvollendete Obelisk — vor 3.500 Jahren im Steinbruch zurückgelassen","Einblicke in antike Steinbearbeitung und den Transport von Obelisken","Der Kontrast zwischen altem und modernem ägyptischem Erfindungsgeist"],"itinerary":[{"time":"09:00","activity":"Abholung vom Hotel"},{"time":"09:30","activity":"Assuan-Hochdamm — Aussichtspunkt und Erklärungen"},{"time":"10:30","activity":"Fahrt zu den antiken Granitsteinbrüchen"},{"time":"11:00","activity":"Der unvollendete Obelisk — ausführliche Führung"},{"time":"12:00","activity":"Rückfahrt zum Hotel"}],"included":["Hoteltransfers","Eintrittsgelder","Guide","Wasser in Flaschen"],"excluded":["Trinkgelder"],"meetingPoint":"Hotellobby in Assuan.","whatToBring":["Bequeme Schuhe","Sonnenhut","Kamera"],"cancellationPolicy":"Kostenlose Stornierung bis 24 Stunden vor der Tour.","faq":[]}}'::jsonb, null, true, 4, 11, true, true, false, 4)
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-1', 'Anna M.', 'Germany', 5, 'Absolutely breathtaking. The astronomer knew the sky so well and made it feel like a personal discovery. The Milky Way was visible with the naked eye — I had never seen anything like it.', 'December 2024', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-1' and name = 'Anna M.' and comment = 'Absolutely breathtaking. The astronomer knew the sky so well and made it feel like a personal discovery. The Milky Way was visible with the naked eye — I had never seen anything like it.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-1', 'James T.', 'United Kingdom', 5, 'The highlight of our entire Egypt trip. Small group, excellent guide, and the telescope views of Saturn''s rings left our kids speechless. Highly recommended.', 'January 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-1' and name = 'James T.' and comment = 'The highlight of our entire Egypt trip. Small group, excellent guide, and the telescope views of Saturn''s rings left our kids speechless. Highly recommended.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-1', 'Sophie B.', 'France', 4, 'Magical experience. The Bedouin tea around the campfire was a lovely touch. Docking one star only because pickup was slightly late, but otherwise perfect.', 'November 2024', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-1' and name = 'Sophie B.' and comment = 'Magical experience. The Bedouin tea around the campfire was a lovely touch. Docking one star only because pickup was slightly late, but otherwise perfect.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-2', 'Maria K.', 'Poland', 5, 'Perfect day out. Orange Bay truly is a paradise — turquoise water, white sand, colorful fish everywhere. The crew was friendly and the food was great.', 'March 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-2' and name = 'Maria K.' and comment = 'Perfect day out. Orange Bay truly is a paradise — turquoise water, white sand, colorful fish everywhere. The crew was friendly and the food was great.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-2', 'David L.', 'USA', 4, 'Really enjoyed this trip. The coral was stunning and we saw a sea turtle! Boat was comfortable. Slightly crowded at Orange Bay but still beautiful.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-2' and name = 'David L.' and comment = 'Really enjoyed this trip. The coral was stunning and we saw a sea turtle! Boat was comfortable. Slightly crowded at Orange Bay but still beautiful.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-3', 'Lena S.', 'Germany', 5, 'We swam with an entire pod of dolphins for 20 minutes. This was a dream come true. The yacht was luxurious, the crew was wonderful, and the seafood lunch was delicious.', 'January 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-3' and name = 'Lena S.' and comment = 'We swam with an entire pod of dolphins for 20 minutes. This was a dream come true. The yacht was luxurious, the crew was wonderful, and the seafood lunch was delicious.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-3', 'Oliver W.', 'Australia', 5, 'Absolutely the best day of our entire Egypt trip. The dolphins came right up to us. Incredible experience — worth every penny.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-3' and name = 'Oliver W.' and comment = 'Absolutely the best day of our entire Egypt trip. The dolphins came right up to us. Incredible experience — worth every penny.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-4', 'Charlotte & Thomas R.', 'Switzerland', 5, 'Booked for our honeymoon and it was simply perfect. Every detail was considered, the chef was exceptional, and the crew made us feel like royalty. An unforgettable day.', 'March 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-4' and name = 'Charlotte & Thomas R.' and comment = 'Booked for our honeymoon and it was simply perfect. Every detail was considered, the chef was exceptional, and the crew made us feel like royalty. An unforgettable day.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-5', 'Piotr K.', 'Poland', 5, 'So much fun! The dunes were incredible and the Bedouin camp at sunset was magical. Great value and great guides.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-5' and name = 'Piotr K.' and comment = 'So much fun! The dunes were incredible and the Bedouin camp at sunset was magical. Great value and great guides.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'hurg-5', 'Elena V.', 'Russia', 4, 'Really enjoyable experience. The route was varied and the views were stunning. Quad bikes were well-maintained.', 'January 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'hurg-5' and name = 'Elena V.' and comment = 'Really enjoyable experience. The route was varied and the views were stunning. Quad bikes were well-maintained.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'sharm-1', 'Natalia Z.', 'Russia', 5, 'The coral at Ras Mohammed is unbelievably beautiful. I saw a reef shark, two turtles, and more species of fish than I could count. World class.', 'March 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'sharm-1' and name = 'Natalia Z.' and comment = 'The coral at Ras Mohammed is unbelievably beautiful. I saw a reef shark, two turtles, and more species of fish than I could count. World class.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'sharm-2', 'Aleksandra B.', 'Poland', 5, 'White Island is absolutely magical. The water is every shade of blue and the snorkeling was spectacular. One of the best days of my life.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'sharm-2' and name = 'Aleksandra B.' and comment = 'White Island is absolutely magical. The water is every shade of blue and the snorkeling was spectacular. One of the best days of my life.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'sharm-3', 'Marco R.', 'Italy', 5, 'The desert around Sharm is stunningly beautiful — craggy red mountains and desert silence. The Bedouin camp at sunset was a lovely ending. Great fun.', 'January 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'sharm-3' and name = 'Marco R.' and comment = 'The desert around Sharm is stunningly beautiful — craggy red mountains and desert silence. The Bedouin camp at sunset was a lovely ending. Great fun.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'sharm-4', 'Yulia M.', 'Russia', 5, 'I was terrified to try diving but our instructor was calm, patient, and incredibly professional. The reef was extraordinary. I am now a certified diver because of this experience.', 'March 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'sharm-4' and name = 'Yulia M.' and comment = 'I was terrified to try diving but our instructor was calm, patient, and incredibly professional. The reef was extraordinary. I am now a certified diver because of this experience.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'sharm-5', 'Joanna K.', 'Poland', 5, 'Absolutely exhilarating. The view of the Red Sea from above is stunning and the GoPro footage is brilliant. Over too soon but 100% worth it!', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'sharm-5' and name = 'Joanna K.' and comment = 'Absolutely exhilarating. The view of the Red Sea from above is stunning and the GoPro footage is brilliant. Over too soon but 100% worth it!');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'cairo-1', 'Michael H.', 'USA', 5, 'Our guide was extraordinary — her knowledge was encyclopaedic and her passion for Egyptology was infectious. The Tutankhamun collection left us speechless. Essential.', 'March 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'cairo-1' and name = 'Michael H.' and comment = 'Our guide was extraordinary — her knowledge was encyclopaedic and her passion for Egyptology was infectious. The Tutankhamun collection left us speechless. Essential.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'cairo-1', 'Giulia M.', 'Italy', 5, 'The private guide made all the difference. We understood context and meaning that you simply can''t get from a sign on a wall. The best museum experience I''ve ever had.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'cairo-1' and name = 'Giulia M.' and comment = 'The private guide made all the difference. We understood context and meaning that you simply can''t get from a sign on a wall. The best museum experience I''ve ever had.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'cairo-2', 'Sarah J.', 'United Kingdom', 5, 'Seeing the pyramids was on my bucket list for 30 years. Our guide brought them alive in a way I never expected. Private tour was absolutely worth it.', 'January 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'cairo-2' and name = 'Sarah J.' and comment = 'Seeing the pyramids was on my bucket list for 30 years. Our guide brought them alive in a way I never expected. Private tour was absolutely worth it.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'cairo-2', 'Kazimiera W.', 'Poland', 5, 'Perfect tour from start to finish. The early morning timing meant no crowds at the Sphinx. Our guide was brilliant and incredibly knowledgeable.', 'December 2024', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'cairo-2' and name = 'Kazimiera W.' and comment = 'Perfect tour from start to finish. The early morning timing meant no crowds at the Sphinx. Our guide was brilliant and incredibly knowledgeable.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'cairo-3', 'Francesco B.', 'Italy', 5, 'The best walking tour I''ve ever taken, anywhere. Our guide knew every alley, every story, every hidden door. Khan el-Khalili was fascinating with his guidance.', 'March 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'cairo-3' and name = 'Francesco B.' and comment = 'The best walking tour I''ve ever taken, anywhere. Our guide knew every alley, every story, every hidden door. Khan el-Khalili was fascinating with his guidance.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'cairo-4', 'Thomas G.', 'Germany', 4, 'Lovely evening on the Nile. The food was good, the performances were entertaining, and the views were beautiful. A classic Cairo experience.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'cairo-4' and name = 'Thomas G.' and comment = 'Lovely evening on the Nile. The food was good, the performances were entertaining, and the views were beautiful. A classic Cairo experience.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'cairo-5', 'Andrew P.', 'Canada', 5, 'Far better than Giza in my opinion. The tombs at Saqqara are breathtaking — the murals look freshly painted. We were virtually alone at Dahshur. Extraordinary.', 'January 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'cairo-5' and name = 'Andrew P.' and comment = 'Far better than Giza in my opinion. The tombs at Saqqara are breathtaking — the murals look freshly painted. We were virtually alone at Dahshur. Extraordinary.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'luxor-1', 'Helena K.', 'Czech Republic', 5, 'Walking into a 3,200-year-old royal tomb is genuinely humbling. Our guide explained every scene on every wall. One of the greatest experiences of my life.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'luxor-1' and name = 'Helena K.' and comment = 'Walking into a 3,200-year-old royal tomb is genuinely humbling. Our guide explained every scene on every wall. One of the greatest experiences of my life.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'luxor-2', 'Laura C.', 'USA', 5, 'Watching the sun rise over the temples of Luxor from a balloon was the most beautiful thing I have ever seen. Totally silent, totally magical. Book this.', 'March 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'luxor-2' and name = 'Laura C.' and comment = 'Watching the sun rise over the temples of Luxor from a balloon was the most beautiful thing I have ever seen. Totally silent, totally magical. Book this.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'luxor-2', 'Tobias F.', 'Germany', 5, 'The undisputed highlight of our Egypt trip. The scale of Karnak Temple from above is humbling. The champagne on landing was a lovely touch.', 'January 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'luxor-2' and name = 'Tobias F.' and comment = 'The undisputed highlight of our Egypt trip. The scale of Karnak Temple from above is humbling. The champagne on landing was a lovely touch.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'luxor-3', 'Sandra N.', 'Netherlands', 5, 'The hypostyle hall at sunset was genuinely overwhelming. The scale of it, the light, the carvings — extraordinary. Our guide was passionate and knowledgeable.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'luxor-3' and name = 'Sandra N.' and comment = 'The hypostyle hall at sunset was genuinely overwhelming. The scale of it, the light, the carvings — extraordinary. Our guide was passionate and knowledgeable.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'luxor-4', 'Patrick D.', 'Ireland', 5, 'Seeing Luxor Temple lit up at night was one of the most beautiful things I''ve ever witnessed. The photos do not do it justice. Do not miss this.', 'March 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'luxor-4' and name = 'Patrick D.' and comment = 'Seeing Luxor Temple lit up at night was one of the most beautiful things I''ve ever witnessed. The photos do not do it justice. Do not miss this.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'luxor-5', 'Rebecca M.', 'New Zealand', 5, 'The painted walls at Abydos look like they were done last week. Unbelievably vivid and beautiful. Dendera is magnificent. This tour is for serious Egypt lovers.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'luxor-5' and name = 'Rebecca M.' and comment = 'The painted walls at Abydos look like they were done last week. Unbelievably vivid and beautiful. Dendera is magnificent. This tour is for serious Egypt lovers.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'aswan-1', 'Monika R.', 'Poland', 5, 'Philae at sunset is simply one of the most beautiful things I''ve ever seen. An island temple, glowing pink in the last light, reflected in the Nile. Perfection.', 'January 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'aswan-1' and name = 'Monika R.' and comment = 'Philae at sunset is simply one of the most beautiful things I''ve ever seen. An island temple, glowing pink in the last light, reflected in the Nile. Perfection.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'aswan-2', 'Christopher B.', 'United Kingdom', 5, 'The four statues of Ramesses are simply staggering in scale. Nothing prepares you for this. The early start was absolutely worth it. A once-in-a-lifetime experience.', 'March 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'aswan-2' and name = 'Christopher B.' and comment = 'The four statues of Ramesses are simply staggering in scale. Nothing prepares you for this. The early start was absolutely worth it. A once-in-a-lifetime experience.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'aswan-3', 'Elisa V.', 'Italy', 4, 'A very different side of Egypt. The Nubian people are warm and welcoming and the painted houses are beautiful. Lovely way to spend a morning.', 'February 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'aswan-3' and name = 'Elisa V.' and comment = 'A very different side of Egypt. The Nubian people are warm and welcoming and the painted houses are beautiful. Lovely way to spend a morning.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'aswan-4', 'Nadia P.', 'France', 5, 'The most serene two hours of our entire Egypt trip. No engine, no noise — just wind, water, and the most beautiful sunset you''ve ever seen. Perfect.', 'January 2025', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'aswan-4' and name = 'Nadia P.' and comment = 'The most serene two hours of our entire Egypt trip. No engine, no noise — just wind, water, and the most beautiful sunset you''ve ever seen. Perfect.');
insert into public.reviews (experience_id, name, country, rating, comment, date_label, status, source) select 'aswan-5', 'Erik H.', 'Sweden', 4, 'The Unfinished Obelisk is fascinating — it completely changed how I think about the pyramids and what the ancient Egyptians achieved. Very informative tour.', 'December 2024', 'approved', 'imported' where not exists (select 1 from public.reviews where experience_id = 'aswan-5' and name = 'Erik H.' and comment = 'The Unfinished Obelisk is fascinating — it completely changed how I think about the pyramids and what the ancient Egyptians achieved. Very informative tour.');
